// static
bool LLPipeline::isMainWorldPass()
{
    return !sShadowRender && !sImpostorRender && !sRenderingHUDs && !gCubeSnapshot
        && LLViewerCamera::sCurCameraID == LLViewerCamera::CAMERA_WORLD;
}

#if LL_DARWIN
bool LLPipeline::isMetalWorldCapturePass() const
{
    return isMainWorldPass() ||
        (mMetalHeroWorldCaptureActive && gCubeSnapshot &&
         mHeroProbeManager.isMirrorPass() && mRT == &mHeroProbeRT) ||
        (mMetalReflectionWorldCaptureActive && gCubeSnapshot &&
         mRT == &mAuxillaryRT);
}

#endif

// static
bool LLPipeline::suppressesLensAndPrintEffects()
{
    return gSnapshotNoPost || sCutoutRender;
}

