    ALMetalWorldSpotShadowBatch* appendSeparateShadowBatch(U32 source_line)
    {
        if (spot_shadow_admission.admitSeparate())
        {
            try
            {
                return &spot_shadow_batches.emplace_back();
            }
            catch (...)
            {
                spot_shadow_admission.invalidate();
                spot_shadow_capture_complete = false;
                throw;
            }
        }
        spot_shadow_first_incomplete_source_line = source_line;
        spot_shadow_capture_complete = false;
        spot_shadow_batches.clear();
        return nullptr;
    }

    void markIncomplete(U32 source_line)
    {
        if ((impostor_bake || impostor_alpha_active) &&
            impostor_bake_first_incomplete_line == 0)
        {
            impostor_bake_first_incomplete_line = source_line;
        }
        if (complete)
        {
            first_incomplete_source_line = source_line;
        }
        complete = false;
    }

    void resetCompleteness()
    {
        complete = true;
        first_incomplete_source_line = 0;
    }

    bool beginFrameData(const MetalWorldSimpleCapture* other, U64 frame)
    {
        if (!device || !renderer)
        {
            return false;
        }
        if (!frame_data && other && other->device == device)
        {
            frame_data = other->frame_data;
        }
        if (!frame_data)
        {
            std::string error;
            frame_data = ALMetalWorldFrameData::create(*device, &error);
            if (!frame_data)
            {
                LL_WARNS("Metal")
                    << "Could not prepare native frame data: " << error
                    << LL_ENDL;
                return false;
            }
        }
        // Main, hero and ordinary-probe owners swap slots, but all views in
        // this viewer frame share immutable data and completion-safe pages.
        // Repeated beginFrame calls for the same generation do not retire it.
        frame_data->beginFrame(frame);
        renderer->setFrameData(frame_data);
        return true;
    }

