void LLPipeline::beginMetalWorldAvatarPass(
    bool skinned, bool cloth, const F32* wind, const F32* sin_wave,
    const F32* gravity, const F32* cloth_depth, bool direct_alpha)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active || (cloth && !skinned) ||
        (cloth && (!wind || !sin_wave || !gravity || !cloth_depth)))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.avatar_palettes.clear();
        return;
    }
    const bool avatar_alpha = capture.world_post_deferred_active &&
        !capture.world_post_deferred_phase;
    if (direct_alpha && !avatar_alpha)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.avatar_palettes.clear();
        return;
    }
    if (avatar_alpha)
    {
        if ((!capture.alpha_environment_valid &&
             !fillMetalWorldAlphaEnvironment(capture.alpha_environment)) ||
            (!capture.world_alpha_lighting_valid &&
             !fillMetalWorldAlphaLighting(capture.world_alpha_lighting)))
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            capture.avatar_palettes.clear();
            return;
        }
        capture.alpha_environment_valid = true;
        capture.world_alpha_lighting_valid = true;
        const bool uses_shadows =
            LLViewerShaderMgr::instance()->getShaderLevel(
                LLViewerShaderMgr::SHADER_DEFERRED) > 1 &&
            shaderInputs().mGlobal.mShadowDetail > 0;
        if (uses_shadows && !fillMetalImpostorDirectionalShadows())
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            capture.avatar_palettes.clear();
            return;
        }
        capture.world_alpha_uses_shadows =
            capture.world_alpha_uses_shadows ||
            (uses_shadows &&
             capture.impostor_directional_shadows.depth_texture != nullptr);
    }
    capture.rigged = false;
    capture.alpha_mask = true;
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
    capture.pbr = false;
    capture.terrain = false;
    capture.avatar = true;
    capture.impostor = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
    capture.avatar_skinned = skinned;
    capture.avatar_cloth = cloth;
    capture.direct_avatar_alpha = direct_alpha;
    capture.direct_avatar_alpha_state_active = false;
    std::memset(capture.avatar_wind, 0, sizeof(capture.avatar_wind));
    std::memset(capture.avatar_sin_wave, 0,
                sizeof(capture.avatar_sin_wave));
    std::memset(capture.avatar_gravity, 0,
                sizeof(capture.avatar_gravity));
    std::memset(capture.avatar_cloth_depth, 0,
                sizeof(capture.avatar_cloth_depth));
    if (cloth)
    {
        std::memcpy(capture.avatar_wind, wind,
                    sizeof(capture.avatar_wind));
        std::memcpy(capture.avatar_sin_wave, sin_wave,
                    sizeof(capture.avatar_sin_wave));
        std::memcpy(capture.avatar_gravity, gravity,
                    sizeof(capture.avatar_gravity));
        std::memcpy(capture.avatar_cloth_depth, cloth_depth,
                    sizeof(capture.avatar_cloth_depth));
    }
    capture.pass_active = true;
}

void LLPipeline::setMetalWorldAvatarAlphaState(
    bool cull, bool front, bool depth_write, bool color_write)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active)
    {
        // The retained avatar pool still traverses while a native
        // post-deferred transaction is temporarily ineligible (for example,
        // while the first reflection-probe pack is warming after a live
        // quality-preset change).  Its transparent-mesh callbacks are then
        // observation-only.  Do not poison the next native retry merely
        // because there is no transaction for this state to belong to.
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.pass_active || !capture.avatar ||
        !capture.direct_avatar_alpha ||
        !capture.world_post_deferred_active ||
        capture.world_post_deferred_phase)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.avatar_palettes.clear();
        return;
    }
    capture.direct_avatar_alpha_cull_mode = !cull
        ? ALMetalCullMode::none
        : (front ? ALMetalCullMode::front : ALMetalCullMode::back);
    capture.direct_avatar_alpha_depth_write = depth_write;
    capture.direct_avatar_alpha_color_write = color_write;
    capture.direct_avatar_alpha_state_active = true;
}

