void LLPipeline::captureMetalReflectionProbeVolumes()
{
    if (!mMetalWorldSimpleCapture || !sReflectionProbesEnabled ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete)
    {
        return;
    }
    if (capture.reflection_probe_volume_valid ||
        !mReflectionMapManager.fillMetalReflectionProbeConstants(
            capture.reflection_probe_volume_constants))
    {
        capture.markIncomplete(__LINE__);
        capture.reflection_probe_volume_valid = false;
        return;
    }

    LLMatrix4a inverse_projection;
    inverse_projection.setInverse(
        LLViewerCamera::getCurrent().getProjection());
    std::memcpy(capture.reflection_probe_volume_inverse_projection,
                inverse_projection.getF32ptr(),
                sizeof(capture.reflection_probe_volume_inverse_projection));
    capture.reflection_probe_volume_valid = true;
}

void LLPipeline::beginMetalWindVectorCapture(std::size_t vector_count)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || capture.wind_vector_capture_active ||
        !capture.wind_vector_points.empty() ||
        !capture.wind_vector_lines.empty() ||
        vector_count > std::numeric_limits<std::size_t>::max() / 2)
    {
        capture.markIncomplete(__LINE__);
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    std::memcpy(capture.wind_vector_modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(capture.wind_vector_modelview_projection));
    try
    {
        capture.wind_vector_points.reserve(vector_count);
        capture.wind_vector_lines.reserve(vector_count * 2);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.wind_vector_points.clear();
        capture.wind_vector_lines.clear();
        return;
    }
    capture.wind_vector_capture_active = true;
}

void LLPipeline::captureMetalWindVector(const LLVector3& point,
                                        const LLVector3& line_start,
                                        const LLVector3& line_end)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || !capture.wind_vector_capture_active)
    {
        return;
    }

    ALMetalWorldWindVectorVertex point_vertex;
    ALMetalWorldWindVectorVertex line_vertices[2];
    std::memcpy(point_vertex.position, point.mV, sizeof(point.mV));
    point_vertex.color[0] = 0.f;
    point_vertex.color[1] = 1.f;
    point_vertex.color[2] = 0.f;
    std::memcpy(line_vertices[0].position, line_start.mV,
                sizeof(line_start.mV));
    std::memcpy(line_vertices[1].position, line_end.mV,
                sizeof(line_end.mV));
    for (ALMetalWorldWindVectorVertex& vertex : line_vertices)
    {
        vertex.color[0] = 1.f;
        vertex.color[1] = 0.f;
        vertex.color[2] = 0.f;
    }
    try
    {
        capture.wind_vector_points.push_back(point_vertex);
        capture.wind_vector_lines.push_back(line_vertices[0]);
        capture.wind_vector_lines.push_back(line_vertices[1]);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.wind_vector_points.clear();
        capture.wind_vector_lines.clear();
        capture.wind_vector_capture_active = false;
    }
}

void LLPipeline::endMetalWindVectorCapture(std::size_t vector_count)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.wind_vector_capture_active)
    {
        return;
    }
    capture.wind_vector_capture_active = false;
    if (!capture.complete ||
        capture.wind_vector_points.size() != vector_count ||
        vector_count > std::numeric_limits<std::size_t>::max() / 2 ||
        capture.wind_vector_lines.size() != vector_count * 2)
    {
        capture.markIncomplete(__LINE__);
        capture.wind_vector_points.clear();
        capture.wind_vector_lines.clear();
    }
}

void LLPipeline::beginMetalAgentTargetCapture(
    std::size_t crosshair_count)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    bool color_mask[4]{};
    gGL.getColorMask(color_mask);
    constexpr std::size_t expected_crosshair_count = 4;
    constexpr std::size_t vertices_per_crosshair = 6;
    if (!capture.complete || capture.agent_target_capture_active ||
        !capture.agent_target_lines.empty() ||
        crosshair_count != expected_crosshair_count ||
        crosshair_count >
            std::numeric_limits<std::size_t>::max() /
                vertices_per_crosshair ||
        !LLGLState::isEnabled(GL_BLEND) ||
        !LLGLDepthTest::depthEnabled() ||
        !LLGLDepthTest::depthWriteEnabled() ||
        LLGLDepthTest::depthFunction() != GL_LEQUAL ||
        capture.render_debug_order ==
            std::numeric_limits<U64>::max() ||
        !color_mask[0] || !color_mask[1] || !color_mask[2] || color_mask[3])
    {
        capture.markIncomplete(__LINE__);
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    std::memcpy(capture.agent_target_modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(capture.agent_target_modelview_projection));
    try
    {
        capture.agent_target_lines.reserve(
            crosshair_count * vertices_per_crosshair);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.agent_target_lines.clear();
        return;
    }
    capture.agent_target_order = capture.render_debug_order++;
    capture.agent_target_capture_active = true;
}

void LLPipeline::captureMetalAgentTargetCrosshair(
    const LLVector3& position, F32 size, const LLColor4& color)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || !capture.agent_target_capture_active)
    {
        return;
    }

    const LLVector3 positions[6] = {
        position - LLVector3(size, 0.f, 0.f),
        position + LLVector3(size, 0.f, 0.f),
        position - LLVector3(0.f, size, 0.f),
        position + LLVector3(0.f, size, 0.f),
        position - LLVector3(0.f, 0.f, size),
        position + LLVector3(0.f, 0.f, size),
    };
    try
    {
        for (const LLVector3& line_position : positions)
        {
            ALMetalWorldAgentTargetVertex vertex;
            std::memcpy(vertex.position, line_position.mV,
                        sizeof(line_position.mV));
            std::memcpy(vertex.color, color.mV, sizeof(color.mV));
            capture.agent_target_lines.push_back(vertex);
        }
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.agent_target_lines.clear();
        capture.agent_target_capture_active = false;
    }
}

void LLPipeline::endMetalAgentTargetCapture(
    std::size_t crosshair_count)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.agent_target_capture_active)
    {
        return;
    }
    capture.agent_target_capture_active = false;
    constexpr std::size_t expected_crosshair_count = 4;
    constexpr std::size_t vertices_per_crosshair = 6;
    if (!capture.complete ||
        crosshair_count != expected_crosshair_count ||
        crosshair_count >
            std::numeric_limits<std::size_t>::max() /
                vertices_per_crosshair ||
        capture.agent_target_lines.size() !=
            crosshair_count * vertices_per_crosshair)
    {
        capture.markIncomplete(__LINE__);
        capture.agent_target_lines.clear();
    }
}

void LLPipeline::beginMetalAvatarVolumeCapture(
    std::size_t collision_volume_count)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    constexpr std::size_t pairs_per_volume = 2;
    const bool count_overflows = collision_volume_count >
        std::numeric_limits<std::size_t>::max() / pairs_per_volume;
    const std::size_t pair_count = count_overflows
        ? 0 : collision_volume_count * pairs_per_volume;
    const bool reserve_overflows = !count_overflows &&
        pair_count > std::numeric_limits<std::size_t>::max() -
            capture.avatar_volume_batches.size();
    if (!capture.complete || capture.avatar_volume_capture_active ||
        capture.avatar_joint_capture_active ||
        capture.avatar_volume_pair_active || count_overflows ||
        reserve_overflows ||
        pair_count > std::numeric_limits<U64>::max() -
            capture.render_debug_order)
    {
        capture.markIncomplete(__LINE__);
        return;
    }

    capture.avatar_volume_capture_first =
        capture.avatar_volume_batches.size();
    capture.avatar_volume_expected_pairs = pair_count;
    try
    {
        capture.avatar_volume_batches.reserve(
            capture.avatar_volume_batches.size() + pair_count);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.avatar_volume_batches.clear();
        return;
    }
    capture.avatar_volume_capture_active = true;
}

void LLPipeline::beginMetalAvatarVolumePair(
    const LLVector3& end, F32 sphere_scale,
    const LLVector3& occluded_color,
    const LLVector3& visible_color)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool volume_capture = capture.avatar_volume_capture_active;
    const bool joint_capture = capture.avatar_joint_capture_active;
    if (!volume_capture && !joint_capture)
    {
        return;
    }

    const std::size_t captured_pairs = volume_capture
        ? capture.avatar_volume_batches.size() -
              capture.avatar_volume_capture_first
        : capture.avatar_joint_captured_segments;
    const std::size_t expected_pairs = volume_capture
        ? capture.avatar_volume_expected_pairs
        : capture.avatar_joint_expected_segments;
    if (!capture.complete || capture.avatar_volume_pair_active ||
        captured_pairs >= expected_pairs)
    {
        capture.markIncomplete(__LINE__);
        return;
    }

    capture.avatar_volume_batch = {};
    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    std::memcpy(
        capture.avatar_volume_batch.line_modelview_projection,
        modelview_projection.getF32ptr(),
        sizeof(capture.avatar_volume_batch.line_modelview_projection));
    std::memcpy(capture.avatar_volume_batch.end, end.mV, sizeof(end.mV));
    capture.avatar_volume_batch.end[3] = 1.f;
    std::memcpy(capture.avatar_volume_batch.visible_color,
                visible_color.mV, sizeof(visible_color.mV));
    capture.avatar_volume_batch.visible_color[3] = 1.f;
    std::memcpy(capture.avatar_volume_batch.occluded_color,
                occluded_color.mV, sizeof(occluded_color.mV));
    capture.avatar_volume_batch.occluded_color[3] = 1.f;
    capture.avatar_volume_batch.sphere_scale = sphere_scale;
    capture.avatar_volume_batch.order = capture.render_debug_order++;
    capture.avatar_volume_sphere_transform_captured = false;
    capture.avatar_volume_pair_active = true;
}

void LLPipeline::captureMetalAvatarVolumeSphereTransform()
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.avatar_volume_pair_active)
    {
        return;
    }
    if (!capture.complete ||
        capture.avatar_volume_sphere_transform_captured)
    {
        capture.markIncomplete(__LINE__);
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    std::memcpy(
        capture.avatar_volume_batch.sphere_modelview_projection,
        modelview_projection.getF32ptr(),
        sizeof(capture.avatar_volume_batch.sphere_modelview_projection));
    capture.avatar_volume_sphere_transform_captured = true;
}

void LLPipeline::endMetalAvatarVolumePair()
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.avatar_volume_pair_active)
    {
        return;
    }

    const bool state_valid = capture.complete &&
        capture.avatar_volume_sphere_transform_captured;
    if (state_valid && capture.avatar_volume_capture_active)
    {
        try
        {
            capture.avatar_volume_batches.push_back(
                capture.avatar_volume_batch);
        }
        catch (const std::bad_alloc&)
        {
            capture.markIncomplete(__LINE__);
        }
    }
    else if (state_valid && capture.avatar_joint_capture_active)
    {
        ALMetalWorldAvatarJointBatch joint_batch;
        joint_batch.kind = ALMetalWorldAvatarJointKind::segment;
        std::memcpy(
            joint_batch.line_modelview_projection,
            capture.avatar_volume_batch.line_modelview_projection,
            sizeof(joint_batch.line_modelview_projection));
        std::memcpy(
            joint_batch.sphere_modelview_projection,
            capture.avatar_volume_batch.sphere_modelview_projection,
            sizeof(joint_batch.sphere_modelview_projection));
        std::memcpy(joint_batch.end, capture.avatar_volume_batch.end,
                    sizeof(joint_batch.end));
        std::memcpy(
            joint_batch.visible_color,
            capture.avatar_volume_batch.visible_color,
            sizeof(joint_batch.visible_color));
        std::memcpy(
            joint_batch.occluded_color,
            capture.avatar_volume_batch.occluded_color,
            sizeof(joint_batch.occluded_color));
        joint_batch.sphere_scale =
            capture.avatar_volume_batch.sphere_scale;
        joint_batch.order = capture.avatar_volume_batch.order;
        try
        {
            capture.avatar_joint_batches.push_back(joint_batch);
            ++capture.avatar_joint_captured_segments;
        }
        catch (const std::bad_alloc&)
        {
            capture.markIncomplete(__LINE__);
        }
    }
    else
    {
        capture.markIncomplete(__LINE__);
    }
    capture.avatar_volume_batch = {};
    capture.avatar_volume_pair_active = false;
    capture.avatar_volume_sphere_transform_captured = false;
}

void LLPipeline::beginMetalAvatarJointCapture(
    std::size_t skeleton_segment_count)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool reserve_overflows = skeleton_segment_count >
        std::numeric_limits<std::size_t>::max() -
            capture.avatar_joint_batches.size();
    if (!capture.complete || capture.avatar_volume_capture_active ||
        capture.avatar_joint_capture_active ||
        capture.avatar_volume_pair_active || reserve_overflows ||
        skeleton_segment_count > std::numeric_limits<U64>::max() -
            capture.render_debug_order)
    {
        capture.markIncomplete(__LINE__);
        return;
    }

    capture.avatar_joint_capture_first =
        capture.avatar_joint_batches.size();
    capture.avatar_joint_expected_segments = skeleton_segment_count;
    capture.avatar_joint_captured_segments = 0;
    try
    {
        capture.avatar_joint_batches.reserve(
            capture.avatar_joint_batches.size() + skeleton_segment_count);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.avatar_joint_batches.clear();
        return;
    }
    capture.avatar_joint_capture_active = true;
}

void LLPipeline::captureMetalAvatarJointBox(
    const LLVector4a& center, const LLVector4a& half_extent,
    bool attachment_bounds)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.avatar_joint_capture_active)
    {
        return;
    }
    if (!center.isFinite3() || !half_extent.isFinite3())
    {
        // Invalid extents make the same valid no-output decision as the
        // generated native outline.
        return;
    }

    if (!capture.complete || capture.avatar_volume_pair_active ||
        capture.render_debug_order == std::numeric_limits<U64>::max())
    {
        capture.markIncomplete(__LINE__);
        capture.avatar_joint_batches.clear();
        return;
    }

    ALMetalWorldAvatarJointBatch batch;
    batch.kind = attachment_bounds
        ? ALMetalWorldAvatarJointKind::attachment_bounds
        : ALMetalWorldAvatarJointKind::joint_bounds;
    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    std::memcpy(batch.line_modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.line_modelview_projection));
    std::memcpy(batch.center, center.getF32ptr(), sizeof(float) * 3);
    batch.center[3] = 1.f;
    std::memcpy(batch.half_extent, half_extent.getF32ptr(),
                sizeof(float) * 3);
    batch.half_extent[3] = 0.f;
    batch.visible_color[0] = attachment_bounds ? 0.f : 1.f;
    batch.visible_color[1] = 1.f;
    batch.visible_color[2] = attachment_bounds ? 1.f : 0.f;
    batch.visible_color[3] = 1.f;
    batch.order = capture.render_debug_order++;
    try
    {
        capture.avatar_joint_batches.push_back(batch);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.avatar_joint_batches.clear();
    }
}

void LLPipeline::endMetalAvatarJointCapture(
    std::size_t skeleton_segment_count)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.avatar_joint_capture_active)
    {
        return;
    }
    capture.avatar_joint_capture_active = false;
    if (!capture.complete || capture.avatar_volume_pair_active ||
        skeleton_segment_count != capture.avatar_joint_expected_segments ||
        capture.avatar_joint_captured_segments != skeleton_segment_count ||
        capture.avatar_joint_batches.size() <
            capture.avatar_joint_capture_first + skeleton_segment_count)
    {
        capture.markIncomplete(__LINE__);
        capture.avatar_joint_batches.clear();
    }
    capture.avatar_volume_batch = {};
    capture.avatar_joint_capture_first = 0;
    capture.avatar_joint_expected_segments = 0;
    capture.avatar_joint_captured_segments = 0;
    capture.avatar_volume_pair_active = false;
    capture.avatar_volume_sphere_transform_captured = false;
}

void LLPipeline::endMetalAvatarVolumeCapture(
    std::size_t collision_volume_count)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.avatar_volume_capture_active)
    {
        return;
    }
    capture.avatar_volume_capture_active = false;
    constexpr std::size_t pairs_per_volume = 2;
    const bool count_overflows = collision_volume_count >
        std::numeric_limits<std::size_t>::max() / pairs_per_volume;
    const std::size_t pair_count = count_overflows
        ? 0 : collision_volume_count * pairs_per_volume;
    const std::size_t captured_pairs = capture.avatar_volume_batches.size() -
        capture.avatar_volume_capture_first;
    if (!capture.complete || capture.avatar_volume_pair_active ||
        count_overflows || pair_count != capture.avatar_volume_expected_pairs ||
        captured_pairs != pair_count)
    {
        capture.markIncomplete(__LINE__);
        capture.avatar_volume_batches.clear();
    }
    capture.avatar_volume_batch = {};
    capture.avatar_volume_capture_first = 0;
    capture.avatar_volume_expected_pairs = 0;
    capture.avatar_volume_pair_active = false;
    capture.avatar_volume_sphere_transform_captured = false;
}

void LLPipeline::beginMetalDebugPointCapture()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || capture.debug_point_capture_active ||
        capture.debug_point_batch_active || !capture.debug_points.empty() ||
        !capture.debug_point_batches.empty() ||
        capture.render_debug_order != 0)
    {
        capture.markIncomplete(__LINE__);
        return;
    }
    capture.debug_point_capture_active = true;
}

void LLPipeline::beginMetalDebugPointBatch(std::size_t face_capacity)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.debug_point_capture_active)
    {
        return;
    }

    if (!capture.complete || capture.debug_point_batch_active ||
        face_capacity == 0 ||
        face_capacity > std::numeric_limits<std::uint32_t>::max() ||
        face_capacity >
            std::numeric_limits<std::size_t>::max() -
                capture.debug_points.size() ||
        capture.render_debug_order ==
            std::numeric_limits<U64>::max())
    {
        capture.markIncomplete(__LINE__);
        capture.debug_points.clear();
        capture.debug_point_batches.clear();
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    capture.debug_point_batch = {};
    std::memcpy(capture.debug_point_batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(capture.debug_point_batch.modelview_projection));
    capture.debug_point_batch_first = capture.debug_points.size();
    try
    {
        capture.debug_points.reserve(
            capture.debug_points.size() + face_capacity);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.debug_points.clear();
        capture.debug_point_batches.clear();
        return;
    }
    capture.debug_point_batch_active = true;
}

void LLPipeline::captureMetalDebugPoint(const LLVector3& position)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || !capture.debug_point_batch_active)
    {
        return;
    }
    ALMetalWorldDebugPointVertex point;
    std::memcpy(point.position, position.mV, sizeof(position.mV));
    try
    {
        capture.debug_points.push_back(point);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.debug_points.clear();
        capture.debug_point_batches.clear();
        capture.debug_point_batch_active = false;
    }
}

void LLPipeline::endMetalDebugPointBatch(std::size_t point_count)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.debug_point_batch_active)
    {
        return;
    }
    capture.debug_point_batch_active = false;
    if (!capture.complete ||
        capture.debug_point_batch_first > capture.debug_points.size() ||
        point_count != capture.debug_points.size() -
                           capture.debug_point_batch_first ||
        point_count > std::numeric_limits<std::uint32_t>::max() ||
        capture.debug_point_batch_first >
            std::numeric_limits<std::uint32_t>::max())
    {
        capture.markIncomplete(__LINE__);
        capture.debug_points.clear();
        capture.debug_point_batches.clear();
        return;
    }
    if (point_count == 0)
    {
        capture.debug_point_batch = {};
        return;
    }

    ALMetalWorldDebugPointBatch& batch = capture.debug_point_batch;
    batch.first_vertex = static_cast<std::uint32_t>(
        capture.debug_point_batch_first);
    batch.vertex_count = static_cast<std::uint32_t>(point_count);
    if (!capture.debug_point_batches.empty())
    {
        ALMetalWorldDebugPointBatch& previous =
            capture.debug_point_batches.back();
        const std::uint64_t previous_end =
            static_cast<std::uint64_t>(previous.first_vertex) +
            previous.vertex_count;
        const std::uint64_t merged_count =
            static_cast<std::uint64_t>(previous.vertex_count) +
            batch.vertex_count;
        if (previous.order + 1 == capture.render_debug_order &&
            previous_end == batch.first_vertex &&
            merged_count <= std::numeric_limits<std::uint32_t>::max() &&
            std::memcmp(previous.modelview_projection,
                        batch.modelview_projection,
                        sizeof(batch.modelview_projection)) == 0)
        {
            previous.vertex_count =
                static_cast<std::uint32_t>(merged_count);
            capture.debug_point_batch = {};
            return;
        }
    }

    batch.order = capture.render_debug_order++;
    try
    {
        capture.debug_point_batches.push_back(batch);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.debug_points.clear();
        capture.debug_point_batches.clear();
    }
    capture.debug_point_batch = {};
}

void LLPipeline::endMetalDebugPointCapture()
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.debug_point_capture_active)
    {
        return;
    }
    capture.debug_point_capture_active = false;
    if (!capture.complete || capture.debug_point_batch_active ||
        capture.debug_points.empty() != capture.debug_point_batches.empty())
    {
        capture.markIncomplete(__LINE__);
        capture.debug_points.clear();
        capture.debug_point_batches.clear();
        capture.debug_point_batch_active = false;
    }
}

void LLPipeline::captureMetalTextureAnimBatch(
    const LLDrawInfo& params)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    if (!capture.complete || !buffer || params.mCount == 0 ||
        params.mCount % 3 != 0 ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer() ||
        (buffer->getIndexStride() != 2 &&
         buffer->getIndexStride() != 4) ||
        capture.render_debug_order ==
            std::numeric_limits<U64>::max())
    {
        capture.markIncomplete(__LINE__);
        capture.texture_anim_batches.clear();
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    ALMetalWorldTextureAnimBatch batch;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_VERTEX);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset =
        static_cast<std::size_t>(params.mOffset) *
        buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = params.mCount;
    batch.order = capture.render_debug_order++;
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    try
    {
        capture.texture_anim_batches.push_back(batch);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.texture_anim_batches.clear();
    }
}

void LLPipeline::captureMetalUpdateTypeFace(
    const LLFace& face, const LLColor4& color)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    LLVertexBuffer* buffer = face.getVertexBuffer();
    if (!buffer || face.getGeomCount() == 0 ||
        face.getIndicesCount() == 0)
    {
        return;
    }

    const auto color_is = [&](F32 red, F32 green, F32 blue)
    {
        return color.mV[0] == red && color.mV[1] == green &&
               color.mV[2] == blue && color.mV[3] == 0.5f;
    };
    const bool valid_color =
        color_is(0.f, 1.f, 0.f) || color_is(0.f, 1.f, 1.f) ||
        color_is(1.f, 0.f, 0.f) || color_is(1.f, 1.f, 0.f) ||
        color_is(0.f, 0.f, 1.f);
    if (!capture.complete || face.getIndicesCount() % 3 != 0 ||
        face.getIndicesStart() < 0 ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer() ||
        (buffer->getIndexStride() != 2 &&
         buffer->getIndexStride() != 4) ||
        capture.render_debug_order ==
            std::numeric_limits<U64>::max() ||
        !valid_color)
    {
        capture.markIncomplete(__LINE__);
        capture.update_type_batches.clear();
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    ALMetalWorldUpdateTypeBatch batch;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_VERTEX);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset =
        static_cast<std::size_t>(face.getIndicesStart()) *
        buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = face.getIndicesCount();
    batch.order = capture.render_debug_order++;
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    std::memcpy(batch.color, color.mV, sizeof(batch.color));
    try
    {
        capture.update_type_batches.push_back(batch);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.update_type_batches.clear();
    }
}

void LLPipeline::captureMetalTexelDensityFace(
    const LLFace& face, const LLColor4& color)
{
    const bool hud_capture = sRenderingHUDs &&
        gGL.hasMetalUITextureCapture();
    const bool world_capture = mMetalWorldSimpleCapture &&
        mMetalWorldSimpleCapture->frame_active &&
        mMetalWorldSimpleCapture->world_post_deferred_active &&
        !mMetalWorldSimpleCapture->world_post_deferred_phase;
    if (!hud_capture && !world_capture)
    {
        return;
    }

    MetalWorldSimpleCapture* capture = world_capture
        ? mMetalWorldSimpleCapture.get() : nullptr;
    const auto fail = [capture, hud_capture](const char* reason)
    {
        if (capture)
        {
            capture->markIncomplete(__LINE__);
            capture->texel_density_batches.clear();
        }
        if (hud_capture)
        {
            gGL.invalidateMetalUITextureCapture(reason);
        }
    };

    LLVertexBuffer* buffer = face.getVertexBuffer();
    if (!buffer || face.getGeomCount() < 3 ||
        face.getIndicesCount() == 0)
    {
        return;
    }

    const std::size_t geom_first = face.getGeomStart();
    const std::size_t geom_count = face.getGeomCount();
    const bool color_finite = std::all_of(
        std::begin(color.mV), std::end(color.mV),
        [](F32 value) { return std::isfinite(value); });
    if ((capture && (!capture->complete ||
         capture->render_debug_order ==
             std::numeric_limits<U64>::max())) ||
        face.getIndicesCount() % 3 != 0 ||
        face.getIndicesStart() < 0 ||
        geom_first > buffer->getNumVerts() ||
        geom_count > buffer->getNumVerts() - geom_first ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer() ||
        (buffer->getIndexStride() != sizeof(U16) &&
         buffer->getIndexStride() != sizeof(U32)) ||
        !color_finite)
    {
        fail("Texel Density geometry or semantic color is incomplete");
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    const std::size_t index_offset =
        static_cast<std::size_t>(face.getIndicesStart()) *
        buffer->getIndexStride();

    if (capture)
    {
        ALMetalWorldTexelDensityBatch batch;
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = index_offset;
        batch.index_type = buffer->getIndexStride() == sizeof(U32)
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = face.getIndicesCount();
        batch.order = capture->render_debug_order++;
        std::memcpy(batch.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
        std::memcpy(batch.color, color.mV, sizeof(batch.color));
        try
        {
            capture->texel_density_batches.push_back(batch);
        }
        catch (const std::bad_alloc&)
        {
            fail("Texel Density batch allocation failed");
            return;
        }
    }

    if (hud_capture)
    {
        ALMetalHUDIndexedBatch batch;
        batch.shader = ALMetalHUDShader::debug;
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = index_offset;
        batch.index_type = buffer->getIndexStride() == sizeof(U32)
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = face.getIndicesCount();
        batch.double_sided = true;
        std::memcpy(batch.matrices.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.matrices.modelview_projection));
        std::memcpy(batch.highlight_color, color.mV,
                    sizeof(batch.highlight_color));
        if (!gGL.drawMetalHUDIndexedBatch(batch))
        {
            fail("Texel Density HUD attachment encoding failed");
        }
    }
}

void LLPipeline::captureMetalBatchSizeBatch(
    const LLDrawInfo& params, const LLColor4U& color)
{
    const bool hud_capture = sRenderingHUDs &&
        gGL.hasMetalUITextureCapture();
    const bool world_capture = mMetalWorldSimpleCapture &&
        mMetalWorldSimpleCapture->frame_active &&
        mMetalWorldSimpleCapture->world_post_deferred_active &&
        !mMetalWorldSimpleCapture->world_post_deferred_phase;
    if (!hud_capture && !world_capture)
    {
        return;
    }

    MetalWorldSimpleCapture* capture = world_capture
        ? mMetalWorldSimpleCapture.get() : nullptr;
    const auto fail = [capture, hud_capture](const char* reason)
    {
        if (capture)
        {
            capture->markIncomplete(__LINE__);
            capture->batch_size_batches.clear();
        }
        if (hud_capture)
        {
            gGL.invalidateMetalUITextureCapture(reason);
        }
    };

    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    const bool rigged = params.mAvatar != nullptr;
    if (!buffer || params.mCount == 0 || params.mCount % 3 != 0 ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer() ||
        (buffer->getIndexStride() != 2 &&
         buffer->getIndexStride() != 4) ||
        (rigged &&
         (!params.mSkinInfo ||
          !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))) ||
        color.mV[3] != 200)
    {
        fail("Batch Size geometry or render state is incomplete");
        return;
    }

    const F32* skin_palette = nullptr;
    std::size_t skin_palette_float_count = 0;
    U32 skin_joint_count = 0;
    std::size_t weight_offset = 0;
    if (rigged)
    {
        const LLVOAvatar::MatrixPaletteCache& palette =
            params.mAvatar->updateSkinInfoMatrixPalette(params.mSkinInfo);
        skin_joint_count = static_cast<U32>(
            palette.mMatrixPalette.size());
        skin_palette_float_count = palette.mGLMp.size();
        if (skin_joint_count == 0 || skin_joint_count > 110 ||
            skin_palette_float_count !=
                4u + static_cast<std::size_t>(skin_joint_count) * 12u)
        {
            fail("Batch Size skin palette is incomplete");
            return;
        }
        skin_palette = palette.mGLMp.data();
        weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT4);
    }

    LLMatrix4a modelview =
        LLViewerCamera::getCurrent().getModelview();
    if (params.mModelMatrix)
    {
        modelview.setMul(*params.mModelMatrix, modelview);
    }
    const LLMatrix4a& projection = hud_capture
        ? gGL.getProjectionMatrix()
        : LLViewerCamera::getCurrent().getProjection();
    LLMatrix4a modelview_projection;
    modelview_projection.setMul(modelview, projection);
    const std::size_t index_offset =
        static_cast<std::size_t>(params.mOffset) *
        buffer->getIndexStride();
    float native_color[4];
    for (std::size_t channel = 0; channel < 4; ++channel)
    {
        native_color[channel] =
            static_cast<F32>(color.mV[channel]) / 255.f;
    }

    if (world_capture)
    {
        if (!capture->complete || capture->render_debug_order ==
                std::numeric_limits<U64>::max())
        {
            fail("Batch Size ordering is incomplete");
            return;
        }
        ALMetalWorldBatchSizeBatch batch;
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.weight_offset = weight_offset;
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = index_offset;
        batch.index_type = buffer->getIndexStride() == 4
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = params.mCount;
        batch.skin_palette = skin_palette;
        batch.skin_palette_float_count = skin_palette_float_count;
        batch.skin_joint_count = skin_joint_count;
        batch.order = capture->render_debug_order++;
        std::memcpy(batch.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
        std::memcpy(batch.color, native_color, sizeof(batch.color));
        try
        {
            capture->batch_size_batches.push_back(batch);
        }
        catch (const std::bad_alloc&)
        {
            fail("Batch Size batch allocation failed");
            return;
        }
    }

    if (hud_capture)
    {
        ALMetalHUDIndexedBatch batch;
        batch.shader = rigged
            ? ALMetalHUDShader::debug_skinned
            : ALMetalHUDShader::debug;
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.weight_offset = weight_offset;
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = index_offset;
        batch.index_type = buffer->getIndexStride() == 4
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = params.mCount;
        batch.skin_palette = skin_palette;
        batch.skin_palette_float_count = skin_palette_float_count;
        batch.skin_joint_count = skin_joint_count;
        batch.double_sided = true;
        batch.depth_bias_slope = -1.f;
        batch.depth_bias_units = 1.f;
        std::memcpy(batch.matrices.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.matrices.modelview_projection));
        std::memcpy(batch.highlight_color, native_color,
                    sizeof(batch.highlight_color));
        if (!gGL.drawMetalHUDIndexedBatch(batch))
        {
            fail("Batch Size HUD attachment encoding failed");
        }
    }
}

void LLPipeline::beginMetalBoundingBoxCapture()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || capture.bounding_box_capture_active ||
        !capture.bounding_box_batches.empty())
    {
        capture.markIncomplete(__LINE__);
        return;
    }
    capture.bounding_box_capture_active = true;
}

void LLPipeline::captureMetalBoundingBox(
    const LLVector4a& center, const LLVector4a& half_extent,
    const LLColor4& color, F32 line_width)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.bounding_box_capture_active)
    {
        return;
    }
    if (!center.isFinite3() || !half_extent.isFinite3())
    {
        // drawBoxOutline() makes the same valid no-output decision.
        return;
    }

    if (!capture.complete ||
        capture.render_debug_order == std::numeric_limits<U64>::max() ||
        !std::isfinite(color.mV[0]) || !std::isfinite(color.mV[1]) ||
        !std::isfinite(color.mV[2]) || !std::isfinite(color.mV[3]) ||
        color.mV[3] != 1.f ||
        !std::isfinite(line_width) || line_width < 1.f || line_width > 5.f)
    {
        capture.markIncomplete(__LINE__);
        capture.bounding_box_batches.clear();
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    ALMetalWorldBoundingBoxBatch batch;
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    std::memcpy(batch.center, center.getF32ptr(), sizeof(float) * 3);
    batch.center[3] = 1.f;
    std::memcpy(batch.half_extent, half_extent.getF32ptr(),
                sizeof(float) * 3);
    batch.half_extent[3] = 0.f;
    std::memcpy(batch.color, color.mV, sizeof(batch.color));
    batch.line_width = line_width;
    batch.order = capture.render_debug_order++;
    try
    {
        capture.bounding_box_batches.push_back(batch);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.bounding_box_batches.clear();
    }
}

void LLPipeline::endMetalBoundingBoxCapture()
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.bounding_box_capture_active)
    {
        return;
    }
    capture.bounding_box_capture_active = false;
    if (!capture.complete)
    {
        capture.bounding_box_batches.clear();
    }
}

