void LLPipeline::captureMetalFarPlaneOverlay()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete)
    {
        return;
    }
    if (!capture.far_plane_overlay_columns.empty())
    {
        capture.markIncomplete(__LINE__);
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    std::memcpy(capture.far_plane_overlay_modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(capture.far_plane_overlay_modelview_projection));

    const LLVector3 origin = LLViewerCamera::getInstance()->getOrigin();
    const std::vector<ALFarPlane::OverlayColumn>& columns =
        ALFarPlane::overlayColumns();
    try
    {
        capture.far_plane_overlay_columns.reserve(columns.size());
        for (bool nearer : {true, false})
        {
            for (const ALFarPlane::OverlayColumn& column : columns)
            {
                if (column.mNearer != nearer)
                {
                    continue;
                }
                const F32 radians = column.mBearing * DEG_TO_RAD;
                const LLVector3 forward(
                    sinf(radians), cosf(radians), 0.f);
                const LLVector3 right(
                    cosf(radians), -sinf(radians), 0.f);
                const LLVector3 center = origin +
                    forward * column.mDistance +
                    right * column.mOffset;

                ALMetalWorldFarPlaneOverlayColumn retained;
                std::memcpy(retained.center, center.mV, sizeof(center.mV));
                retained.half_extent[0] = column.mHalfWidth;
                retained.half_extent[1] = column.mHalfWidth;
                retained.half_extent[2] = 0.5f * column.mHeight;
                retained.color[0] = nearer ? 1.f : 0.f;
                retained.color[1] = nearer ? 0.5f : 0.8f;
                retained.color[2] = nearer ? 0.f : 1.f;
                capture.far_plane_overlay_columns.push_back(retained);
            }
            if (nearer)
            {
                capture.far_plane_overlay_near_count =
                    capture.far_plane_overlay_columns.size();
            }
        }
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.far_plane_overlay_columns.clear();
        capture.far_plane_overlay_near_count = 0;
    }

    if (capture.complete &&
        (capture.far_plane_overlay_columns.size() != columns.size() ||
         capture.far_plane_overlay_near_count == 0 ||
         capture.far_plane_overlay_near_count >=
             capture.far_plane_overlay_columns.size()))
    {
        capture.markIncomplete(__LINE__);
        capture.far_plane_overlay_columns.clear();
        capture.far_plane_overlay_near_count = 0;
    }
}

bool LLPipeline::fillMetalWorldAlphaEnvironment(
    ALMetalWorldAlphaEnvironment& alpha)
{
    const LLEnvironment& environment = LLEnvironment::instance();
    const LLSettingsSky::ptr_t sky = environment.getCurrentSky();
    if (!sky)
    {
        return false;
    }

    const LLEnvironment::EnvironmentUBOData& data =
        environment.getEnvironmentUBOData();
    alpha = {};
    std::memcpy(alpha.water_plane, LLDrawPoolAlpha::sWaterPlane.mV,
                sizeof(alpha.water_plane));
    std::memcpy(alpha.eye_to_sky, data.eyeToSky,
                sizeof(alpha.eye_to_sky));
    std::memcpy(alpha.haze_extinction, data.haze_extinction,
                sizeof(data.haze_extinction));
    std::memcpy(alpha.glow_max_y, data.glow, sizeof(data.glow));
    alpha.glow_max_y[3] = data.max_y;
    std::memcpy(alpha.haze_additive, data.haze_additive,
                sizeof(data.haze_additive));
    std::memcpy(alpha.haze_additive_glow, data.haze_additive_glow,
                sizeof(data.haze_additive_glow));
    std::memcpy(alpha.water_fog_color, data.waterFogColorLinear,
                sizeof(data.waterFogColorLinear));
    const LLVector4& light_direction = environment.getIsSunUp()
        ? mTransformedSunDir : mTransformedMoonDir;
    std::memcpy(alpha.light_direction, light_direction.mV,
                sizeof(alpha.light_direction));
    std::memcpy(alpha.atmos_sunlit, data.atmos_sunlit,
                sizeof(data.atmos_sunlit));
    std::memcpy(alpha.atmos_sunlit_linear, data.atmos_sunlit_linear,
                sizeof(data.atmos_sunlit_linear));
    std::memcpy(alpha.atmos_amblit, data.atmos_amblit,
                sizeof(data.atmos_amblit));
    alpha.atmos_sunlit[3] = data.sky_sunlight_scale;
    alpha.atmos_sunlit_linear[3] = data.sky_ambient_scale;
    alpha.atmospheric[0] = sky->getDensityMultiplier();
    alpha.atmospheric[1] = data.distance_multiplier;
    alpha.atmospheric[2] = sky->getSunMoonGlowFactor();

    // LLSettingsVOSky::applySpecial owns this loose-uniform policy. The
    // transparent owner must see the same value as the authoritative GLSL
    // program even when the sky itself is an HDRI.
    static LLCachedControl<bool> should_auto_adjust(
        gSavedSettings, "RenderSkyAutoAdjustLegacy", false);
    static LLCachedControl<F32> auto_adjust_hdr_scale(
        gSavedSettings, "RenderSkyAutoAdjustHDRScale", 2.f);
    alpha.atmospheric[3] = sky->getReflectionProbeAmbiance() != 0.f
        ? sqrtf(sky->getGamma()) * 2.f
        : sky->canAutoAdjust() && should_auto_adjust
            ? static_cast<F32>(auto_adjust_hdr_scale) : 1.f;
    alpha.water_fog[0] = data.waterFogKS;
    alpha.water_fog[1] = data.waterFogDensity;
    alpha.water_fog[2] = sUnderWaterRender ? 1.f : -1.f;

    // Match bindDeferredShader's transpose=true env_mat upload. The
    // transparent and opaque-forward owners consume the same no-probe sky
    // cube as the already-native base-light and water owners.
    const F32* modelview =
        LLViewerCamera::getCurrent().getModelview().getF32ptr();
    alpha.environment_matrix[0][0] = modelview[0];
    alpha.environment_matrix[0][1] = modelview[4];
    alpha.environment_matrix[0][2] = modelview[8];
    alpha.environment_matrix[1][0] = modelview[1];
    alpha.environment_matrix[1][1] = modelview[5];
    alpha.environment_matrix[1][2] = modelview[9];
    alpha.environment_matrix[2][0] = modelview[2];
    alpha.environment_matrix[2][1] = modelview[6];
    alpha.environment_matrix[2][2] = modelview[10];
    alpha.environment[0] = data.reflection_probe_ambiance;

    static_assert(sizeof(ALMetalWorldAlphaEnvironment) == 320);
    const F32* values = reinterpret_cast<const F32*>(&alpha);
    constexpr std::size_t float_count =
        offsetof(ALMetalWorldAlphaEnvironment, environment_config) /
        sizeof(F32);
    return std::all_of(values, values + float_count,
                       [](F32 value) { return std::isfinite(value); }) &&
        alpha.atmospheric[0] >= 0.f &&
        alpha.atmospheric[1] >= 0.f &&
        alpha.atmospheric[3] >= 0.f &&
        alpha.water_fog[0] > 0.f && alpha.water_fog[1] >= 0.f;
}

bool LLPipeline::fillMetalWorldAlphaLighting(
    ALMetalWorldLegacyAlphaLighting& lighting)
{
    lighting = {};
    const LLEnvironment& environment = LLEnvironment::instance();
    const LLEnvironment::EnvironmentUBOData& data =
        environment.getEnvironmentUBOData();
    const LLVector4& sun_direction = environment.getIsSunUp()
        ? mTransformedSunDir : mTransformedMoonDir;
    std::memcpy(lighting.sun_direction, sun_direction.mV,
                sizeof(sun_direction.mV));
    for (U32 channel = 0; channel < 3; ++channel)
    {
        lighting.sun_color[channel] = LLRender::sClassicMode
            ? sRGBtoLinear(data.atmos_sunlit[channel] *
                           data.sky_sunlight_scale * 1.35f)
            : data.atmos_sunlit_linear[channel] *
                  data.sky_sunlight_scale;
    }
    // Build the forward-alpha light block from the authoritative CPU scene
    // list. The old bridge snapshotted gGL's packed light UBO, which made a
    // native probe face depend on setupHWLights mutating legacy GL state and
    // could also import a stale avatar-backlight slot. Index zero is kept
    // empty to preserve the historical slot-1 reservation; the next six
    // entries match setupHWLights' slot-2..7 selection and ordering.
    const LLMatrix4a& modelview =
        LLViewerCamera::getCurrent().getModelview();
    F32 light_scale = 1.f;
    if (gCubeSnapshot)
    {
        light_scale = mReflectionMapManager.mLightScale;
    }
    else
    {
        static LLCachedControl<F32> alchemy_light_scale(
            gSavedSettings, "AlchemyGlobalLightScale", 1.f);
        light_scale = alchemy_light_scale;
    }

    std::size_t destination_index = 1;
    for (light_set_t::const_iterator iter = mNearbyLights.begin();
         iter != mNearbyLights.end() &&
         destination_index < lighting.local_lights.size(); ++iter)
    {
        LLDrawable* drawable = iter->drawable;
        LLVOVolume* volume = drawable ? drawable->getVOVolume() : nullptr;
        if (!volume || (volume->isAttachment() && !sRenderAttachedLights))
        {
            continue;
        }

        LLColor4 color = volume->getLightLinearColor() * light_scale;
        color.mV[3] = 0.f;
        color *= light_fade_brightness(iter->fade);
        const F32 radius = volume->getLightRadius() * 1.5f;
        if (color.magVecSquared() < 0.001f || radius <= 0.001f)
        {
            continue;
        }

        ALMetalWorldLegacyAlphaLight& destination =
            lighting.local_lights[destination_index++];
        const LLVector4 world_position_value(
            volume->getRenderPosition(), 1.f);
        LLVector4a world_position;
        world_position.loadua(world_position_value.mV);
        LLVector4a eye_position;
        modelview.transform4(world_position, eye_position);
        std::memcpy(destination.position, eye_position.getF32ptr(),
                    sizeof(destination.position));
        std::memcpy(destination.diffuse, color.mV,
                    sizeof(destination.diffuse));
        destination.parameters[0] = radius;
        destination.parameters[1] =
            volume->getLightFalloff(DEFERRED_LIGHT_FALLOFF);

        if (volume->isLightSpotlight())
        {
            LLVector3 direction(0.f, 0.f, -1.f);
            direction *= volume->getRenderRotation();
            LLVector4a world_direction;
            world_direction.load3(direction.mV);
            LLVector4a eye_direction;
            modelview.rotate(world_direction, eye_direction);
            std::memcpy(destination.direction,
                        eye_direction.getF32ptr(),
                        sizeof(F32) * 3);
            destination.parameters[2] = 0.f;
            destination.parameters[3] =
                volume->getSpotLightParams().mV[2];
        }
        else
        {
            destination.parameters[2] = 1.f;
        }
    }
    lighting.parameters[0] = mDeferredUBOData.specular_exponent;
    lighting.parameters[1] = 0.004f;
    lighting.parameters[2] = 1.f;
    lighting.parameters[3] = LLRender::sClassicMode ? 1.f : 0.f;

    const F32* values = reinterpret_cast<const F32*>(&lighting);
    return std::all_of(
        values, values + sizeof(lighting) / sizeof(F32),
        [](F32 value) { return std::isfinite(value); });
}

void LLPipeline::beginMetalWorldPreWaterAlphaPhase()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active || capture.world_pre_water_alpha_active ||
        capture.world_post_water_alpha_active ||
        !fillMetalWorldAlphaEnvironment(capture.alpha_environment))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.alpha_environment = {};
        capture.alpha_environment_valid = false;
        capture.world_alpha_lighting = {};
        capture.world_alpha_lighting_valid = false;
        capture.world_alpha_uses_shadows = false;
        return;
    }
    capture.world_pre_water_alpha_active = true;
    capture.alpha_environment_valid = true;
}

void LLPipeline::endMetalWorldPreWaterAlphaPhase()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_pre_water_alpha_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    capture.world_pre_water_alpha_active = false;
    capture.pass_active = false;
    capture.rigged = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
}

void LLPipeline::beginMetalWorldPostWaterAlphaPhase()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool low_detail_probe = gCubeSnapshot &&
        shaderInputs().mGlobal.mProbeLevel == 0;
    const bool atmospheric_haze_expected =
        !sRenderingHUDs && !sImpostorRender &&
        RenderDeferredAtmospheric && !low_detail_probe;
    if (!capture.alpha_environment_valid)
    {
        capture.alpha_environment_valid =
            fillMetalWorldAlphaEnvironment(capture.alpha_environment);
    }
    if (capture.pass_active || capture.world_pre_water_alpha_active ||
        capture.world_post_water_alpha_active ||
        (atmospheric_haze_expected && !capture.atmospheric_haze_valid) ||
        !capture.alpha_environment_valid)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.world_post_water_alpha_active = false;
        return;
    }
    capture.world_post_water_alpha_active = true;
}

void LLPipeline::endMetalWorldPostWaterAlphaPhase()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_post_water_alpha_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    capture.world_post_water_alpha_active = false;
    capture.pass_active = false;
    capture.rigged = false;
    capture.pbr = false;
    capture.legacy_glow = false;
    capture.pbr_glow = false;
}

void LLPipeline::beginMetalWorldWaterExclusionPass()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active ||
        !mWaterSurface.fillMetalWaterExclusionSurface(
            capture.water_exclusion_surface,
            *LLViewerCamera::getInstance()))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.water_exclusion_surface_valid = false;
        return;
    }
    capture.rigged = false;
    capture.alpha_mask = false;
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
    capture.pbr = false;
    capture.terrain = false;
    capture.avatar = false;
    capture.impostor = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
    capture.water_exclusion = true;
    capture.legacy_glow = false;
    capture.pbr_glow = false;
    capture.water_exclusion_surface_valid = true;
    capture.pass_active = true;
}

