bool LLPipeline::requestMetalWorldSnapshotCapture(std::string* error)
{
    const auto fail = [error](const char* message)
    {
        if (error)
        {
            *error = message;
        }
        return false;
    };
    if (mMetalWorldSnapshotRequested)
    {
        return fail("Metal world snapshot capture is already requested");
    }
    if (!sRenderDeferred)
    {
        return fail("Metal world snapshot requires deferred rendering");
    }
    if (!getViewerMetalDevice())
    {
        return fail("Metal world snapshot device is unavailable");
    }
    mMetalWorldSnapshotRequested = true;
    if (!canCaptureMetalWorldPresentation(error))
    {
        mMetalWorldSnapshotRequested = false;
        return false;
    }
    return true;
}

bool LLPipeline::readMetalWorldSnapshot(
    U32 x, U32 y, U32 width, U32 height, U8* pixels,
    std::size_t bytes_per_row, std::string* error) const
{
    const auto fail = [error](const char* message)
    {
        if (error)
        {
            *error = message;
        }
        return false;
    };
    if (!mMetalWorldSnapshotRequested || !pixels || width == 0 ||
        height == 0 || !mMetalWorldSimpleCapture)
    {
        return fail("Metal world snapshot capture is unavailable");
    }
    const MetalWorldSimpleCapture& capture =
        *mMetalWorldSimpleCapture;
    const ALMetalTexture* texture = capture.world_ui_target.get();
    ALMetalDevice* device = getViewerMetalDevice();
    if (!capture.world_ui_chain_snapshot ||
        capture.world_ui_capture_active || !texture || !device ||
        capture.device != device || capture.world_ui_frame != gFrameCount)
    {
        if (error)
        {
            *error = fmt::format(
                "Metal world snapshot did not complete exactly: "
                "chain_snapshot={}, capture_active={}, chain_active={}, "
                "complete={}, first_incomplete_line={}, "
                "frame_active={}, renderer={}, target={}, composed_light={}, "
                "lighting_attempted={}, post_attempted={}, "
                "presentation_target={}, presentation_frame={}, "
                "world_ui_target={}, world_ui_frame={}, current_frame={}, "
                "device={}, device_match={}",
                capture.world_ui_chain_snapshot,
                capture.world_ui_capture_active,
                capture.world_ui_chain_active,
                capture.complete,
                capture.first_incomplete_source_line,
                capture.frame_active,
                static_cast<bool>(capture.renderer),
                static_cast<bool>(capture.target),
                static_cast<bool>(capture.composed_light_target),
                capture.lighting_composition_attempted,
                capture.opaque_post_deferred_attempted,
                static_cast<bool>(capture.presentation_target),
                capture.presentation_frame,
                static_cast<bool>(capture.world_ui_target),
                capture.world_ui_frame,
                gFrameCount,
                device != nullptr,
                capture.device == device);
        }
        return false;
    }
    const ALMetalTextureDescriptor& descriptor = texture->descriptor();
    if (descriptor.format != ALMetalPixelFormat::bgra8_unorm ||
        x > descriptor.width || y > descriptor.height ||
        width > descriptor.width - x || height > descriptor.height - y)
    {
        return fail("Metal world snapshot region is incompatible");
    }
    return texture->readbackRGB8(
        *device, 0, 0, {x, y, width, height}, pixels,
        bytes_per_row, error);
}

bool LLPipeline::readMetalWorldSnapshotRGBA(
    U32 x, U32 y, U32 width, U32 height, U8* pixels,
    std::size_t bytes_per_row, std::string* error) const
{
    const auto fail = [error](const char* message)
    {
        if (error)
        {
            *error = message;
        }
        return false;
    };
    if (!mMetalWorldSnapshotRequested || !sCutoutRender || !pixels ||
        width == 0 || height == 0 || !mMetalWorldSimpleCapture)
    {
        return fail("Metal world cutout snapshot capture is unavailable");
    }
    const MetalWorldSimpleCapture& capture =
        *mMetalWorldSimpleCapture;
    const ALMetalTexture* texture = capture.presentation_target
        ? capture.presentation_target->colorTexture(0) : nullptr;
    ALMetalDevice* device = getViewerMetalDevice();
    if (!capture.world_ui_chain_snapshot ||
        capture.world_ui_capture_active || !texture || !device ||
        capture.device != device || capture.presentation_frame != gFrameCount)
    {
        return fail("Metal world cutout snapshot did not complete exactly");
    }
    const ALMetalTextureDescriptor& descriptor = texture->descriptor();
    const std::size_t rgba_row = static_cast<std::size_t>(width) * 4u;
    if (descriptor.format != ALMetalPixelFormat::bgra8_unorm ||
        x > descriptor.width || y > descriptor.height ||
        width > descriptor.width - x || height > descriptor.height - y ||
        bytes_per_row < rgba_row ||
        (height != 0 &&
         rgba_row > std::numeric_limits<std::size_t>::max() / height))
    {
        return fail("Metal world cutout snapshot region is incompatible");
    }

    std::vector<U8> staging;
    try
    {
        staging.resize(rgba_row * static_cast<std::size_t>(height));
    }
    catch (const std::bad_alloc&)
    {
        return fail("Could not allocate Metal cutout snapshot staging");
    }
    if (!texture->readback(
            *device, 0, 0, {x, y, width, height}, staging.data(),
            rgba_row, error))
    {
        return false;
    }
    for (U32 row = 0; row < height; ++row)
    {
        const U8* source = staging.data() + row * rgba_row;
        U8* destination = pixels + row * bytes_per_row;
        for (U32 column = 0; column < width; ++column)
        {
            const std::size_t offset =
                static_cast<std::size_t>(column) * 4u;
            destination[offset + 0] = source[offset + 2];
            destination[offset + 1] = source[offset + 1];
            destination[offset + 2] = source[offset + 0];
            destination[offset + 3] = source[offset + 3];
        }
    }
    return true;
}

bool LLPipeline::readMetalWorldSnapshotDepth(
    U32 x, U32 y, U32 width, U32 height, F32* depth,
    std::size_t bytes_per_row, std::string* error) const
{
    const auto fail = [error](const char* message)
    {
        if (error)
        {
            *error = message;
        }
        return false;
    };
    if (!mMetalWorldSnapshotRequested || !depth || width == 0 ||
        height == 0 || !mMetalWorldSimpleCapture)
    {
        return fail("Metal world depth snapshot capture is unavailable");
    }
    const MetalWorldSimpleCapture& capture =
        *mMetalWorldSimpleCapture;
    const ALMetalTexture* texture = capture.target
        ? capture.target->depthStencilTexture() : nullptr;
    ALMetalDevice* device = getViewerMetalDevice();
    if (!capture.world_ui_chain_snapshot ||
        capture.world_ui_capture_active || !texture || !device ||
        capture.device != device || capture.world_ui_frame != gFrameCount)
    {
        return fail("Metal world depth snapshot did not complete exactly");
    }
    const ALMetalTextureDescriptor& descriptor = texture->descriptor();
    if ((descriptor.format != ALMetalPixelFormat::depth32_float &&
         descriptor.format !=
             ALMetalPixelFormat::depth32_float_stencil8) ||
        x > descriptor.width || y > descriptor.height ||
        width > descriptor.width - x || height > descriptor.height - y)
    {
        return fail("Metal world depth snapshot region is incompatible");
    }
    return texture->readback(
        *device, 0, 0, {x, y, width, height}, depth,
        bytes_per_row, error);
}

void LLPipeline::cancelMetalWorldSnapshotCapture()
{
    mMetalWorldSnapshotRequested = false;
}

bool LLPipeline::beginMetalWorldUICompositionCapture()
{
    if (!mMetalWorldSimpleCapture ||
        (gSnapshot && !mMetalWorldSnapshotRequested) || sCutoutRender ||
        mMetalHeroWorldCaptureActive || mMetalReflectionWorldCaptureActive ||
        mRT != &mMainRT || gDisconnected)
    {
        return false;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.world_ui_capture_active || !gAlphaMaskProgram.isAvailable())
        return false;

    const ALMetalTexture* background = nullptr;
    const ALMetalTexture* depth = nullptr;
    const bool exact_frame = capture.world_ui_chain_snapshot ||
        capture.world_ui_chain_debug_color || gSnapshot;
    if (exact_frame)
    {
        // Screenshots and pixel diagnostics must describe this exact world,
        // never the retained prefix of a preceding display frame.
        if (!capture.world_ui_chain_active || capture.world_ssr_history_warmup ||
            !capture.presentation_target || !capture.target ||
            capture.presentation_frame != gFrameCount)
            return false;
        background = capture.presentation_target->colorTexture(0);
        depth = capture.target->depthStencilTexture();
        if (!background || !depth ||
            background->descriptor().width != depth->descriptor().width ||
            background->descriptor().height != depth->descriptor().height)
            return false;
    }
    else
    {
        if (!metalWorldPresentationRequested()) return false;
        const ALMetalSurface* surface = gGL.getMetalPresentationSurface();
        ALMetalDevice* device = getViewerMetalDevice();
        if (!surface || !device) return false;
        const auto& info = surface->info();
        const ALMetalRetainedBackground::Context context{
            device, surface, info.generation, info.width, info.height,
            LLRender::sReverseZ};
        if (info.width == 0 || info.height == 0) return false;

        // renderFinalize has already committed the world transaction. Keep
        // its PRE-UI color and matching depth, not last frame's combined UI.
        std::string error;
        if (capture.presentation_frame == gFrameCount &&
            capture.presentation_target && capture.target &&
            capture.device == device &&
            !capture.world_ssr_history_warmup)
        {
            if (!capture.ui_background.publish(context, gFrameCount,
                    capture.presentation_target, capture.target, &error))
            {
                LL_WARNS_ONCE("Metal")
                    << "Could not retain the native pre-UI world: " << error
                    << LL_ENDL;
            }
        }
        capture.ui_frame_background = capture.ui_background.find(context);
        if (capture.ui_frame_background)
        {
            capture.ui_clear_background.reset();
            if (capture.ui_frame_background->source_frame != gFrameCount)
            {
                LL_INFOS_ONCE("Metal")
                    << "Publishing fresh native UI over the retained pre-UI "
                       "world while current scene resources are incomplete"
                    << LL_ENDL;
            }
        }
        else
        {
            // A resize/device change invalidates both backing textures as
            // one pair. Keep publishing fresh controls even before any world
            // is ready, with far depth so HUD depth brackets remain valid.
            capture.ui_background.clear();
            if (!capture.ui_clear_background ||
                !(capture.ui_clear_background->context == context))
            {
                capture.ui_clear_background =
                    ALMetalRetainedBackground::makeCleared(context, &error);
            }
            capture.ui_frame_background = capture.ui_clear_background;
            if (!capture.ui_frame_background)
            {
                LL_WARNS_ONCE("Metal")
                    << "Could not prepare native UI loading background: "
                    << error << LL_ENDL;
                return false;
            }
        }
        background = capture.ui_frame_background->colorTexture();
        depth = capture.ui_frame_background->depthTexture();
    }

    // This transaction owns the HUD fills as well as the interface. HUD draw
    // pools require native authority; mirror mode captures selection outlines
    // but silently skips the attached HUD surfaces.
    if (!gGL.beginMetalUITextureCapture(
            ALMetalPixelFormat::bgra8_unorm, &gAlphaMaskProgram,
            background, depth, &gDebugProgram,
            LLRender::EMetalUICaptureMode::NATIVE_AUTHORITATIVE,
            LLRender::EMetalUICaptureStorage::FORMAT_NATIVE,
            &capture.world_ui_target))
    {
        capture.ui_frame_background.reset();
        return false;
    }
    capture.world_ui_target.reset();
    capture.world_ui_frame = std::numeric_limits<U32>::max();
    capture.world_ui_capture_active = true;
    if (!capture.world_ui_chain_snapshot &&
        metalWorldPresentationRequested())
    {
        capture.world_ui_presentation_state_frame = gFrameCount;
        capture.world_ui_presentation_state =
            MetalWorldPresentationState::CaptureStarted;
    }
    if (!capture.world_ui_chain_snapshot)
    {
        capture.world_ui_probe_attempted = true;
        if (!capture.world_ui_continuous_unlocked &&
            !capture.world_ui_chain_debug_color)
        {
            ++capture.world_ui_probe_attempts;
        }
    }
    return true;
}

void LLPipeline::endMetalWorldUICompositionCapture()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_ui_capture_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;

    // Every batch owner fails the capture closed when it cannot reproduce its
    // GL draw, and begin rejected the known world-side overlays that sit
    // outside this ordered stream. When presentation is requested, append the
    // final drawable copy before committing this offscreen command buffer so
    // the exact texture and its surface publication share one submission.
    const bool presentation_requested =
        metalWorldPresentationRequested() &&
        !capture.world_ui_chain_snapshot;
    const bool surface_ready = presentation_requested &&
        gGL.setMetalPresentationOpaque(true);
    bool surface_submitted = false;
    std::string capture_failure;
    LLRender::EMetalUICaptureEndState capture_end_state =
        LLRender::EMetalUICaptureEndState::INACTIVE;
    capture.world_ui_target = gGL.endMetalUITextureCapture(
        true, surface_ready, &surface_submitted, &capture_failure,
        &capture_end_state);
    capture.world_ui_capture_active = false;
    capture.ui_frame_background.reset();
    if (presentation_requested)
    {
        capture.world_ui_presentation_state_frame = gFrameCount;
        if (surface_submitted)
        {
            capture.world_ui_presentation_state =
                MetalWorldPresentationState::Submitted;
        }
        else if (capture.world_ui_target && !surface_ready)
        {
            capture.world_ui_presentation_state =
                MetalWorldPresentationState::SurfaceUnavailable;
        }
        else if (surface_ready &&
                 (capture_end_state ==
                      LLRender::EMetalUICaptureEndState::
                          COMMAND_SUBMISSION_FAILED ||
                  capture_end_state ==
                      LLRender::EMetalUICaptureEndState::
                          SURFACE_SUBMISSION_FAILED))
        {
            capture.world_ui_presentation_state =
                MetalWorldPresentationState::SurfaceSubmitFailed;
        }
        else
        {
            capture.world_ui_presentation_state =
                MetalWorldPresentationState::CaptureFailed;
        }
    }
    if (capture.world_ui_target)
    {
        capture.world_ui_frame = gFrameCount;
        LL_INFOS_ONCE("Metal")
            << "A complete current-frame native world + ordered UI/HUD "
               "texture was retained after its command submission"
            << LL_ENDL;

        // Native publication is mandatory. A committed current-frame
        // drawable advances the surface; failure retains the previous Metal
        // drawable and never reveals a second visible backend.
        if (presentation_requested)
        {
            if (surface_submitted)
            {
                gDisplaySwapBuffers = false;
                capture.world_ui_last_submitted_frame = gFrameCount;
                capture.world_ui_continuous_failure_streak = 0;
                capture.world_ui_continuous_last_failure_frame =
                    std::numeric_limits<U32>::max();
                capture.world_ui_probe_attempted = false;
                LL_INFOS_ONCE("Metal")
                    << "Continuous native world/UI publication is active; "
                       "each incomplete frame retains the previous native "
                       "drawable"
                    << LL_ENDL;
            }
            else
            {
                capture.world_ui_target.reset();
                capture.world_ui_frame = std::numeric_limits<U32>::max();
                capture.world_ui_probe_attempted = false;
                LL_INFOS_ONCE("Metal")
                    << "Native world/UI publication failed closed; the "
                       "opaque surface retains its previous Metal drawable "
                       "while the next frame retries"
                    << LL_ENDL;
            }
        }
        else if (capture.world_ui_chain_debug_color)
        {
            // The diagnostic consumes a fresh exact prefix every frame and
            // must not latch the bounded presentation probe's one-shot gate.
            capture.world_ui_probe_attempted = false;
        }
    }
    else
    {
        capture.world_ui_frame = std::numeric_limits<U32>::max();
        // An unsupported runtime family is evidence, not a permanent latch:
        // mandatory native authority retries on the next eligible frame.
        if (!capture.world_ui_chain_snapshot)
        {
            capture.world_ui_probe_attempted = false;
        }
        LL_INFOS_ONCE("Metal")
            << "The ordered native world/UI transaction failed closed; "
               "the previous Metal drawable remains authoritative while "
               "the next frame retries. First exactness failure: "
            << capture_failure
            << LL_ENDL;
    }
}

void LLPipeline::beginMetalImpostorFullbrightPass(bool rigged,
                                                  bool alpha_mask)
{
    if (!mMetalWorldSimpleCapture ||
        (!mMetalWorldSimpleCapture->impostor_alpha_active &&
         !mMetalWorldSimpleCapture->world_post_deferred_active) ||
        mMetalWorldSimpleCapture->impostor_alpha_phase ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    capture.rigged = rigged;
    capture.alpha_mask = alpha_mask;
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
    capture.pbr = false;
    capture.terrain = false;
    capture.avatar = false;
    capture.impostor = false;
    capture.impostor_fullbright = true;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
    capture.pass_active = true;
}

void LLPipeline::beginMetalImpostorShinyPass(bool rigged)
{
    if (!mMetalWorldSimpleCapture ||
        (!mMetalWorldSimpleCapture->impostor_alpha_active &&
         !mMetalWorldSimpleCapture->world_post_deferred_active) ||
        mMetalWorldSimpleCapture->impostor_alpha_phase ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    // fullbrightShinyF supplies zero glossiness to legacyProbeFinish, so its
    // SSR gate is always false. The active hero probe still replaces the
    // legacy radiance tap, but that sharp cube is mirrored before encoding.
    capture.rigged = rigged;
    capture.alpha_mask = false;
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
    capture.pbr = false;
    capture.terrain = false;
    capture.avatar = false;
    capture.impostor = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = true;
    capture.impostor_emboss = false;
    capture.pass_active = true;
}

