{
    if (!mMetalWorldSimpleCapture ||
        (!mMetalWorldSimpleCapture->impostor_alpha_active &&
         !mMetalWorldSimpleCapture->world_post_deferred_active) ||
        mMetalWorldSimpleCapture->impostor_alpha_phase ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    capture.rigged = rigged;
    capture.alpha_mask = false;
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
    capture.pbr = false;
    capture.terrain = false;
    capture.avatar = false;
    capture.impostor = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = true;
    capture.pass_active = true;
}

void LLPipeline::beginMetalImpostorAlphaPhase()
{
    if (mMetalWorldSimpleCapture &&
        mMetalWorldSimpleCapture->world_post_deferred_active)
    {
        return;
    }
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->impostor_alpha_active ||
        mMetalWorldSimpleCapture->impostor_alpha_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    capture.pass_active = false;
    capture.impostor_alpha_phase = true;

    const bool has_shiny = std::any_of(
        capture.batches.begin(), capture.batches.end(),
        [](const ALMetalWorldSimpleBatch& batch)
        {
            return batch.impostor_shiny;
        });
    const bool hero_active = !gCubeSnapshot && isMetalHeroProbeActive();
    if (capture.complete && has_shiny &&
        !mReflectionMapManager.fillMetalReflectionProbes(
            capture.impostor_reflection_probes))
    {
        // The native slice must be one coherent replay. If any shiny batch
        // cannot see a complete current probe generation, retain the GL bake
        // instead of publishing a partial Metal result.
        capture.markIncomplete(__LINE__);
        LL_WARNS("Metal")
            << "Could not acquire a coherent reflection-probe pack for the "
               "native avatar-impostor opaque-forward slice" << LL_ENDL;
    }
    if (capture.complete && has_shiny && hero_active &&
        !fillMetalImpostorHeroProbe())
    {
        capture.markIncomplete(__LINE__);
        LL_WARNS("Metal")
            << "Could not acquire the active hero probe for the native "
               "avatar-impostor opaque-forward slice" << LL_ENDL;
    }

    if (capture.complete && !capture.batches.empty() &&
        capture.renderer && capture.impostor_bake_target)
    {
        ALMetalWorldGBufferScene scene;
        scene.batches = capture.batches.data();
        scene.batch_count = capture.batches.size();
        scene.width = capture.width;
        scene.height = capture.height;
        scene.normal_hdr = capture.normal_hdr;
        scene.hdr = capture.hdr;
        scene.reverse_z = capture.reverse_z;
        scene.stamp_opaque_coverage = !capture.impostor_profile;
        scene.reflection_probes = has_shiny
            ? &capture.impostor_reflection_probes : nullptr;
        scene.hero_probe = has_shiny && hero_active
            ? &capture.impostor_hero_probe : nullptr;
        std::string error;
        if (!capture.renderer->compositeImpostorPostDeferred(
                *capture.impostor_bake_target, scene, &error))
        {
            capture.markIncomplete(__LINE__);
            LL_WARNS("Metal")
                << "Could not encode native avatar-impostor "
                   "opaque-forward slice: " << error << LL_ENDL;
        }
        else
        {
            LL_DEBUGS("Metal")
                << "Native avatar-impostor opaque-forward slice encoded "
                << capture.batches.size() << " batches at "
                << capture.width << "x" << capture.height
                << (has_shiny ? "; including live shiny reflection"
                              : "")
                << LL_ENDL;
        }
    }
    else if (capture.complete && !capture.batches.empty())
    {
        capture.markIncomplete(__LINE__);
    }
    capture.impostor_bake_native_valid =
        capture.impostor_bake_native_valid && capture.complete;
    capture.batches.clear();
    capture.avatar_palettes.clear();
    capture.resetCompleteness();
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
}

void LLPipeline::endMetalImpostorAlphaCapture()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->impostor_alpha_active)
    {
        return;
    }
    beginMetalImpostorAlphaPhase();
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    capture.impostor_alpha_active = false;
    capture.impostor_alpha_phase = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
    capture.frame_active = false;
    capture.pass_active = false;
    const bool has_legacy_alpha = std::any_of(
        capture.batches.begin(), capture.batches.end(),
        [](const ALMetalWorldSimpleBatch& batch)
        {
            return batch.material_slot_count != 0 &&
                   batch.material_alpha_mode ==
                       LLMaterial::DIFFUSE_ALPHA_MODE_BLEND;
        });
    const bool legacy_alpha_uses_probes = has_legacy_alpha;
    const bool legacy_alpha_uses_environment = std::any_of(
        capture.batches.begin(), capture.batches.end(),
        [](const ALMetalWorldSimpleBatch& batch)
        {
            const std::size_t slot_count = std::min<std::size_t>(
                batch.material_slot_count, batch.materialSlots().size());
            return batch.material_alpha_mode ==
                       LLMaterial::DIFFUSE_ALPHA_MODE_BLEND &&
                   std::any_of(
                       batch.materialSlots().begin(),
                       batch.materialSlots().begin() + slot_count,
                       [](const ALMetalWorldMaterialSlot& slot)
                       {
                           return slot.env_intensity > 0.f;
                       });
        });
    const bool hero_active = !gCubeSnapshot && isMetalHeroProbeActive();
    const bool ssr_active =
        mResourcePlan.wants(ALRenderResourcePlan::Id::SSRScene) &&
        !gCubeSnapshot;
    if (capture.complete && has_legacy_alpha &&
        (!capture.impostor_legacy_alpha_lighting_valid ||
         (legacy_alpha_uses_probes &&
          !mReflectionMapManager.fillMetalReflectionProbes(
              capture.impostor_reflection_probes))))
    {
        capture.markIncomplete(__LINE__);
        LL_WARNS("Metal")
            << "Could not acquire a coherent glare-lighting pack for the "
               "native avatar-impostor legacy BLEND slice" << LL_ENDL;
    }
    if (capture.complete && legacy_alpha_uses_environment && hero_active &&
        !fillMetalImpostorHeroProbe())
    {
        capture.markIncomplete(__LINE__);
        LL_WARNS("Metal")
            << "Could not acquire the active hero probe for the native "
               "avatar-impostor legacy BLEND slice" << LL_ENDL;
    }
    if (capture.complete && legacy_alpha_uses_environment && ssr_active &&
        !fillMetalImpostorScreenSpaceReflections())
    {
        capture.markIncomplete(__LINE__);
        LL_WARNS("Metal")
            << "Could not acquire coherent screen-space reflection history "
               "for the native avatar-impostor legacy BLEND slice"
            << LL_ENDL;
    }

    if (!capture.complete || capture.batches.empty() ||
        !capture.renderer || !capture.impostor_bake_target)
    {
        if (!capture.complete ||
            (!capture.batches.empty() &&
             (!capture.renderer || !capture.impostor_bake_target)))
        {
            capture.impostor_bake_native_valid = false;
        }
        capture.impostor_bake_native_complete = true;
        capture.batches.clear();
        capture.avatar_palettes.clear();
        return;
    }

    ALMetalWorldGBufferScene scene;
    scene.batches = capture.batches.data();
    scene.batch_count = capture.batches.size();
    scene.width = capture.width;
    scene.height = capture.height;
    scene.normal_hdr = capture.normal_hdr;
    scene.hdr = capture.hdr;
    scene.reverse_z = capture.reverse_z;
    scene.reflection_probes = legacy_alpha_uses_probes
        ? &capture.impostor_reflection_probes : nullptr;
    scene.hero_probe = legacy_alpha_uses_environment && hero_active
        ? &capture.impostor_hero_probe : nullptr;
    scene.screen_space_reflections =
        legacy_alpha_uses_environment && ssr_active
        ? &capture.impostor_screen_space_reflections : nullptr;
    scene.legacy_alpha_lighting = has_legacy_alpha
        ? &capture.impostor_legacy_alpha_lighting : nullptr;
    scene.directional_shadows =
        has_legacy_alpha && capture.impostor_legacy_alpha_uses_shadows &&
                capture.impostor_directional_shadows.depth_texture
            ? &capture.impostor_directional_shadows
            : nullptr;
    std::string error;
    if (!capture.renderer->compositeImpostorPostDeferred(
            *capture.impostor_bake_target, scene, &error))
    {
        capture.impostor_bake_native_valid = false;
        LL_WARNS("Metal")
            << "Could not encode native avatar-impostor alpha slice: "
            << error << LL_ENDL;
    }
    else
    {
        LL_DEBUGS("Metal")
            << "Native avatar-impostor alpha slice encoded "
            << capture.batches.size() << " batches at "
            << capture.width << "x" << capture.height
            << (has_legacy_alpha
                    ? "; including glare-dependent legacy BLEND coverage"
                    : "")
            << LL_ENDL;
    }
    capture.impostor_bake_native_complete = true;
    capture.batches.clear();
    capture.avatar_palettes.clear();
}

static void buildMetalWorldDrawMatrices(
    const LLMatrix4a* model_matrix, LLMatrix4a& modelview,
    LLMatrix4a& modelview_projection)
{
    // The native batch contract owns its transforms. Reconstruct the same
    // object-to-eye matrix as LLRenderPass::applyModelMatrix instead of
    // reading it back from gGL's mutable matrix stack. This is required for a
    // direct Metal scene traversal that never binds a GL program or target.
    modelview = LLViewerCamera::getCurrent().getModelview();
    if (model_matrix)
    {
        modelview.setMul(*model_matrix, modelview);
    }
    modelview_projection.setMul(
        modelview, LLViewerCamera::getCurrent().getProjection());
}

static void buildMetalWorldDrawMatrices(
    const LLDrawInfo& params, LLMatrix4a& modelview,
    LLMatrix4a& modelview_projection)
{
    buildMetalWorldDrawMatrices(
        params.mModelMatrix, modelview, modelview_projection);
}

static bool buildMetalWorldDrawMatrices(
    const LLMatrix4a* model_matrix, LLMatrix4a& modelview,
    LLMatrix4a& inverse_modelview, LLMatrix4a& modelview_projection)
{
    buildMetalWorldDrawMatrices(
        model_matrix, modelview, modelview_projection);
    return inverse_modelview.setAffineInverse(modelview);
}

static bool buildMetalWorldDrawMatrices(
    const LLDrawInfo& params, LLMatrix4a& modelview,
    LLMatrix4a& inverse_modelview, LLMatrix4a& modelview_projection)
{
    return buildMetalWorldDrawMatrices(
        params.mModelMatrix, modelview, inverse_modelview,
        modelview_projection);
}

void LLPipeline::invalidateMetalReflectionProbeScene()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->direct_probe_scene_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    capture.markIncomplete(__LINE__);
    capture.batches.clear();
    capture.avatar_palettes.clear();
    capture.direct_avatar_alpha = false;
    capture.direct_avatar_alpha_state_active = false;
}

void LLPipeline::captureMetalReflectionProbeScene()
{
    if (!isMetalProbeFaceCaptureActive() ||
        !mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    struct DirectPass
    {
        U32 type;
        bool rigged;
        bool alpha_mask;
        bool batch_textures;
        bool skip_indexed_materials;
    };
    static constexpr DirectPass passes[] = {
        { LLRenderPass::PASS_SIMPLE, false, false, true, false },
        { LLRenderPass::PASS_SIMPLE_RIGGED, true, false, true, false },
        { LLRenderPass::PASS_ALPHA_MASK, false, true, true, true },
        { LLRenderPass::PASS_ALPHA_MASK_RIGGED, true, true, true, true },
        { LLRenderPass::PASS_GRASS, false, true, false, false },
    };

    capture.direct_probe_scene_active = true;
    for (const DirectPass& pass : passes)
    {
        beginMetalWorldGBufferPass(pass.rigged, pass.alpha_mask);
        auto* at = beginRenderMap(pass.type);
        auto* end = endRenderMap(pass.type);
        for (; at != end; )
        {
            LLDrawInfo* info = *at;
            LLCullResult::increment_iterator(at, end);
            if (!info)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                break;
            }
            if (pass.skip_indexed_materials &&
                info->mMaterialSlotList.size() > 1)
            {
                // The GL alpha-mask pool excludes these from the scalar
                // sweep as well; indexed legacy material masks have their
                // own pass contract.
                continue;
            }

            captureMetalWorldGBufferBatch(*info, pass.batch_textures);
            if (!capture.complete)
            {
                break;
            }
        }
        endMetalWorldGBufferPass();
        if (!capture.complete)
        {
            break;
        }
    }
    for (bool rigged : { false, true })
    {
        if (!capture.complete)
        {
            break;
        }
        for (const LLDrawPoolMaterials::DeferredPassDescription& pass :
             LLDrawPoolMaterials::DEFERRED_PASSES)
        {
            beginMetalWorldMaterialPass(
                rigged, pass.alphaMode(), pass.hasNormalMap(),
                pass.hasSpecularMap());
            auto* at = beginRenderMap(
                pass.render_type + (rigged ? 1 : 0));
            auto* end = endRenderMap(
                pass.render_type + (rigged ? 1 : 0));
            for (; at != end; )
            {
                LLDrawInfo* info = *at;
                LLCullResult::increment_iterator(at, end);
                if (!info)
                {
                    capture.markIncomplete(__LINE__);
                    capture.batches.clear();
                    break;
                }
                captureMetalWorldMaterialBatch(
                    *info, info->mMaterialSlotList.size() > 1);
                if (!capture.complete)
                {
                    break;
                }
            }
            endMetalWorldGBufferPass();
            if (!capture.complete)
            {
                break;
            }
        }
        if (!capture.complete)
        {
            break;
        }
    }

    // Legacy bump geometry uses the same CPU render maps as its former GL
    // producer, but resolves the normal image without binding a texture unit.
    // Preserve that pool's two-pass alpha classification in the direct Metal
    // transaction.
    for (bool rigged : { false, true })
    {
        if (!capture.complete)
        {
            break;
        }
        const U32 type = rigged
            ? LLRenderPass::PASS_BUMP_RIGGED
            : LLRenderPass::PASS_BUMP;
        std::vector<LLDrawInfo*> masked;
        beginMetalWorldGBufferPass(rigged, false);
        auto* at = beginRenderMap(type);
        auto* end = endRenderMap(type);
        U8 last_bump = 255;
        LLViewerTexture* last_source = nullptr;
        LLViewerTexture* last_normal = nullptr;
        for (; at != end; )
        {
            LLDrawInfo* info = *at;
            LLCullResult::increment_iterator(at, end);
            if (!info)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                break;
            }
            if (LLDrawPoolBump::bumpCanDiscard(*info))
            {
                masked.push_back(info);
                continue;
            }
            if (info->mBump != last_bump ||
                info->mTexture.get() != last_source)
            {
                last_bump = info->mBump;
                last_source = info->mTexture.get();
                last_normal = LLDrawPoolBump::resolveBumpMap(*info);
            }
            captureMetalWorldBumpBatch(*info, last_normal);
            if (!capture.complete)
            {
                break;
            }
        }
        endMetalWorldGBufferPass();
        if (!capture.complete)
        {
            break;
        }

        beginMetalWorldGBufferPass(rigged, true);
        last_bump = 255;
        last_source = nullptr;
        last_normal = nullptr;
        for (LLDrawInfo* info : masked)
        {
            if (!info)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                break;
            }
            if (info->mBump != last_bump ||
                info->mTexture.get() != last_source)
            {
                last_bump = info->mBump;
                last_source = info->mTexture.get();
                last_normal = LLDrawPoolBump::resolveBumpMap(*info);
            }
            captureMetalWorldBumpBatch(*info, last_normal);
            if (!capture.complete)
            {
                break;
            }
        }
        endMetalWorldGBufferPass();
    }

    struct PBRPass
    {
        U32 type;
        bool rigged;
        bool alpha_mask;
    };
    static constexpr PBRPass pbr_passes[] = {
        { LLRenderPass::PASS_GLTF_PBR, false, false },
        { LLRenderPass::PASS_GLTF_PBR_RIGGED, true, false },
        { LLRenderPass::PASS_GLTF_PBR_ALPHA_MASK, false, true },
        { LLRenderPass::PASS_GLTF_PBR_ALPHA_MASK_RIGGED, true, true },
    };
    for (const PBRPass& pass : pbr_passes)
    {
        if (!capture.complete)
        {
            break;
        }
        beginMetalWorldPBRPass(pass.rigged, pass.alpha_mask);
        auto* at = beginRenderMap(pass.type);
        auto* end = endRenderMap(pass.type);
        for (; at != end; )
        {
            LLDrawInfo* info = *at;
            LLCullResult::increment_iterator(at, end);
            if (!info)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                break;
            }
            captureMetalWorldPBRBatch(
                *info, info->mGLTFMaterialList.size() > 1);
            if (!capture.complete)
            {
                break;
            }
        }
        endMetalWorldGBufferPass();
    }

    if (capture.complete && hasRenderType(LLDrawPool::POOL_TREE))
    {
        beginMetalWorldGBufferPass(false, true);
        for (LLDrawPool* pool : mPools)
        {
            if (pool->getType() != LLDrawPool::POOL_TREE)
            {
                continue;
            }
            LLFacePool* tree_pool = static_cast<LLFacePool*>(pool);
            if (tree_pool->mDrawFace.empty())
            {
                continue;
            }
            LLViewerTexture* source_texture = tree_pool->getTexture();
            LLViewerTexture* draw_texture = sRenderTextures
                ? source_texture
                : LLViewerFetchedTexture::sDefaultDiffuseImagep.get();
            if (source_texture)
            {
                // Preserve the pool owner's full-resolution Linden-tree
                // request even after GL draw execution is removed.
                source_texture->addTextureStats(1024.f * 1024.f);
            }
            for (LLFace* face : tree_pool->mDrawFace)
            {
                if (!face)
                {
                    capture.markIncomplete(__LINE__);
                    capture.batches.clear();
                    break;
                }
                if (!face->getVertexBuffer())
                {
                    // The GL pool also draws nothing for an unbuilt face.
                    continue;
                }
                captureMetalWorldTreeBatch(face, draw_texture);
                if (!capture.complete)
                {
                    break;
                }
            }
            if (!capture.complete)
            {
                break;
            }
        }
        endMetalWorldGBufferPass();
    }
    if (capture.complete && hasRenderType(LLDrawPool::POOL_TERRAIN))
    {
        for (LLDrawPool* pool : mPools)
        {
            if (pool->getType() != LLDrawPool::POOL_TERRAIN)
            {
                continue;
            }
            static_cast<LLDrawPoolTerrain*>(pool)
                ->captureMetalReflectionProbe();
            if (!capture.complete)
            {
                break;
            }
        }
    }
    for (U32 pool_type : { LLDrawPool::POOL_AVATAR,
                           LLDrawPool::POOL_CONTROL_AV })
    {
        if (!capture.complete)
        {
            break;
        }
        if (!hasRenderType(pool_type))
        {
            continue;
        }
        for (S32 pass = 0;
             capture.complete && pass < 3; ++pass)
        {
            for (LLDrawPool* pool : mPools)
            {
                if (pool->getType() != pool_type ||
                    pool->getSkipRenderFlag())
                {
                    continue;
                }
                static_cast<LLDrawPoolAvatar*>(pool)
                    ->captureMetalDeferred(pass);
                if (!capture.complete)
                {
                    break;
                }
            }
        }
    }
    if (capture.complete && hasRenderType(LLDrawPool::POOL_WL_SKY))
    {
        for (LLDrawPool* pool : mPools)
        {
            if (pool->getType() != LLDrawPool::POOL_WL_SKY)
            {
                continue;
            }
            static_cast<LLDrawPoolWLSky*>(pool)
                ->captureMetalReflectionProbe();
            break;
        }
    }
    capture.direct_probe_scene_active = false;
    capture.pass_active = false;
}

void LLPipeline::captureMetalReflectionProbeAvatarAlpha(U32 pool_type)
{
    if (!isMetalProbeFaceCaptureActive() ||
        !mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase ||
        !mMetalWorldSimpleCapture->complete ||
        (pool_type != LLDrawPool::POOL_AVATAR &&
         pool_type != LLDrawPool::POOL_CONTROL_AV))
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool prior_direct_scene = capture.direct_probe_scene_active;
    capture.direct_probe_scene_active = true;
    capture.direct_avatar_alpha = false;
    capture.direct_avatar_alpha_state_active = false;
    for (LLDrawPool* pool : mPools)
    {
        if (pool->getType() != pool_type || pool->getSkipRenderFlag())
        {
            continue;
        }
        static_cast<LLDrawPoolAvatar*>(pool)
            ->captureMetalPostDeferred();
        if (!capture.complete)
        {
            break;
        }
    }
    capture.direct_avatar_alpha = false;
    capture.direct_avatar_alpha_state_active = false;
    capture.direct_probe_scene_active = prior_direct_scene;
    capture.pass_active = false;
}

void LLPipeline::captureMetalReflectionProbePostDeferred()
{
    if (!isMetalProbeFaceCaptureActive() ||
        !mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    capture.direct_probe_scene_active = true;

    const auto fail_null_draw = [&]()
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
    };
    const auto for_each_draw = [&](U32 type, const auto& visitor)
    {
        auto* at = beginRenderMap(type);
        auto* end = endRenderMap(type);
        for (; at != end && capture.complete; )
        {
            LLDrawInfo* info = *at;
            LLCullResult::increment_iterator(at, end);
            if (!info)
            {
                fail_null_draw();
                break;
            }
            visitor(*info);
        }
    };
    const auto capture_flat_pass = [&](U32 type, bool rigged,
                                       bool alpha_mask,
                                       bool batch_textures,
                                       bool skip_indexed_materials)
    {
        if (!capture.complete)
        {
            return;
        }
        beginMetalImpostorFullbrightPass(rigged, alpha_mask);
        for_each_draw(type, [&](LLDrawInfo& info)
        {
            if (!skip_indexed_materials ||
                info.mMaterialSlotList.size() <= 1)
            {
                captureMetalWorldGBufferBatch(info, batch_textures);
            }
        });
        endMetalWorldGBufferPass();
    };

    const bool water_drawn = mWaterPool &&
        hasRenderType(LLPipeline::RENDER_TYPE_WATER) &&
        mWaterPool->getNumPostDeferredPasses() > 0;
    const bool low_detail_probe =
        shaderInputs().mGlobal.mProbeLevel == 0 && gCubeSnapshot;

    // The exclusion pass was formerly reached through pushUntexturedBatch,
    // whose world-capture hook does not exist. Direct enumeration both
    // removes the GL stencil draw and finally gives the native water owner
    // the actual exclusion geometry paired with its field description.
    if (capture.complete && water_drawn && mWaterExclusionPool &&
        hasRenderType(LLPipeline::RENDER_TYPE_WATEREXCLUSION))
    {
        beginMetalWorldWaterExclusionPass();
        for_each_draw(LLRenderPass::PASS_INVISIBLE,
                      [&](LLDrawInfo& info)
        {
            captureMetalWorldGBufferBatch(info, false);
        });
        endMetalWorldGBufferPass();
    }

    // Pool order: fullbright, shiny/emboss, PBR glow, masked
    // fullbright, transparent avatars, legacy glow, pre-water alpha,
    // water, then post-water alpha.
    if (capture.complete &&
        hasRenderType(LLPipeline::RENDER_TYPE_FULLBRIGHT))
    {
        capture_flat_pass(LLRenderPass::PASS_FULLBRIGHT,
                          false, false, true, false);
        capture_flat_pass(LLRenderPass::PASS_FULLBRIGHT_RIGGED,
                          true, false, true, false);
    }

    if (capture.complete && hasRenderType(LLPipeline::RENDER_TYPE_BUMP))
    {
        for (bool rigged : { false, true })
        {
            const U32 shiny_type = rigged
                ? LLRenderPass::PASS_FULLBRIGHT_SHINY_RIGGED
                : LLRenderPass::PASS_FULLBRIGHT_SHINY;
            beginMetalImpostorShinyPass(rigged);
            for_each_draw(shiny_type, [&](LLDrawInfo& info)
            {
                captureMetalWorldGBufferBatch(info, true);
            });
            endMetalWorldGBufferPass();
            if (!capture.complete)
            {
                break;
            }

            const U32 emboss_type = rigged
                ? LLRenderPass::PASS_POST_BUMP_RIGGED
                : LLRenderPass::PASS_POST_BUMP;
            beginMetalImpostorEmbossPass(rigged);
            for_each_draw(emboss_type, [&](LLDrawInfo& info)
            {
                captureMetalWorldBumpBatch(
                    info, LLDrawPoolBump::resolveBumpMap(info));
            });
            endMetalWorldGBufferPass();
            if (!capture.complete)
            {
                break;
            }
        }
    }

    if (capture.complete && sRenderGlow &&
        hasRenderType(LLPipeline::RENDER_TYPE_GLTF_PBR))
    {
        for (bool rigged : { false, true })
        {
            beginMetalWorldPBRGlowPass(rigged);
            for_each_draw(
                rigged ? LLRenderPass::PASS_GLTF_GLOW_RIGGED
                       : LLRenderPass::PASS_GLTF_GLOW,
                [&](LLDrawInfo& info)
            {
                captureMetalWorldPBRBatch(
                    info, info.mGLTFMaterialList.size() > 1);
            });
            endMetalWorldGBufferPass();
            if (!capture.complete)
            {
                break;
            }
        }
    }

    if (capture.complete &&
        hasRenderType(LLPipeline::RENDER_TYPE_FULLBRIGHT_ALPHA_MASK))
    {
        capture_flat_pass(LLRenderPass::PASS_FULLBRIGHT_ALPHA_MASK,
                          false, true, true, true);
        capture_flat_pass(
            LLRenderPass::PASS_FULLBRIGHT_ALPHA_MASK_RIGGED,
            true, true, true, true);
    }

    for (U32 pool_type : { LLDrawPool::POOL_AVATAR,
                           LLDrawPool::POOL_CONTROL_AV })
    {
        if (!capture.complete)
        {
            break;
        }
        if (hasRenderType(pool_type))
        {
            captureMetalReflectionProbeAvatarAlpha(pool_type);
            capture.direct_probe_scene_active = true;
        }
    }

    if (capture.complete && sRenderGlow &&
        hasRenderType(LLPipeline::RENDER_TYPE_GLOW))
    {
        for (bool rigged : { false, true })
        {
            beginMetalWorldLegacyGlowPass(rigged);
            for_each_draw(
                rigged ? LLRenderPass::PASS_GLOW_RIGGED
                       : LLRenderPass::PASS_GLOW,
                [&](LLDrawInfo& info)
            {
                captureMetalWorldLegacyGlowBatch(
                    info, info.mMaterialSlotList.size() > 1);
            });
            endMetalWorldGBufferPass();
            if (!capture.complete)
            {
                break;
            }
        }
    }

    const bool water_haze = capture.complete && !low_detail_probe &&
        !sImpostorRender && RenderDeferredAtmospheric &&
        (sUnderWaterRender || water_drawn) &&
        (sUnderWaterRender ||
         mWaterSurface.drawnFrom(*LLViewerCamera::getInstance())) &&
        (sUnderWaterRender || ALRenderResourcePlan::refractsWater(
             renderPack(), sRenderTransparentWater));
    if (water_haze)
    {
        captureMetalWorldWaterHaze();
    }

    if (capture.complete &&
        hasRenderType(LLPipeline::RENDER_TYPE_ALPHA_PRE_WATER))
    {
        for (LLDrawPool* pool : mPools)
        {
            if (pool->getType() == LLDrawPool::POOL_ALPHA_PRE_WATER &&
                !pool->getSkipRenderFlag())
            {
                static_cast<LLDrawPoolAlpha*>(pool)
                    ->captureMetalReflectionProbe();
            }
        }
    }

    const bool atmospherics = capture.complete && !low_detail_probe &&
        !sImpostorRender && RenderDeferredAtmospheric;
    if (atmospherics && sUnderWaterRender)
    {
        captureMetalWorldAtmospherics();
    }

    if (capture.complete && water_drawn)
    {
        static_cast<LLDrawPoolWater*>(mWaterPool)
            ->captureMetalReflectionProbe();
    }

    if (atmospherics && !sUnderWaterRender)
    {
        captureMetalWorldAtmospherics();
    }

    if (capture.complete &&
        hasRenderType(LLPipeline::RENDER_TYPE_ALPHA_POST_WATER))
    {
        for (LLDrawPool* pool : mPools)
        {
            if (pool->getType() == LLDrawPool::POOL_ALPHA_POST_WATER &&
                !pool->getSkipRenderFlag())
            {
                static_cast<LLDrawPoolAlpha*>(pool)
                    ->captureMetalReflectionProbe();
            }
        }
    }

    capture.direct_probe_scene_active = false;
    capture.pass_active = false;
}

void LLPipeline::captureMetalWorldGBufferBatch(const LLDrawInfo& params,
                                               bool batch_textures)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || !params.mCount)
    {
        return;
    }
    // Legacy glow has a deliberately smaller vertex contract and is captured
    // directly by its native draw-pool enumerator.
    if (capture.legacy_glow)
    {
        return;
    }
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    if (capture.water_exclusion)
    {
        if (!buffer ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
            !buffer->getMetalVertexBuffer() ||
            !buffer->getMetalIndexBuffer())
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        LLMatrix4a modelview;
        LLMatrix4a modelview_projection;
        buildMetalWorldDrawMatrices(
            params, modelview, modelview_projection);
        // Build directly in the retained vector. A failed field/resource
        // check below clears the transaction before returning, so no partial
        // record can reach the renderer.
        ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = static_cast<std::size_t>(params.mOffset) *
                             buffer->getIndexStride();
        batch.index_type = buffer->getIndexStride() == 4
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = params.mCount;
        batch.water_exclusion = true;
        std::memcpy(batch.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
        std::memcpy(batch.modelview, modelview.getF32ptr(),
                    sizeof(batch.modelview));
        return;
    }
    const bool indexed_textures =
        batch_textures && params.mTextureList.size() > 1;
    const std::size_t texture_count = indexed_textures
        ? params.mTextureList.size() : 1;
    if (!buffer || texture_count >
            ALMetalWorldSimpleBatch::max_diffuse_textures ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        (!capture.impostor_fullbright &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_NORMAL)) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_COLOR) ||
        (indexed_textures &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_TEXTURE_INDEX)) ||
        !buffer->getMetalVertexBuffer() || !buffer->getMetalIndexBuffer())
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    LLMatrix4a modelview;
    LLMatrix4a inverse_modelview;
    LLMatrix4a modelview_projection;
    if (!buildMetalWorldDrawMatrices(
            params, modelview, inverse_modelview,
            modelview_projection))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.normal_offset = buffer->hasDataType(LLVertexBuffer::TYPE_NORMAL)
        ? buffer->getOffset(LLVertexBuffer::TYPE_NORMAL) : 0;
    batch.texcoord_offset = buffer->getOffset(LLVertexBuffer::TYPE_TEXCOORD0);
    batch.color_offset = buffer->getOffset(LLVertexBuffer::TYPE_COLOR);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = static_cast<std::size_t>(params.mOffset) *
                         buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = params.mCount;
    batch.impostor_fullbright = capture.impostor_fullbright;
    batch.impostor_shiny = capture.impostor_shiny;
    batch.impostor_emboss = capture.impostor_emboss;
    batch.alpha_mask = capture.alpha_mask;
    batch.alpha_cutoff = capture.alpha_mask
        ? params.mAlphaMaskCutoff : 0.f;
    batch.texture_count = static_cast<U32>(texture_count);
    for (std::size_t index = 0; index < texture_count; ++index)
    {
        LLViewerTexture* texture = indexed_textures
            ? params.mTextureList[index].get() : params.mTexture.get();
        if (!texture)
        {
            texture = LLViewerFetchedTexture::sWhiteImagep.get();
        }
        LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
        ALMetalTexture* metal_texture = image
            ? image->getMetalTexture() : nullptr;
        if (!metal_texture)
        {
            // Preserve streamed-texture substitution without consulting a GL
            // object name: native publication readiness is authoritative.
            LLViewerFetchedTexture* fallback =
                LLViewerFetchedTexture::sDefaultImagep.get();
            LLImageGL* fallback_image = fallback
                ? fallback->getGLTexture() : nullptr;
            metal_texture = fallback_image
                ? fallback_image->getMetalTexture() : nullptr;
        }
        batch.diffuse_textures[index] = metal_texture;
        if (!batch.diffuse_textures[index])
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
    }
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    std::memcpy(batch.modelview, modelview.getF32ptr(),
                sizeof(batch.modelview));

    const F32* inverse = inverse_modelview.getF32ptr();
    const F32* modelview_values = modelview.getF32ptr();
    for (U32 column = 0; column < 3; ++column)
    {
        batch.normal_matrix[column][0] = inverse[0 * 4 + column];
        batch.normal_matrix[column][1] = inverse[1 * 4 + column];
        batch.normal_matrix[column][2] = inverse[2 * 4 + column];
        batch.rigged_normal_matrix[column][0] =
            modelview_values[column * 4 + 0];
        batch.rigged_normal_matrix[column][1] =
            modelview_values[column * 4 + 1];
        batch.rigged_normal_matrix[column][2] =
            modelview_values[column * 4 + 2];
    }
    if (!indexed_textures && params.mTextureMatrix &&
        (!gCubeSnapshot || mHeroProbeManager.isMirrorPass()))
    {
        std::memcpy(batch.texture_matrix, params.mTextureMatrix->mMatrix,
                    sizeof(batch.texture_matrix));
    }
    if (capture.rigged)
    {
        if (!params.mAvatar || !params.mSkinInfo ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        const LLVOAvatar::MatrixPaletteCache& palette =
            params.mAvatar->updateSkinInfoMatrixPalette(params.mSkinInfo);
        const U32 joint_count =
            static_cast<U32>(palette.mMatrixPalette.size());
        if (joint_count == 0 || palette.mGLMp.size() !=
                4 + static_cast<std::size_t>(joint_count) * 12)
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        batch.weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT4);
        batch.skin_palette = palette.mGLMp.data();
        batch.skin_palette_float_count = palette.mGLMp.size();
        batch.skin_joint_count = joint_count;
    }
}

void LLPipeline::captureMetalWorldHighlightBatch(
    LLVertexBuffer* buffer, U32 index_count, U32 index_start,
    LLViewerTexture* texture, const LLColor4& color, U32 texcoord_type)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
    if (!capture.complete || !buffer || index_count == 0 ||
        texcoord_type < LLVertexBuffer::TYPE_TEXCOORD0 ||
        texcoord_type > LLVertexBuffer::TYPE_TEXCOORD3 || !image ||
        !image->getMetalTexture() ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer())
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.highlight_batches.clear();
        return;
    }

    const auto texcoord_attribute =
        static_cast<LLVertexBuffer::AttributeType>(texcoord_type);
    if (!buffer->hasDataType(texcoord_attribute))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.highlight_batches.clear();
        return;
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());

    ALMetalWorldHighlightBatch batch;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_VERTEX);
    batch.texcoord_offset = buffer->getOffset(texcoord_attribute);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = static_cast<std::size_t>(index_start) *
                         buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = index_count;
    batch.texture = image->getMetalTexture();
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    std::memcpy(batch.texture_matrix,
                gGL.getTextureMatrix().getF32ptr(),
                sizeof(batch.texture_matrix));
    std::memcpy(batch.color, color.mV, sizeof(batch.color));
    capture.highlight_batches.push_back(batch);
}

void LLPipeline::captureMetalDebugAlphaBatch(
    const LLDrawInfo& params, LLViewerTexture* texture,
    const LLColor4& color)
{
    const bool hud_capture = sRenderingHUDs &&
        gGL.hasMetalUITextureCapture();
    const bool world_capture = mMetalWorldSimpleCapture &&
        mMetalWorldSimpleCapture->frame_active &&
        mMetalWorldSimpleCapture->world_post_deferred_active &&
        !mMetalWorldSimpleCapture->world_post_deferred_phase;
    if (!hud_capture && !world_capture)
    {
        return;
    }

    MetalWorldSimpleCapture* capture = world_capture
        ? mMetalWorldSimpleCapture.get() : nullptr;
    const auto fail = [capture, hud_capture](const char* reason)
    {
        if (capture)
        {
            capture->markIncomplete(__LINE__);
            capture->batches.clear();
            capture->highlight_batches.clear();
        }
        if (hud_capture)
        {
            gGL.invalidateMetalUITextureCapture(reason);
        }
    };

    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
    const bool rigged = params.mAvatar != nullptr;
    if (!buffer || params.mCount == 0 || !image ||
        !image->getMetalTexture() ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer() ||
        (buffer->getIndexStride() != 2 &&
         buffer->getIndexStride() != 4) ||
        (rigged &&
         (!params.mSkinInfo ||
          !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))))
    {
        fail("Highlight Transparent geometry is incomplete");
        return;
    }

    const F32* skin_palette = nullptr;
    std::size_t skin_palette_float_count = 0;
    U32 skin_joint_count = 0;
    std::size_t weight_offset = 0;
    if (rigged)
    {
        const LLVOAvatar::MatrixPaletteCache& palette =
            params.mAvatar->updateSkinInfoMatrixPalette(params.mSkinInfo);
        skin_joint_count = static_cast<U32>(palette.mMatrixPalette.size());
        skin_palette_float_count = palette.mGLMp.size();
        if (skin_joint_count == 0 ||
            skin_palette_float_count !=
                4u + static_cast<std::size_t>(skin_joint_count) * 12u)
        {
            fail("Highlight Transparent skin palette is incomplete");
            return;
        }
        skin_palette = palette.mGLMp.data();
        weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT4);
    }

    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    const std::size_t index_offset =
        static_cast<std::size_t>(params.mOffset) *
        buffer->getIndexStride();

    if (world_capture)
    {
        ALMetalWorldHighlightBatch batch;
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.texcoord_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_TEXCOORD0);
        batch.weight_offset = weight_offset;
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = index_offset;
        batch.index_type = buffer->getIndexStride() == 4
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = params.mCount;
        batch.texture = image->getMetalTexture();
        batch.skin_palette = skin_palette;
        batch.skin_palette_float_count = skin_palette_float_count;
        batch.skin_joint_count = skin_joint_count;
        std::memcpy(batch.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
        for (U32 diagonal = 0; diagonal < 4; ++diagonal)
        {
            batch.texture_matrix[diagonal * 4 + diagonal] = 1.f;
        }
        std::memcpy(batch.color, color.mV, sizeof(batch.color));
        // renderDebugAlpha runs after forwardRender restores RGB-only output.
        // Preserve glow/coverage alpha underneath the diagnostic overlay.
        batch.write_alpha = false;
        capture->highlight_batches.push_back(batch);
    }

    if (hud_capture)
    {
        ALMetalHUDIndexedBatch batch;
        batch.shader = rigged
            ? ALMetalHUDShader::highlight_skinned
            : ALMetalHUDShader::highlight;
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.texcoord_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_TEXCOORD0);
        batch.weight_offset = weight_offset;
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = index_offset;
        batch.index_type = buffer->getIndexStride() == 4
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = params.mCount;
        batch.textures[0] = image->getMetalTexture();
        batch.texture_count = 1;
        batch.skin_palette = skin_palette;
        batch.skin_palette_float_count = skin_palette_float_count;
        batch.skin_joint_count = skin_joint_count;
        batch.double_sided = false;
        std::memcpy(batch.matrices.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.matrices.modelview_projection));
        for (U32 diagonal = 0; diagonal < 4; ++diagonal)
        {
            batch.matrices.texture0[diagonal * 4 + diagonal] = 1.f;
        }
        std::memcpy(batch.highlight_color, color.mV,
                    sizeof(batch.highlight_color));
        gGL.drawMetalHUDIndexedBatch(batch);
    }
}

void LLPipeline::captureMetalWorldBumpBatch(
    const LLDrawInfo& params, LLViewerTexture* normal_texture)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete)
    {
        return;
    }
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    LLImageGL* normal_image = normal_texture
        ? normal_texture->getGLTexture() : nullptr;
    if (normal_image && !normal_image->getMetalTexture())
    {
        LLViewerTexture* fallback =
            LLViewerFetchedTexture::sDefaultImagep.get();
        LLImageGL* fallback_image = fallback
            ? fallback->getGLTexture() : nullptr;
        if (fallback_image && fallback_image->getMetalTexture())
        {
            // A fetched/generated bump still waiting for native publication
            // uses the same default image as the retained bind path.
            normal_image = fallback_image;
        }
    }
    if (capture.impostor_emboss)
    {
        if (!params.mCount || !buffer || !normal_image ||
            !normal_image->getMetalTexture() ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD1) ||
            !buffer->getMetalVertexBuffer() ||
            !buffer->getMetalIndexBuffer() ||
            (capture.rigged &&
             (!params.mAvatar || !params.mSkinInfo ||
              !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))))
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }

        LLMatrix4a modelview;
        LLMatrix4a modelview_projection;
        buildMetalWorldDrawMatrices(
            params, modelview, modelview_projection);

        ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
        batch.vertices = buffer->getMetalVertexBuffer();
        batch.position_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_VERTEX);
        batch.texcoord_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_TEXCOORD0);
        batch.texcoord1_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_TEXCOORD1);
        batch.vertex_count = buffer->getNumVerts();
        batch.indices = buffer->getMetalIndexBuffer();
        batch.index_offset = static_cast<std::size_t>(params.mOffset) *
                             buffer->getIndexStride();
        batch.index_type = buffer->getIndexStride() == 4
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        batch.index_count = params.mCount;
        batch.diffuse_textures[0] = normal_image->getMetalTexture();
        batch.texture_count = 1;
        batch.impostor_emboss = true;
        std::memcpy(batch.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
        if (params.mTextureMatrix &&
            (!gCubeSnapshot || mHeroProbeManager.isMirrorPass()))
        {
            std::memcpy(batch.texture_matrix,
                        params.mTextureMatrix->mMatrix,
                        sizeof(batch.texture_matrix));
        }
        if (capture.rigged)
        {
            const LLVOAvatar::MatrixPaletteCache& palette =
                params.mAvatar->updateSkinInfoMatrixPalette(
                    params.mSkinInfo);
            const U32 joint_count = static_cast<U32>(
                palette.mMatrixPalette.size());
            if (joint_count == 0 || palette.mGLMp.size() !=
                    4 + static_cast<std::size_t>(joint_count) * 12)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
            batch.weight_offset = buffer->getOffset(
                LLVertexBuffer::TYPE_WEIGHT4);
            batch.skin_palette = palette.mGLMp.data();
            batch.skin_palette_float_count = palette.mGLMp.size();
            batch.skin_joint_count = joint_count;
        }
        return;
    }
    if (!buffer ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TANGENT) ||
        !normal_image || !normal_image->getMetalTexture())
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    const std::size_t prior_count = capture.batches.size();
    captureMetalWorldGBufferBatch(params, false);
    if (!capture.complete || capture.batches.size() == prior_count)
    {
        return;
    }
    ALMetalWorldSimpleBatch& batch = capture.batches.back();
    batch.tangent_offset = buffer->getOffset(LLVertexBuffer::TYPE_TANGENT);
    batch.normal_texture = normal_image->getMetalTexture();
}

void LLPipeline::captureMetalWorldMaterialBatch(
    const LLDrawInfo& params, bool indexed_materials)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const std::size_t slot_count = indexed_materials
        ? params.mMaterialSlotList.size() : 1;
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    if (!capture.complete || !buffer || slot_count == 0 ||
        slot_count > ALMetalWorldSimpleBatch::max_material_slots ||
        (capture.material_normal_map &&
         (!buffer->hasDataType(LLVertexBuffer::TYPE_TANGENT) ||
          !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD1))) ||
        (capture.material_specular_map &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD2)) ||
        (indexed_materials &&
         (slot_count < 2 ||
          !buffer->hasDataType(LLVertexBuffer::TYPE_TEXTURE_INDEX))))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    const std::size_t prior_count = capture.batches.size();
    captureMetalWorldGBufferBatch(params, false);
    if (!capture.complete || capture.batches.size() == prior_count)
    {
        return;
    }

    ALMetalWorldSimpleBatch& batch = capture.batches.back();
    batch.material_slot_count = static_cast<U32>(slot_count);
    batch.material_alpha_mode = capture.material_alpha_mode;
    batch.texture_count = static_cast<U32>(slot_count);
    if (capture.material_normal_map)
    {
        batch.tangent_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_TANGENT);
        batch.texcoord1_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_TEXCOORD1);
    }
    if (capture.material_specular_map)
    {
        batch.texcoord2_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_TEXCOORD2);
    }
    if (indexed_materials)
    {
        std::memset(batch.texture_matrix, 0,
                    sizeof(batch.texture_matrix));
        for (U32 diagonal = 0; diagonal < 4; ++diagonal)
        {
            batch.texture_matrix[diagonal * 4 + diagonal] = 1.f;
        }
    }

    const auto resolve_material_image = [](LLViewerTexture* texture)
        -> LLImageGL*
    {
        LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
        if (!image || !image->getMetalTexture())
        {
            // Native publication readiness, rather than a GL name, selects
            // the streamed fallback for this Metal-owned pass.
            LLViewerFetchedTexture* fallback =
                LLViewerFetchedTexture::sDefaultImagep.get();
            LLImageGL* fallback_image = fallback
                ? fallback->getGLTexture() : nullptr;
            if (fallback_image && fallback_image->getMetalTexture())
            {
                image = fallback_image;
            }
        }
        return image;
    };

    for (std::size_t slot_index = 0;
         slot_index < slot_count; ++slot_index)
    {
        LLViewerTexture* texture = nullptr;
        LLViewerTexture* normal_texture = nullptr;
        LLViewerTexture* specular_texture = nullptr;
        ALMetalWorldMaterialSlot& destination =
            batch.materialSlots()[slot_index];
        if (indexed_materials)
        {
            const LLDrawInfo::MaterialSlot& source =
                params.mMaterialSlotList[slot_index];
            texture = source.mDiffuse.notNull()
                ? source.mDiffuse.get()
                : LLViewerFetchedTexture::sWhiteImagep.get();
            if (capture.material_normal_map)
            {
                normal_texture = source.mNormalMap.notNull()
                    ? source.mNormalMap.get()
                    : LLViewerFetchedTexture::sFlatNormalImagep.get();
            }
            if (capture.material_specular_map)
            {
                specular_texture = source.mSpecularMap.notNull()
                    ? source.mSpecularMap.get()
                    : LLViewerFetchedTexture::sWhiteImagep.get();
            }
            std::memcpy(destination.specular_color,
                        source.mSpecColor.mV,
                        sizeof(destination.specular_color));
            destination.env_intensity = source.mEnvIntensity;
            destination.alpha_cutoff = source.mAlphaMaskCutoff;
            destination.fullbright = source.mFullbright;
        }
        else
        {
            texture = params.mTexture
                ? params.mTexture.get()
                : LLViewerFetchedTexture::sWhiteImagep.get();
            if (capture.material_normal_map)
            {
                normal_texture = params.mNormalMap
                    ? params.mNormalMap.get()
                    : LLViewerFetchedTexture::sFlatNormalImagep.get();
            }
            if (capture.material_specular_map)
            {
                specular_texture = params.mSpecularMap
                    ? params.mSpecularMap.get()
                    : LLViewerFetchedTexture::sWhiteImagep.get();
            }
            std::memcpy(destination.specular_color,
                        params.mSpecColor.mV,
                        sizeof(destination.specular_color));
            destination.env_intensity = params.mEnvIntensity;
            destination.alpha_cutoff = params.mAlphaMaskCutoff;
            destination.fullbright = params.mFullbright ? 1.f : 0.f;
        }

        LLImageGL* image = resolve_material_image(texture);
        batch.diffuse_textures[slot_index] = image
            ? image->getMetalTexture() : nullptr;
        if (!batch.diffuse_textures[slot_index])
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        if (capture.material_normal_map)
        {
            LLImageGL* normal_image =
                resolve_material_image(normal_texture);
            destination.normal_texture = normal_image
                ? normal_image->getMetalTexture() : nullptr;
            if (!destination.normal_texture)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
        }
        if (capture.material_specular_map)
        {
            LLImageGL* specular_image =
                resolve_material_image(specular_texture);
            destination.specular_texture = specular_image
                ? specular_image->getMetalTexture() : nullptr;
            if (!destination.specular_texture)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
        }
    }
}

void LLPipeline::captureMetalWorldLegacyGlowBatch(
    const LLDrawInfo& params, bool indexed_materials)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active ||
        !mMetalWorldSimpleCapture->legacy_glow)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    const bool indexed_textures = !indexed_materials &&
        params.mTextureList.size() > 1;
    const std::size_t texture_count = indexed_materials
        ? params.mMaterialSlotList.size()
        : indexed_textures ? params.mTextureList.size() : 1;
    if (!capture.complete || !params.mCount || !buffer ||
        texture_count == 0 ||
        texture_count > ALMetalWorldSimpleBatch::max_diffuse_textures ||
        (indexed_materials &&
         texture_count > ALMetalWorldSimpleBatch::max_material_slots) ||
        (indexed_materials && texture_count < 2) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_EMISSIVE) ||
        ((indexed_materials || indexed_textures) &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_TEXTURE_INDEX)) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer())
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    LLMatrix4a modelview;
    LLMatrix4a modelview_projection;
    buildMetalWorldDrawMatrices(
        params, modelview, modelview_projection);

    ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.texcoord_offset = buffer->getOffset(LLVertexBuffer::TYPE_TEXCOORD0);
    batch.emissive_offset = buffer->getOffset(LLVertexBuffer::TYPE_EMISSIVE);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = static_cast<std::size_t>(params.mOffset) *
                         buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = params.mCount;
    batch.texture_count = static_cast<U32>(texture_count);
    batch.legacy_glow = true;
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    if (!indexed_materials && !indexed_textures &&
        params.mTextureMatrix &&
        (!gCubeSnapshot || mHeroProbeManager.isMirrorPass()))
    {
        std::memcpy(batch.texture_matrix, params.mTextureMatrix->mMatrix,
                    sizeof(batch.texture_matrix));
    }

    for (std::size_t slot = 0; slot < texture_count; ++slot)
    {
        LLViewerTexture* texture = nullptr;
        if (indexed_materials)
        {
            const LLDrawInfo::MaterialSlot& material =
                params.mMaterialSlotList[slot];
            texture = material.mDiffuse.get();
        }
        else if (indexed_textures)
        {
            texture = params.mTextureList[slot].get();
        }
        else
        {
            texture = params.mTexture.get();
        }
        if (!texture)
        {
            texture = LLViewerFetchedTexture::sWhiteImagep.get();
        }
        LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
        if (image && !image->getMetalTexture())
        {
            LLViewerTexture* fallback =
                LLViewerFetchedTexture::sDefaultImagep.get();
            LLImageGL* fallback_image = fallback
                ? fallback->getGLTexture() : nullptr;
            if (fallback_image && fallback_image->getMetalTexture())
            {
                image = fallback_image;
            }
        }
        batch.diffuse_textures[slot] = image
            ? image->getMetalTexture() : nullptr;
        if (!batch.diffuse_textures[slot])
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
    }

    if (capture.rigged)
    {
        if (!params.mAvatar || !params.mSkinInfo ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        const LLVOAvatar::MatrixPaletteCache& palette =
            params.mAvatar->updateSkinInfoMatrixPalette(params.mSkinInfo);
        const U32 joint_count =
            static_cast<U32>(palette.mMatrixPalette.size());
        if (joint_count == 0 || palette.mGLMp.size() !=
                4 + static_cast<std::size_t>(joint_count) * 12)
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        batch.weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT4);
        batch.skin_palette = palette.mGLMp.data();
        batch.skin_palette_float_count = palette.mGLMp.size();
        batch.skin_joint_count = joint_count;
    }
}

void LLPipeline::captureMetalWorldPostWaterLegacyGlowBatch(
    const LLDrawInfo& params, bool particle_or_hud_particle)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        !mMetalWorldSimpleCapture->world_post_water_alpha_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    const std::size_t first_batch = capture.batches.size();
    capture.rigged = params.mAvatar != nullptr;
    capture.legacy_glow = true;
    capture.pbr_glow = false;
    capture.pass_active = true;
    captureMetalWorldLegacyGlowBatch(params, false);
    capture.pass_active = false;
    capture.legacy_glow = false;
    if (capture.complete &&
        capture.batches.size() == first_batch + 1)
    {
        ALMetalWorldSimpleBatch& batch = capture.batches.back();
        batch.post_water_glow = true;
        batch.pre_water_particle = particle_or_hud_particle;
    }
}

void LLPipeline::captureMetalWorldPostWaterPBRGlowBatch(
    const LLDrawInfo& params, bool particle_or_hud_particle)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->world_post_deferred_active ||
        !mMetalWorldSimpleCapture->world_post_water_alpha_active ||
        mMetalWorldSimpleCapture->world_post_deferred_phase)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.pass_active)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    const std::size_t first_batch = capture.batches.size();
    capture.rigged = params.mAvatar != nullptr;
    capture.alpha_mask = false;
    capture.pbr = true;
    capture.legacy_glow = false;
    capture.pbr_glow = true;
    capture.pass_active = true;
    captureMetalWorldPBRBatch(params, false);
    capture.pass_active = false;
    capture.pbr = false;
    capture.pbr_glow = false;
    if (capture.complete &&
        capture.batches.size() == first_batch + 1)
    {
        ALMetalWorldSimpleBatch& batch = capture.batches.back();
        batch.post_water_glow = true;
        batch.pre_water_particle = particle_or_hud_particle;
        for (std::size_t slot = 0; slot < batch.pbr_slot_count; ++slot)
        {
            // The alpha pool restores its ordinary 0.004 coverage floor
            // before the group-local emissive replay. BLEND glow also
            // weights luminosity by that sampled base coverage.
            batch.pbrSlots()[slot].alpha_cutoff = 0.004f;
        }
    }
}

void LLPipeline::captureMetalWorldPBRBatch(
    const LLDrawInfo& params, bool indexed_materials)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active ||
        !mMetalWorldSimpleCapture->pbr)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const std::size_t slot_count = indexed_materials
        ? params.mGLTFMaterialList.size() : 1;
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    if (!capture.complete || !buffer || slot_count == 0 ||
        slot_count > ALMetalWorldSimpleBatch::max_material_slots ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TANGENT) ||
        (capture.pbr_glow &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_EMISSIVE)) ||
        (indexed_materials &&
         (slot_count < 2 ||
          !buffer->hasDataType(LLVertexBuffer::TYPE_TEXTURE_INDEX))) ||
        (!indexed_materials && params.mGLTFMaterial.isNull()))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    const std::size_t prior_count = capture.batches.size();
    captureMetalWorldGBufferBatch(params, false);
    if (!capture.complete || capture.batches.size() == prior_count)
    {
        return;
    }

    ALMetalWorldSimpleBatch& batch = capture.batches.back();
    batch.tangent_offset = buffer->getOffset(LLVertexBuffer::TYPE_TANGENT);
    batch.pbr_glow = capture.pbr_glow;
    if (capture.pbr_glow)
    {
        batch.emissive_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_EMISSIVE);
    }
    batch.pbr_slot_count = static_cast<U32>(slot_count);
    batch.texture_count = static_cast<U32>(slot_count);
    batch.double_sided = false;
    if (indexed_materials)
    {
        std::memset(batch.texture_matrix, 0,
                    sizeof(batch.texture_matrix));
        for (U32 diagonal = 0; diagonal < 4; ++diagonal)
        {
            batch.texture_matrix[diagonal * 4 + diagonal] = 1.f;
        }
    }

    for (std::size_t slot_index = 0;
         slot_index < slot_count; ++slot_index)
    {
        LLFetchedGLTFMaterial* material = indexed_materials
            ? params.mGLTFMaterialList[slot_index].get()
            : params.mGLTFMaterial.get();
        ALMetalWorldPBRSlot& destination = batch.pbrSlots()[slot_index];

        LLViewerTexture* media_texture = !indexed_materials
            ? params.mTexture.get() : nullptr;
        LLViewerTexture* base_texture = media_texture;
        LLViewerTexture* normal_texture = nullptr;
        LLViewerTexture* orm_texture = nullptr;
        LLViewerTexture* emissive_texture = media_texture;

        if (material)
        {
            const bool masked = material->mAlphaMode ==
                LLGLTFMaterial::ALPHA_MODE_MASK;
            // The original pbrglowF/pbrglowIndexedF shaders deliberately
            // accept both opaque and MASK materials from PASS_GLTF_GLOW and
            // apply each material's own cutoff.  Only the G-buffer sweeps are
            // partitioned into opaque versus alpha-mask passes.
            if (!capture.pbr_glow && masked != capture.alpha_mask)
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
            if (!base_texture)
            {
                base_texture = material->mBaseColorTexture.notNull()
                    ? material->mBaseColorTexture.get()
                    : LLViewerFetchedTexture::sWhiteImagep.get();
            }
            normal_texture =
                material->mNormalTexture.notNull() &&
                material->mNormalTexture->getDiscardLevel() <= 4
                    ? material->mNormalTexture.get()
                    : LLViewerFetchedTexture::sFlatNormalImagep.get();
            orm_texture = material->mMetallicRoughnessTexture.notNull()
                ? material->mMetallicRoughnessTexture.get()
                : LLViewerFetchedTexture::sWhiteImagep.get();
            if (!emissive_texture)
            {
                emissive_texture = material->mEmissiveTexture.notNull()
                    ? material->mEmissiveTexture.get()
                    : LLViewerFetchedTexture::sWhiteImagep.get();
            }
            for (U32 texture = 0;
                 texture < LLGLTFMaterial::GLTF_TEXTURE_INFO_COUNT;
                 ++texture)
            {
                LLGLTFMaterial::TextureTransform::Pack packed;
                material->mTextureTransform[texture].getPacked(packed);
                std::memcpy(destination.texture_transform[texture],
                            packed, sizeof(packed));
            }
            std::memcpy(destination.emissive_color,
                        material->mEmissiveColor.mV,
                        sizeof(material->mEmissiveColor.mV));
            std::memcpy(destination.base_color_factor,
                        material->mBaseColor.mV,
                        sizeof(destination.base_color_factor));
            destination.base_color_factor[3] =
                material->getStreamedBaseAlpha();
            destination.roughness_factor = material->mRoughnessFactor;
            destination.metallic_factor = material->mMetallicFactor;
            destination.alpha_cutoff = masked
                ? material->mAlphaCutoff : -1.f;
            batch.double_sided = batch.double_sided ||
                                 material->mDoubleSided;
        }
        else
        {
            base_texture = LLViewerFetchedTexture::sWhiteImagep.get();
            normal_texture = LLViewerFetchedTexture::sFlatNormalImagep.get();
            orm_texture = LLViewerFetchedTexture::sWhiteImagep.get();
            emissive_texture = LLViewerFetchedTexture::sWhiteImagep.get();
            destination.alpha_cutoff = -1.f;
        }

        const auto metal_texture = [](LLViewerTexture* texture)
            -> ALMetalTexture*
        {
            LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
            ALMetalTexture* native = image
                ? image->getMetalTexture() : nullptr;
            if (!native)
            {
                // LLFetchedGLTFMaterial::bind and the original OpenGL
                // ALTextureSlot path substitute the viewer default whenever a
                // streamed material map is not GPU-ready.  Preserve that
                // draw-local contract here instead of making one pending map
                // discard the complete native world transaction.
                LLViewerFetchedTexture* fallback =
                    LLViewerFetchedTexture::sDefaultImagep.get();
                LLImageGL* fallback_image = fallback
                    ? fallback->getGLTexture() : nullptr;
                native = fallback_image
                    ? fallback_image->getMetalTexture() : nullptr;
            }
            return native;
        };
        batch.diffuse_textures[slot_index] = metal_texture(base_texture);
        destination.normal_texture = metal_texture(normal_texture);
        destination.orm_texture = metal_texture(orm_texture);
        destination.emissive_texture = metal_texture(emissive_texture);
        if (!batch.diffuse_textures[slot_index] ||
            !destination.normal_texture || !destination.orm_texture ||
            !destination.emissive_texture)
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
    }
}

void LLPipeline::captureMetalImpostorPBRAlphaBatch(
    const LLDrawInfo& params, bool particle_or_hud_particle,
    bool depth_only)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool world_pre_water = capture.world_post_deferred_active &&
        capture.world_pre_water_alpha_active;
    const bool world_post_water = capture.world_post_deferred_active &&
        capture.world_post_water_alpha_active;
    const bool world_alpha = world_pre_water || world_post_water;
    if (!capture.impostor_alpha_active && !world_alpha)
    {
        return;
    }
    if (depth_only && !world_post_water)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    if (params.mGLTFMaterial.isNull() ||
        params.mGLTFMaterial->mAlphaMode !=
            LLGLTFMaterial::ALPHA_MODE_BLEND ||
        (!world_alpha &&
         (particle_or_hud_particle ||
          params.mBlendFuncSrc != LLRender::BF_SOURCE_ALPHA ||
          params.mBlendFuncDst != LLRender::BF_ONE_MINUS_SOURCE_ALPHA)))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    bool uses_shadows = false;
    if (world_alpha)
    {
        uses_shadows = metalWorldAlphaUsesDirectionalShadows(*this);
        if (uses_shadows && !fillMetalImpostorDirectionalShadows())
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        uses_shadows = uses_shadows &&
            capture.impostor_directional_shadows.depth_texture != nullptr;
        capture.world_alpha_uses_shadows =
            capture.world_alpha_uses_shadows || uses_shadows;
        if (!capture.world_alpha_lighting_valid)
        {
            ALMetalWorldLegacyAlphaLighting lighting;
            if (!fillMetalWorldAlphaLighting(lighting))
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
            capture.world_alpha_lighting = lighting;
            capture.world_alpha_lighting_valid = true;
        }
    }

    const std::size_t first_batch = capture.batches.size();
    capture.rigged = params.mAvatar != nullptr;
    capture.alpha_mask = false;
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
    capture.pbr = true;
    capture.terrain = false;
    capture.avatar = false;
    capture.impostor = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
    capture.pass_active = true;
    captureMetalWorldPBRBatch(params, false);
    capture.pass_active = false;
    capture.pbr = false;
    if (capture.complete && world_alpha &&
        capture.batches.size() == first_batch + 1)
    {
        ALMetalWorldSimpleBatch& batch = capture.batches.back();
        batch.pre_water_alpha = world_pre_water;
        batch.post_water_alpha = world_post_water;
        batch.pre_water_pbr = true;
        batch.pre_water_shadows = uses_shadows;
        if (!fillMetalWorldPreWaterAlphaDraw(
                batch, params, particle_or_hud_particle,
                depth_only, false))
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
    }
}

void LLPipeline::captureMetalImpostorFlatAlphaBatch(
    const LLDrawInfo& params, bool particle_or_hud_particle,
    bool depth_only)
{
    if (!mMetalWorldSimpleCapture)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool world_pre_water = capture.world_post_deferred_active &&
        capture.world_pre_water_alpha_active;
    const bool world_post_water = capture.world_post_deferred_active &&
        capture.world_post_water_alpha_active;
    const bool world_alpha = world_pre_water || world_post_water;
    if (!capture.impostor_alpha_active && !world_alpha)
    {
        return;
    }
    if (depth_only && !world_post_water)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    // The two legacy non-material impostor programs converge on the same
    // contract: decoded diffuse times linearised streamed tint. Main-world
    // capture also retains particle clamp/cull state and custom RGB blend
    // factors; the avatar-impostor bake keeps its narrower source-over set.
    if (params.mGLTFMaterial.notNull() || params.mMaterial ||
        (!world_alpha &&
         (particle_or_hud_particle ||
          params.mBlendFuncSrc != LLRender::BF_SOURCE_ALPHA ||
          params.mBlendFuncDst != LLRender::BF_ONE_MINUS_SOURCE_ALPHA)))
    {
        if (world_alpha)
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
        }
        return;
    }

    bool world_simple_shadows = false;
    if (world_alpha && !depth_only && !params.mFullbright)
    {
        if (!capture.world_alpha_lighting_valid)
        {
            ALMetalWorldLegacyAlphaLighting lighting;
            if (!fillMetalWorldAlphaLighting(lighting))
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
            capture.world_alpha_lighting = lighting;
            capture.world_alpha_lighting_valid = true;
        }
        world_simple_shadows =
            metalWorldAlphaUsesDirectionalShadows(*this);
        if (world_simple_shadows)
        {
            if (!fillMetalImpostorDirectionalShadows())
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
            world_simple_shadows =
                capture.impostor_directional_shadows.depth_texture !=
                nullptr;
        }
        capture.world_alpha_uses_shadows =
            capture.world_alpha_uses_shadows || world_simple_shadows;
    }

    const std::size_t first_batch = capture.batches.size();
    capture.rigged = params.mAvatar != nullptr;
    capture.alpha_mask = false;
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
    capture.pbr = false;
    capture.terrain = false;
    capture.avatar = false;
    capture.impostor = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
    capture.pass_active = true;
    captureMetalWorldGBufferBatch(params, true);
    capture.pass_active = false;
    if (world_alpha && capture.complete &&
        capture.batches.size() == first_batch + 1)
    {
        ALMetalWorldSimpleBatch& batch = capture.batches.back();
        batch.pre_water_alpha = world_pre_water;
        batch.post_water_alpha = world_post_water;
        // GL's DoF replay aliases both flat families to the fullbright
        // alpha-mask shader. It needs only texture coverage and the water
        // plane, never the simple-lighting resources.
        batch.pre_water_fullbright = depth_only || params.mFullbright;
        batch.pre_water_simple = !depth_only && !params.mFullbright;
        batch.pre_water_shadows = world_simple_shadows;
        batch.impostor_fullbright = false;
        if (!fillMetalWorldPreWaterAlphaDraw(
                batch, params, particle_or_hud_particle,
                depth_only, true))
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
    }
}

bool LLPipeline::fillMetalImpostorScreenSpaceReflections()
{
    if (!mMetalWorldSimpleCapture)
    {
        return false;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    ALMetalWorldScreenSpaceReflections& reflections =
        capture.impostor_screen_space_reflections;
    if (!reflections.scene_color || !reflections.scene_depth ||
        capture.width == 0 || capture.height == 0 ||
        reflections.scene_color->descriptor().width !=
            capture.width ||
        reflections.scene_color->descriptor().height !=
            capture.height ||
        reflections.scene_color->descriptor().format !=
            (hdrEnabled() ? ALMetalPixelFormat::rg11b10_float
                          : ALMetalPixelFormat::rgba8_unorm) ||
        reflections.scene_depth->descriptor().width != capture.width ||
        reflections.scene_depth->descriptor().height != capture.height ||
        reflections.scene_depth->descriptor().format !=
            ALMetalPixelFormat::r32_float)
    {
        return false;
    }

    ALMetalWorldScreenSpaceReflectionConstants constants;
    const LLCamera& camera = LLViewerCamera::getCurrent();
    LLMatrix4a inverse_projection;
    inverse_projection.setInverse(camera.getProjection());
    std::memcpy(constants.projection,
                camera.getProjection().getF32ptr(),
                sizeof(constants.projection));
    std::memcpy(constants.inverse_projection,
                inverse_projection.getF32ptr(),
                sizeof(constants.inverse_projection));
    std::memcpy(constants.inverse_modelview_delta,
                LLViewerCamera::getInstance()
                    ->getInverseDeltaModelview().getF32ptr(),
                sizeof(constants.inverse_modelview_delta));
    constants.screen[0] = static_cast<F32>(capture.width);
    constants.screen[1] = static_cast<F32>(capture.height);
    constants.screen[2] = static_cast<F32>(capture.height);
    constants.trace[0] = static_cast<F32>(
        std::max(RenderScreenSpaceReflectionIterations, 0));
    constants.trace[1] = RenderScreenSpaceReflectionRayStep;
    constants.trace[2] = RenderScreenSpaceReflectionDistanceBias;
    constants.trace[3] = RenderScreenSpaceReflectionDepthRejectBias;
    constants.sampling[0] = static_cast<F32>(std::clamp(
        RenderScreenSpaceReflectionGlossySamples, 1, 128));
    constants.sampling[1] =
        RenderScreenSpaceReflectionAdaptiveStepMultiplier;
    constants.config[0] = capture.reverse_z ? 1u : 0u;
    constants.config[1] = 1;
    reflections.constants = constants;
    return constants.screen[0] > 0.f && constants.screen[1] > 0.f;
}

bool LLPipeline::fillMetalImpostorHeroProbe()
{
    if (!mMetalWorldSimpleCapture || !mMetalWorldSimpleCapture->device)
    {
        return false;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    LLHeroProbeManager& manager = mHeroProbeManager;
    if (!isMetalHeroProbeActive() ||
        manager.mHeroData.heroShape < 0 ||
        manager.mHeroData.heroShape > 1 ||
        !manager.mMetalRadianceReady ||
        manager.mMetalRadianceGeneration == 0 ||
        !std::isfinite(manager.mHeroData.heroMaxLod) ||
        manager.mHeroData.heroMaxLod < 0.f)
    {
        return false;
    }

    const U32 hero_max_lod = static_cast<U32>(
        std::lround(manager.mHeroData.heroMaxLod));
    const U32 radiance_mips = static_cast<U32>(
        std::ceil(0.25f * manager.mHeroData.heroMaxLod)) + 1;
    const ALMetalPixelFormat metal_format = manager.mHDR
        ? ALMetalPixelFormat::rg11b10_float
        : ALMetalPixelFormat::rgba8_unorm;
    const MetalWorldSimpleCapture* native_capture =
        !mMetalHeroWorldCaptureActive &&
        !mMetalReflectionWorldCaptureActive
            ? mMetalProbeWorldSimpleCapture.get() : nullptr;
    const ALMetalTextureDescriptor* native_descriptor =
        native_capture && native_capture->hero_probe_radiance_cube
            ? &native_capture->hero_probe_radiance_cube->descriptor()
            : nullptr;
    const bool native_radiance = native_capture && native_descriptor &&
        native_capture->device == capture.device &&
        manager.mNearestHero.notNull() &&
        !manager.mNearestHero->isDead() &&
        native_capture->hero_probe_owner_id ==
            manager.mNearestHero->getID() &&
        native_capture->hero_probe_owner_epoch ==
            manager.mMetalRadianceEpoch &&
        native_capture->hero_probe_native_generation ==
            manager.mMetalRadianceGeneration &&
        native_descriptor->type == ALMetalTextureType::texture_cube &&
        native_descriptor->format == metal_format &&
        native_descriptor->width != 0 &&
        native_descriptor->height == native_descriptor->width &&
        native_descriptor->mipmap_level_count == radiance_mips;
    if (!native_radiance)
    {
        return false;
    }

    static_assert(sizeof(LLMatrix4) == sizeof(F32) * 16);
    ALMetalWorldHeroProbeConstants constants;
    std::memcpy(constants.hero_box, manager.mHeroData.heroBox.mMatrix,
                sizeof(constants.hero_box));
    std::memcpy(constants.hero_sphere,
                manager.mHeroData.heroSphere.mV,
                sizeof(constants.hero_sphere));

    const LLMatrix4a& modelview =
        LLViewerCamera::getCurrent().getModelview();
    LLMatrix4a normal_matrix;
    normal_matrix.setNormalMatrix(modelview);
    LLVector4a mirror_normal(
        manager.mMirrorNormal.mV[0], manager.mMirrorNormal.mV[1],
        manager.mMirrorNormal.mV[2], 0.f);
    LLVector4a mirror_position(
        manager.mMirrorPosition.mV[0], manager.mMirrorPosition.mV[1],
        manager.mMirrorPosition.mV[2], 1.f);
    LLVector4a eye_normal;
    LLVector4a eye_position;
    normal_matrix.rotate(mirror_normal, eye_normal);
    eye_normal.normalize3();
    modelview.affineTransform(mirror_position, eye_position);
    constants.clip_plane[0] = eye_normal[0];
    constants.clip_plane[1] = eye_normal[1];
    constants.clip_plane[2] = eye_normal[2];
    constants.clip_plane[3] =
        -eye_position.dot3(eye_normal).getF32();
    constants.config[0] =
        static_cast<U32>(manager.mHeroData.heroShape);
    constants.config[1] = 1;
    constants.config[2] = hero_max_lod;

    capture.impostor_hero_probe.radiance_texture =
        native_capture->hero_probe_radiance_cube.get();
    capture.impostor_hero_probe.constants = constants;
    return true;
}

bool LLPipeline::isMetalHeroProbeActive() const
{
    return mResourceInputs.mMirrors &&
        mResourcePlan.heroProbes().has_value() &&
        mHeroProbeManager.mHeroData.heroProbeCount == 1;
}

void LLPipeline::retireMetalHeroProbeResources()
{
    // A settings change is reconciled at the next frame boundary, after any
    // bounded probe capture has ended. Recover defensively if that invariant
    // is ever broken so the ordinary-world owner is restored before its hero
    // fields are cleared.
    if (mMetalHeroWorldCaptureActive)
    {
        if (mMetalWorldSimpleCapture &&
            mMetalWorldSimpleCapture->renderer &&
            mMetalWorldSimpleCapture->renderer->commandBatchActive())
        {
            mMetalWorldSimpleCapture->renderer->cancelCommandBatch();
        }
        if (mMetalWorldSimpleCapture)
        {
            mMetalWorldSimpleCapture->hero_probe_face_capture = false;
            mMetalWorldSimpleCapture->hero_forward_capture_reserved = false;
        }
        std::swap(mMetalWorldSimpleCapture, mMetalProbeWorldSimpleCapture);
        mMetalHeroWorldCaptureActive = false;
        mRT = &mMainRT;
        LL_WARNS("Metal")
            << "Mirror resources were retired during an active native hero "
               "capture; the incomplete capture was cancelled"
            << LL_ENDL;
    }

    bool retired = false;
    const auto clear_hero = [&retired](
        std::unique_ptr<MetalWorldSimpleCapture>& owner)
    {
        if (!owner)
        {
            return;
        }
        retired = retired || owner->hero_probe_source_cube ||
            owner->hero_probe_radiance_cube ||
            !owner->hero_probe_owner_id.isNull() ||
            owner->hero_probe_native_generation != 0 ||
            owner->impostor_hero_probe.radiance_texture != nullptr;
        owner->impostor_hero_probe = {};
        owner->hero_probe_source_cube.reset();
        owner->hero_probe_radiance_cube.reset();
        owner->hero_probe_owner_id.setNull();
        owner->hero_probe_owner_epoch = 0;
        owner->hero_probe_valid_faces = 0;
        owner->hero_probe_face = 0;
        owner->hero_probe_max_lod = 0;
        owner->hero_probe_native_generation = 0;
        owner->hero_probe_face_capture = false;
        owner->hero_forward_capture_reserved = false;
    };
    clear_hero(mMetalWorldSimpleCapture);
    clear_hero(mMetalProbeWorldSimpleCapture);

    if (retired)
    {
        LL_INFOS("Metal")
            << "Retired native mirror source, radiance, and visible-world "
               "binding after the hero resource plan was disabled"
            << LL_ENDL;
    }
}

bool LLPipeline::fillMetalImpostorDirectionalShadows()
{
    if (!mMetalWorldSimpleCapture || !mMetalWorldSimpleCapture->device)
    {
        return false;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const U32 unbuilt = unbuiltShadowMaps() & 0xfu;
    if (capture.impostor_directional_shadow_frame == gFrameCount &&
        capture.impostor_directional_shadows.depth_texture)
    {
        const ALMetalTextureDescriptor& descriptor =
            capture.impostor_directional_shadows.depth_texture->descriptor();
        ALMetalWorldDirectionalShadowConstants& constants =
            capture.impostor_directional_shadows.constants;
        std::memcpy(constants.shadow_matrix,
                    mNativeShadowData.shadow_matrix,
                    sizeof(constants.shadow_matrix));
        std::memcpy(constants.shadow_clip, mNativeShadowData.shadow_clip,
                    sizeof(constants.shadow_clip));
        // The original OpenGL pack publishes shadow_res from the actual
        // mRT->shadow texture it binds, not from the resource plan.  Hero and
        // ordinary probe faces share this retained native capture owner and
        // can alternate sizes within one viewer frame, so the sampled
        // texture is likewise the only authoritative resolution here.
        constants.resolution[0] = static_cast<F32>(descriptor.width);
        constants.resolution[1] = static_cast<F32>(descriptor.height);
        constants.resolution[2] = static_cast<F32>(capture.width);
        constants.resolution[3] = static_cast<F32>(capture.height);
        constants.parameters[0] = mNativeShadowData.shadow_bias;
        constants.parameters[1] = mNativeShadowData.shadow_offset;
        constants.parameters[2] = mNativeShadowData.shadow_pcss_scale;
        constants.parameters[3] = static_cast<F32>(capture.height);
        constants.config[0] = sunCascades();
        constants.config[1] = unbuilt;
        constants.config[2] = capture.reverse_z ? 1u : 0u;
        constants.config[3] = static_cast<U32>(std::clamp(
            shaderInputs().mGlobal.mShadowFilterQuality, 0, 3)) |
            (gCubeSnapshot
                 ? ALMetalWorldDirectionalShadowConstants::probe_single_tap
                 : 0u);
        return true;
    }

    // No cascade exists. Both renderers return fully lit from the unbuilt
    // mask without sampling, which is also the native null-pack fallback.
    if (unbuilt == 0xfu)
    {
        capture.impostor_directional_shadows = {};
        capture.impostor_directional_shadow_frame = gFrameCount;
        return true;
    }

    const auto publish = [&](const ALMetalTexture* texture)
    {
        const ALMetalTextureDescriptor& descriptor = texture->descriptor();
        ALMetalWorldDirectionalShadowConstants constants;
        std::memcpy(constants.shadow_matrix,
                    mNativeShadowData.shadow_matrix,
                    sizeof(constants.shadow_matrix));
        std::memcpy(constants.shadow_clip, mNativeShadowData.shadow_clip,
                    sizeof(constants.shadow_clip));
        constants.resolution[0] = static_cast<F32>(descriptor.width);
        constants.resolution[1] = static_cast<F32>(descriptor.height);
        constants.resolution[2] = static_cast<F32>(capture.width);
        constants.resolution[3] = static_cast<F32>(capture.height);
        constants.parameters[0] = mNativeShadowData.shadow_bias;
        constants.parameters[1] = mNativeShadowData.shadow_offset;
        constants.parameters[2] = mNativeShadowData.shadow_pcss_scale;
        constants.parameters[3] = static_cast<F32>(capture.height);
        constants.config[0] = sunCascades();
        constants.config[1] = unbuilt;
        constants.config[2] = capture.reverse_z ? 1u : 0u;
        constants.config[3] = static_cast<U32>(std::clamp(
            shaderInputs().mGlobal.mShadowFilterQuality, 0, 3)) |
            (gCubeSnapshot
                 ? ALMetalWorldDirectionalShadowConstants::probe_single_tap
                 : 0u);

        capture.impostor_directional_shadows.depth_texture = texture;
        capture.impostor_directional_shadows.constants = constants;
        capture.impostor_directional_shadow_frame = gFrameCount;
        return true;
    };

    const MetalWorldSimpleCapture& source = capture.profile_source
        ? *capture.profile_source : capture;
    const ALMetalTextureDescriptor* direct =
        source.direct_directional_shadow_texture
            ? &source.direct_directional_shadow_texture->descriptor()
            : nullptr;
    bool direct_complete = direct &&
        direct->type == ALMetalTextureType::texture_2d_array &&
        direct->format == ALMetalPixelFormat::r32_float &&
        direct->width != 0 && direct->height != 0 &&
        direct->array_length == 4;
    for (U32 cascade = 0; direct_complete && cascade < 4; ++cascade)
    {
        direct_complete = (unbuilt & (1u << cascade)) != 0 ||
            source.direct_directional_shadow_valid[cascade];
    }
    return direct_complete &&
        publish(source.direct_directional_shadow_texture.get());
}

void LLPipeline::countMetalShadowBatches(
    std::size_t& batches, bool& complete)
{
    const auto counted_batches = [&](U32 type)
    {
        std::size_t count = 0;
        auto* begin = beginRenderMap(type);
        auto* end = endRenderMap(type);
        for (auto* at = begin; at != end; )
        {
            LLDrawInfo* info = *at;
            LLCullResult::increment_iterator(at, end);
            if (info && info->mCount)
            {
                ++count;
            }
        }
        return count;
    };

    batches = 0;
    complete = true;
    for (U32 type : SHADOW_GEOMETRY_PASSES)
    {
        batches += counted_batches(type);
        batches += counted_batches(type + 1);
    }
    batches += counted_batches(LLRenderPass::PASS_GLTF_PBR);
    batches += counted_batches(LLRenderPass::PASS_GLTF_PBR_RIGGED);
    for (U32 type : SHADOW_MASKED_PASSES)
    {
        batches += counted_batches(type);
        batches += counted_batches(type + 1);
    }
    batches += counted_batches(LLRenderPass::PASS_ALPHA);
    batches += counted_batches(LLRenderPass::PASS_GRASS);

    for (LLDrawPool* pool : mPools)
    {
        if (!complete)
        {
            break;
        }
        if (!hasRenderType(pool->getType()) ||
            !pool->hasShadowCasters())
        {
            continue;
        }
        ALSpotShadowCache::Casters pool_casters;
        pool->addShadowCasters(pool_casters);
        if (pool->getType() == LLDrawPool::POOL_TREE)
        {
            // The tree pool contributes one caster record for every indexed
            // face draw. The adjacent draw hook captures the same loop.
            batches += pool_casters.count();
        }
        else if (pool->getType() == LLDrawPool::POOL_TERRAIN &&
                 !pool_casters.changing())
        {
            // Terrain starts with one region-wide dependency, followed by
            // one record per patch draw. Only the patch records are batches.
            batches += pool_casters.count() == 0
                ? 0 : pool_casters.count() - 1;
        }
        else if ((pool->getType() == LLDrawPool::POOL_AVATAR ||
                  pool->getType() == LLDrawPool::POOL_CONTROL_AV) &&
                 pool_casters.count() == 0)
        {
            // Avatar visibility, bake splitting and detail filtering are
            // resolved by the direct avatar capture. Its mesh hook increments
            // the expected total for each native batch it emits.
        }
        else
        {
            complete = pool_casters.count() == 0 &&
                       !pool_casters.changing();
        }
    }
}

void LLPipeline::captureMetalShadowScene()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active ||
        !mMetalWorldSimpleCapture->spot_shadow_explicit_matrices)
    {
        return;
    }

    const bool saved_shadow_render = sShadowRender;
    sShadowRender = true;
    mMetalWorldSimpleCapture->spot_shadow_source_merge_active = true;
    const auto for_each_batch = [this](U32 type, const auto& capture)
    {
        // A render family is an ordering/state boundary even when two
        // neighbouring sources happen to share native geometry and matrices.
        mMetalWorldSimpleCapture->spot_shadow_admission.barrier();
        auto* at = beginRenderMap(type);
        auto* end = endRenderMap(type);
        while (at != end)
        {
            LLDrawInfo* info = *at;
            LLCullResult::increment_iterator(at, end);
            if (info && info->mCount)
            {
                capture(*info);
            }
        }
    };
    const auto capture_opaque = [this](const LLDrawInfo& info)
    {
        bool double_sided = info.mGLTFMaterial.notNull() &&
            info.mGLTFMaterial->mDoubleSided;
        for (const LLPointer<LLFetchedGLTFMaterial>& material :
             info.mGLTFMaterialList)
        {
            double_sided = double_sided ||
                (material.notNull() && material->mDoubleSided);
        }
        captureMetalSpotShadowOpaqueBatch(info, double_sided);
    };

    setMetalSpotShadowCoverage(ALMetalWorldSpotShadowCoverage::opaque);
    for (U32 type : SHADOW_GEOMETRY_PASSES)
    {
        for_each_batch(type, capture_opaque);
        for_each_batch(type + 1, capture_opaque);
    }
    for_each_batch(LLRenderPass::PASS_GLTF_PBR, capture_opaque);
    for_each_batch(LLRenderPass::PASS_GLTF_PBR_RIGGED, capture_opaque);

    const auto capture_legacy = [this](const LLDrawInfo& info)
    {
        captureMetalSpotShadowTexturedBatch(
            info, true, info.mMaterialSlotList.size() > 1);
    };
    setMetalSpotShadowCoverage(
        ALMetalWorldSpotShadowCoverage::legacy_mask);
    for_each_batch(LLRenderPass::PASS_ALPHA_MASK, capture_legacy);
    for_each_batch(LLRenderPass::PASS_ALPHA_MASK_RIGGED, capture_legacy);

    setMetalSpotShadowCoverage(
        ALMetalWorldSpotShadowCoverage::legacy_fullbright_mask);
    for_each_batch(
        LLRenderPass::PASS_FULLBRIGHT_ALPHA_MASK, capture_legacy);
    for_each_batch(
        LLRenderPass::PASS_FULLBRIGHT_ALPHA_MASK_RIGGED, capture_legacy);

    setMetalSpotShadowCoverage(
        ALMetalWorldSpotShadowCoverage::legacy_blend);
    for_each_batch(LLRenderPass::PASS_ALPHA,
        [this](const LLDrawInfo& info)
        {
            if (info.mGLTFMaterial.notNull() ||
                !info.mGLTFMaterialList.empty())
            {
                captureMetalSpotShadowPBRBatch(
                    info, info.mGLTFMaterialList.size() > 1);
            }
            else
            {
                captureMetalSpotShadowTexturedBatch(info, true);
            }
        });

    setMetalSpotShadowCoverage(
        ALMetalWorldSpotShadowCoverage::texture_mask);
    for_each_batch(LLRenderPass::PASS_GRASS, capture_legacy);
    for (U32 type : {
             LLRenderPass::PASS_NORMSPEC_MASK,
             LLRenderPass::PASS_MATERIAL_ALPHA_MASK,
             LLRenderPass::PASS_SPECMAP_MASK,
             LLRenderPass::PASS_NORMMAP_MASK })
    {
        for_each_batch(type, capture_legacy);
        for_each_batch(type + 1, capture_legacy);
    }

    setMetalSpotShadowCoverage(
        ALMetalWorldSpotShadowCoverage::pbr_mask);
    const auto capture_pbr = [this](const LLDrawInfo& info)
    {
        captureMetalSpotShadowPBRBatch(
            info, info.mGLTFMaterialList.size() > 1);
    };
    for_each_batch(LLRenderPass::PASS_GLTF_PBR_ALPHA_MASK, capture_pbr);
    for_each_batch(
        LLRenderPass::PASS_GLTF_PBR_ALPHA_MASK_RIGGED, capture_pbr);

    setMetalSpotShadowCoverage(ALMetalWorldSpotShadowCoverage::opaque);
    for (LLDrawPool* pool : mPools)
    {
        if (!pool || !hasRenderType(pool->getType()) ||
            !pool->hasShadowCasters())
        {
            continue;
        }
        switch (pool->getType())
        {
            case LLDrawPool::POOL_TREE:
                static_cast<LLDrawPoolTree*>(pool)
                    ->captureMetalDirectionalShadow();
                break;
            case LLDrawPool::POOL_TERRAIN:
                static_cast<LLDrawPoolTerrain*>(pool)
                    ->captureMetalDirectionalShadow();
                break;
            case LLDrawPool::POOL_AVATAR:
            case LLDrawPool::POOL_CONTROL_AV:
                static_cast<LLDrawPoolAvatar*>(pool)
                    ->captureMetalDirectionalShadow();
                break;
            default:
                break;
        }
    }
    mMetalWorldSimpleCapture->spot_shadow_source_merge_active = false;
    sShadowRender = saved_shadow_render;
}

void LLPipeline::beginMetalSpotShadowCapture(
    U32 map, U32 width, U32 height, std::size_t expected_batches,
    bool complete, const LLMatrix4a* view,
    const LLMatrix4a* projection)
{
    if (!mMetalWorldSimpleCapture || map >= 2 || width == 0 || height == 0)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device || !capture.renderer ||
        capture.spot_shadow_capture_active)
    {
        return;
    }
    capture.direct_projector_shadow_valid[map] = false;
    if (!capture.beginFrameData(
            mMetalProbeWorldSimpleCapture.get(), gFrameCount))
    {
        return;
    }
    capture.spot_shadow_batches.clear();
    capture.spot_shadow_avatar_palettes.clear();
    capture.spot_shadow_map = map;
    capture.spot_shadow_width = width;
    capture.spot_shadow_height = height;
    capture.spot_shadow_expected_batches = expected_batches;
    capture.spot_shadow_admission.reset();
    capture.spot_shadow_explicit_matrices = view && projection;
    if (capture.spot_shadow_explicit_matrices)
    {
        capture.spot_shadow_view = *view;
        capture.spot_shadow_projection = *projection;
    }
    capture.spot_shadow_coverage =
        ALMetalWorldSpotShadowCoverage::opaque;
    capture.spot_shadow_capture_complete = complete;
    capture.spot_shadow_first_incomplete_source_line = 0;
    capture.spot_shadow_capture_directional = false;
    capture.spot_shadow_avatar_pass_active = false;
    capture.spot_shadow_avatar_cloth = false;
    capture.reverse_z = LLRender::sReverseZ;
    capture.spot_shadow_capture_active = true;
    capture.spot_shadow_source_merge_active = false;
}

void LLPipeline::beginMetalDirectionalShadowCapture(
    U32 map, U32 width, U32 height, std::size_t expected_batches,
    bool complete, const LLMatrix4a* view,
    const LLMatrix4a* projection)
{
    if (!mMetalWorldSimpleCapture || map >= 4 || width == 0 || height == 0)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device || !capture.renderer ||
        capture.spot_shadow_capture_active)
    {
        return;
    }
    capture.direct_directional_shadow_valid[map] = false;
    if (!capture.beginFrameData(
            mMetalProbeWorldSimpleCapture.get(), gFrameCount))
    {
        return;
    }
    capture.spot_shadow_batches.clear();
    capture.spot_shadow_avatar_palettes.clear();
    capture.spot_shadow_map = map;
    capture.spot_shadow_width = width;
    capture.spot_shadow_height = height;
    capture.spot_shadow_expected_batches = expected_batches;
    capture.spot_shadow_admission.reset();
    capture.spot_shadow_explicit_matrices = view && projection;
    if (capture.spot_shadow_explicit_matrices)
    {
        capture.spot_shadow_view = *view;
        capture.spot_shadow_projection = *projection;
    }
    capture.spot_shadow_coverage =
        ALMetalWorldSpotShadowCoverage::opaque;
    capture.spot_shadow_capture_complete = complete;
    capture.spot_shadow_first_incomplete_source_line = 0;
    capture.spot_shadow_capture_directional = true;
    capture.spot_shadow_avatar_pass_active = false;
    capture.spot_shadow_avatar_cloth = false;
    capture.reverse_z = LLRender::sReverseZ;
    capture.spot_shadow_capture_active = true;
    capture.spot_shadow_source_merge_active = false;
}

bool LLPipeline::getMetalSpotShadowModelviewProjection(
    const LLMatrix4a* model_matrix,
    LLMatrix4a& modelview_projection) const
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active)
    {
        return false;
    }

    const MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.spot_shadow_explicit_matrices)
    {
        LLMatrix4a modelview = capture.spot_shadow_view;
        if (model_matrix)
        {
            modelview.setMul(*model_matrix, capture.spot_shadow_view);
        }
        modelview_projection.setMul(
            modelview, capture.spot_shadow_projection);
    }
    else
    {
        modelview_projection.setMul(
            gGL.getModelviewMatrix(), gGL.getProjectionMatrix());
    }
    return true;
}

void LLPipeline::beginMetalSpotShadowAvatarPass(
    bool cloth, const F32* wind, const F32* sin_wave,
    const F32* gravity, const F32* cloth_depth)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.spot_shadow_avatar_pass_active ||
        (cloth && (!wind || !sin_wave || !gravity || !cloth_depth)))
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
        capture.spot_shadow_avatar_palettes.clear();
        return;
    }
    capture.spot_shadow_avatar_pass_active = true;
    capture.spot_shadow_avatar_cloth = cloth;
    if (cloth)
    {
        std::memcpy(capture.spot_shadow_avatar_wind, wind,
                    sizeof(capture.spot_shadow_avatar_wind));
        std::memcpy(capture.spot_shadow_avatar_sin_wave, sin_wave,
                    sizeof(capture.spot_shadow_avatar_sin_wave));
        std::memcpy(capture.spot_shadow_avatar_gravity, gravity,
                    sizeof(capture.spot_shadow_avatar_gravity));
        std::memcpy(capture.spot_shadow_avatar_cloth_depth, cloth_depth,
                    sizeof(capture.spot_shadow_avatar_cloth_depth));
    }
}

void LLPipeline::endMetalSpotShadowAvatarPass()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.spot_shadow_avatar_pass_active)
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
        capture.spot_shadow_avatar_palettes.clear();
        return;
    }
    capture.spot_shadow_avatar_pass_active = false;
    capture.spot_shadow_avatar_cloth = false;
}

void LLPipeline::setMetalSpotShadowCoverage(
    ALMetalWorldSpotShadowCoverage coverage)
{
    if (mMetalWorldSimpleCapture &&
        mMetalWorldSimpleCapture->spot_shadow_capture_active)
    {
        mMetalWorldSimpleCapture->spot_shadow_admission.barrier();
        mMetalWorldSimpleCapture->spot_shadow_coverage = coverage;
    }
}

void LLPipeline::captureMetalSpotShadowOpaqueBatch(
    const LLDrawInfo& params, bool double_sided)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_complete ||
        mMetalWorldSimpleCapture->spot_shadow_coverage !=
            ALMetalWorldSpotShadowCoverage::opaque ||
        !params.mCount)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    if (!buffer ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->getMetalVertexBuffer() || !buffer->getMetalIndexBuffer())
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
        return;
    }

    LLMatrix4a modelview_projection;
    getMetalSpotShadowModelviewProjection(
        params.mModelMatrix, modelview_projection);
    if (capture.spot_shadow_source_merge_active &&
        !params.mAvatar && !params.mSkinInfo)
    {
        ALMetalOpaqueShadowSource source;
        source.vertices = buffer->getMetalVertexBuffer();
        source.indices = buffer->getMetalIndexBuffer();
        source.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
        source.vertex_count = buffer->getNumVerts();
        source.index_offset = static_cast<std::size_t>(params.mOffset) * buffer->getIndexStride();
        source.index_count = params.mCount;
        source.index_type = buffer->getIndexStride() == 4
            ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
        source.modelview_projection = modelview_projection.getF32ptr();
        source.double_sided = double_sided;
        source.reverse_z = capture.reverse_z;
        if ((buffer->getIndexStride() != 2 && buffer->getIndexStride() != 4) ||
            !capture.spot_shadow_admission.appendOpaque(capture.spot_shadow_batches, source))
        {
            capture.spot_shadow_admission.invalidate();
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
        }
        return;
    }

    // Populate retained storage in place instead of copying every unused
    // material/terrain field for each cascade. Every failure after admission
    // clears the shadow transaction and returns immediately.
    auto* appended = capture.appendSeparateShadowBatch(__LINE__);
    if (!appended) return;
    auto& batch = *appended;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = static_cast<std::size_t>(params.mOffset) *
                         buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = params.mCount;
    batch.double_sided = double_sided;

    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));

    if (params.mAvatar || params.mSkinInfo)
    {
        if (!params.mAvatar || !params.mSkinInfo ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
        const LLVOAvatar::MatrixPaletteCache& palette =
            params.mAvatar->updateSkinInfoMatrixPalette(params.mSkinInfo);
        const U32 joint_count = static_cast<U32>(
            palette.mMatrixPalette.size());
        if (joint_count == 0 || palette.mGLMp.size() !=
                4 + static_cast<std::size_t>(joint_count) * 12)
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
        batch.weight_offset = buffer->getOffset(LLVertexBuffer::TYPE_WEIGHT4);
        batch.skin_palette = palette.mGLMp.data();
        batch.skin_palette_float_count = palette.mGLMp.size();
        batch.skin_joint_count = joint_count;
    }
}

void LLPipeline::captureMetalSpotShadowTexturedBatch(
    const LLDrawInfo& params, bool batch_textures,
    bool indexed_materials)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_complete ||
        mMetalWorldSimpleCapture->spot_shadow_coverage ==
            ALMetalWorldSpotShadowCoverage::opaque ||
        !params.mCount)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool indexed_textures = !indexed_materials && batch_textures &&
        params.mTextureList.size() > 1;
    const std::size_t texture_count = indexed_materials
        ? params.mMaterialSlotList.size()
        : indexed_textures ? params.mTextureList.size() : 1;
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    if (!buffer || texture_count == 0 ||
        texture_count > ALMetalWorldSpotShadowBatch::max_textures ||
        (indexed_materials && texture_count < 2) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_COLOR) ||
        ((indexed_materials || indexed_textures) &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_TEXTURE_INDEX)) ||
        !buffer->getMetalVertexBuffer() || !buffer->getMetalIndexBuffer())
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
        return;
    }

    auto* appended = capture.appendSeparateShadowBatch(__LINE__);
    if (!appended) return;
    auto& batch = *appended;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.texcoord_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_TEXCOORD0);
    batch.color_offset = buffer->getOffset(LLVertexBuffer::TYPE_COLOR);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = static_cast<std::size_t>(params.mOffset) *
                         buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = params.mCount;
    batch.texture_count = static_cast<U32>(texture_count);
    batch.coverage = capture.spot_shadow_coverage;

    LLMatrix4a modelview_projection;
    getMetalSpotShadowModelviewProjection(
        params.mModelMatrix, modelview_projection);
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    if (!indexed_materials && !indexed_textures &&
        params.mTextureMatrix &&
        (!gCubeSnapshot || mHeroProbeManager.isMirrorPass()))
    {
        std::memcpy(batch.texture_matrix, params.mTextureMatrix->mMatrix,
                    sizeof(batch.texture_matrix));
    }

    const auto metal_texture = [](LLViewerTexture* texture)
        -> ALMetalTexture*
    {
        LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
        ALMetalTexture* native = image ? image->getMetalTexture() : nullptr;
        if (!native)
        {
            // The original texture-slot bind substitutes the viewer default
            // while a streamed image is not GPU-ready. A transient upload
            // must not invalidate the complete shadow map.
            LLViewerFetchedTexture* fallback =
                LLViewerFetchedTexture::sDefaultImagep.get();
            LLImageGL* fallback_image = fallback
                ? fallback->getGLTexture() : nullptr;
            native = fallback_image
                ? fallback_image->getMetalTexture() : nullptr;
        }
        return native;
    };
    for (std::size_t slot = 0; slot < texture_count; ++slot)
    {
        LLViewerTexture* texture = nullptr;
        if (indexed_materials)
        {
            const LLDrawInfo::MaterialSlot& material =
                params.mMaterialSlotList[slot];
            texture = material.mDiffuse.get();
            batch.coverageData().alpha_cutoffs[slot] = material.mAlphaMaskCutoff;
        }
        else if (indexed_textures)
        {
            texture = params.mTextureList[slot].get();
            batch.coverageData().alpha_cutoffs[slot] = params.mAlphaMaskCutoff;
        }
        else
        {
            texture = params.mTexture.get();
            batch.coverageData().alpha_cutoffs[slot] =
                capture.spot_shadow_coverage ==
                    ALMetalWorldSpotShadowCoverage::legacy_blend
                ? ALPHA_BLEND_CUTOFF : params.mAlphaMaskCutoff;
        }
        if (!texture)
        {
            texture = LLViewerFetchedTexture::sWhiteImagep.get();
        }
        batch.coverageData().textures[slot] = metal_texture(texture);
        if (!batch.coverageData().textures[slot])
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
    }
    if (capture.spot_shadow_coverage ==
            ALMetalWorldSpotShadowCoverage::legacy_blend)
    {
        std::fill_n(batch.coverageData().alpha_cutoffs.begin(), texture_count,
                    ALPHA_BLEND_CUTOFF);
    }

    if (params.mAvatar || params.mSkinInfo)
    {
        if (!params.mAvatar || !params.mSkinInfo ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
        const LLVOAvatar::MatrixPaletteCache& palette =
            params.mAvatar->updateSkinInfoMatrixPalette(params.mSkinInfo);
        const U32 joint_count = static_cast<U32>(
            palette.mMatrixPalette.size());
        if (joint_count == 0 || palette.mGLMp.size() !=
                4 + static_cast<std::size_t>(joint_count) * 12)
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
        batch.weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT4);
        batch.skin_palette = palette.mGLMp.data();
        batch.skin_palette_float_count = palette.mGLMp.size();
        batch.skin_joint_count = joint_count;
    }
}

void LLPipeline::captureMetalSpotShadowPBRBatch(
    const LLDrawInfo& params, bool indexed_materials)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_complete ||
        mMetalWorldSimpleCapture->spot_shadow_coverage ==
            ALMetalWorldSpotShadowCoverage::opaque ||
        !params.mCount)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const ALMetalWorldSpotShadowCoverage coverage =
        capture.spot_shadow_coverage ==
                ALMetalWorldSpotShadowCoverage::legacy_blend
            ? ALMetalWorldSpotShadowCoverage::pbr_blend
            : ALMetalWorldSpotShadowCoverage::pbr_mask;
    const std::size_t texture_count = indexed_materials
        ? params.mGLTFMaterialList.size() : 1;
    LLVertexBuffer* buffer = params.mVertexBuffer.get();
    if (!buffer || texture_count == 0 ||
        texture_count > ALMetalWorldSpotShadowBatch::max_pbr_slots ||
        (indexed_materials && texture_count < 2) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_COLOR) ||
        (indexed_materials &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_TEXTURE_INDEX)) ||
        !buffer->getMetalVertexBuffer() || !buffer->getMetalIndexBuffer() ||
        (!indexed_materials && params.mGLTFMaterial.isNull()))
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
        return;
    }

    auto* appended = capture.appendSeparateShadowBatch(__LINE__);
    if (!appended) return;
    auto& batch = *appended;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.texcoord_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_TEXCOORD0);
    batch.color_offset = buffer->getOffset(LLVertexBuffer::TYPE_COLOR);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = static_cast<std::size_t>(params.mOffset) *
                         buffer->getIndexStride();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = params.mCount;
    batch.texture_count = static_cast<U32>(texture_count);
    batch.coverage = coverage;

    LLMatrix4a modelview_projection;
    getMetalSpotShadowModelviewProjection(
        params.mModelMatrix, modelview_projection);
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    if (!indexed_materials && params.mTextureMatrix &&
        (!gCubeSnapshot || mHeroProbeManager.isMirrorPass()))
    {
        std::memcpy(batch.texture_matrix, params.mTextureMatrix->mMatrix,
                    sizeof(batch.texture_matrix));
    }

    const auto metal_texture = [](LLViewerTexture* texture)
        -> ALMetalTexture*
    {
        LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
        ALMetalTexture* native = image ? image->getMetalTexture() : nullptr;
        if (!native)
        {
            // Match LLFetchedGLTFMaterial/texture-slot streaming fallback.
            LLViewerFetchedTexture* fallback =
                LLViewerFetchedTexture::sDefaultImagep.get();
            LLImageGL* fallback_image = fallback
                ? fallback->getGLTexture() : nullptr;
            native = fallback_image
                ? fallback_image->getMetalTexture() : nullptr;
        }
        return native;
    };
    for (std::size_t slot = 0; slot < texture_count; ++slot)
    {
        LLFetchedGLTFMaterial* material = indexed_materials
            ? params.mGLTFMaterialList[slot].get()
            : params.mGLTFMaterial.get();
        if (!material)
        {
            // Match the original indexed GL shadow owner: a null entry is a
            // fragmented-batch gap and no vertex in this draw references the
            // slot. Keep the slot numbering intact (the per-vertex material
            // index depends on it) and bind an inert white fallback rather
            // than invalidating every caster already captured for the map.
            LLViewerTexture* texture =
                LLViewerFetchedTexture::sWhiteImagep.get();
            batch.coverageData().textures[slot] = metal_texture(texture);
            batch.coverageData().alpha_cutoffs[slot] = 0.f;
            batch.coverageData().pbr_base_color_transforms[slot][0][0] = 1.f;
            batch.coverageData().pbr_base_color_transforms[slot][0][1] = 1.f;
            if (!batch.coverageData().textures[slot])
            {
                capture.spot_shadow_first_incomplete_source_line = __LINE__;
                capture.spot_shadow_capture_complete = false;
                capture.spot_shadow_batches.clear();
                return;
            }
            continue;
        }
        LLViewerTexture* texture = !indexed_materials
            ? params.mTexture.get() : nullptr;
        if (!texture)
        {
            texture = material->mBaseColorTexture.notNull()
                ? material->mBaseColorTexture.get()
                : LLViewerFetchedTexture::sWhiteImagep.get();
        }
        batch.coverageData().textures[slot] = metal_texture(texture);
        batch.coverageData().alpha_cutoffs[slot] =
            coverage == ALMetalWorldSpotShadowCoverage::pbr_blend
                ? ALPHA_BLEND_CUTOFF : material->mAlphaCutoff;
        LLGLTFMaterial::TextureTransform::Pack packed;
        material->mTextureTransform[
            LLGLTFMaterial::GLTF_TEXTURE_INFO_BASE_COLOR].getPacked(packed);
        std::memcpy(batch.coverageData().pbr_base_color_transforms[slot].data(), packed,
                    sizeof(packed));
        batch.double_sided = batch.double_sided || material->mDoubleSided;
        if (!batch.coverageData().textures[slot])
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
    }

    if (params.mAvatar || params.mSkinInfo)
    {
        if (!params.mAvatar || !params.mSkinInfo ||
            !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT4))
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
        const LLVOAvatar::MatrixPaletteCache& palette =
            params.mAvatar->updateSkinInfoMatrixPalette(params.mSkinInfo);
        const U32 joint_count = static_cast<U32>(
            palette.mMatrixPalette.size());
        if (joint_count == 0 || palette.mGLMp.size() !=
                4 + static_cast<std::size_t>(joint_count) * 12)
        {
            capture.spot_shadow_first_incomplete_source_line = __LINE__;
            capture.spot_shadow_capture_complete = false;
            capture.spot_shadow_batches.clear();
            return;
        }
        batch.weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT4);
        batch.skin_palette = palette.mGLMp.data();
        batch.skin_palette_float_count = palette.mGLMp.size();
        batch.skin_joint_count = joint_count;
    }
}

void LLPipeline::captureMetalSpotShadowTreeBatch(
    LLVertexBuffer* buffer, LLViewerTexture* texture,
    const LLMatrix4a* model_matrix)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_complete)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
    ALMetalTexture* native_texture = image
        ? image->getMetalTexture() : nullptr;
    if (image && !native_texture)
    {
        LLViewerFetchedTexture* fallback =
            LLViewerFetchedTexture::sDefaultImagep.get();
        LLImageGL* fallback_image = fallback
            ? fallback->getGLTexture() : nullptr;
        native_texture = fallback_image
            ? fallback_image->getMetalTexture() : nullptr;
    }
    if (!buffer || !image ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_COLOR) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer() || !native_texture ||
        buffer->getNumVerts() == 0 || buffer->getNumIndices() == 0 ||
        (buffer->getIndexStride() != 2 && buffer->getIndexStride() != 4))
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
        return;
    }

    auto* appended = capture.appendSeparateShadowBatch(__LINE__);
    if (!appended) return;
    auto& batch = *appended;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.texcoord_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_TEXCOORD0);
    batch.color_offset = buffer->getOffset(LLVertexBuffer::TYPE_COLOR);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = buffer->getNumIndices();
    batch.coverageData().textures[0] = native_texture;
    batch.texture_count = 1;
    batch.coverageData().alpha_cutoffs[0] = 0.5f;
    batch.coverage = ALMetalWorldSpotShadowCoverage::texture_mask;

    LLMatrix4a modelview_projection;
    getMetalSpotShadowModelviewProjection(
        model_matrix, modelview_projection);
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
}

void LLPipeline::captureMetalSpotShadowTerrainBatch(
    LLFace* face, F32 tess_density, F32 raster_segment,
    bool smoothing, bool tessellation_pinned)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_complete)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const auto fail = [&capture]()
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
    };
    LLDrawable* drawable = face ? face->getDrawable() : nullptr;
    LLVOSurfacePatch* object = drawable
        ? dynamic_cast<LLVOSurfacePatch*>(drawable->getVObj().get())
        : nullptr;
    LLSurfacePatch* patch = object ? object->getPatch() : nullptr;
    LLSurface* surface = patch ? patch->getSurface() : nullptr;
    LLViewerRegion* region = surface ? surface->getRegion() : nullptr;
    LLVertexBuffer* buffer = face ? face->getVertexBuffer() : nullptr;
    const ALMetalTexture* height_texture = surface
        ? surface->getSurfaceMaps().getMetalHeightTexture() : nullptr;
    if (!face || !patch || !surface || !region || !buffer ||
        !height_texture || !buffer->getMetalVertexBuffer() ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        face->getGeomCount() != LLVOSurfacePatch::PATCH_CORNERS ||
        face->getGeomIndex() + LLVOSurfacePatch::PATCH_CORNERS >
            buffer->getNumVerts() ||
        !std::isfinite(tess_density) ||
        (!tessellation_pinned && tess_density <= 0.f) ||
        !std::isfinite(raster_segment) ||
        !std::isfinite(surface->getMetersPerGrid()) ||
        surface->getMetersPerGrid() <= 0.f)
    {
        fail();
        return;
    }

    auto* appended = capture.appendSeparateShadowBatch(__LINE__);
    if (!appended) return;
    auto& batch = *appended;
    batch.terrain = true;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX) +
        static_cast<std::size_t>(face->getGeomIndex()) *
            sizeof(LLVector4a);
    batch.vertex_count = LLVOSurfacePatch::PATCH_CORNERS;
    batch.terrain_height_texture = height_texture;
    batch.terrain_grid_scale = surface->getMetersPerGrid();
    batch.terrain_smoothing = smoothing;
    batch.terrain_tessellation_pinned = tessellation_pinned;

    LLMatrix4a modelview_projection;
    LLMatrix4a* model_matrix = face->getDrawable() &&
            face->getDrawable()->getRegion()
        ? &face->getDrawable()->getRegion()->mRenderMatrix : nullptr;
    getMetalSpotShadowModelviewProjection(
        model_matrix, modelview_projection);
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));

    struct TerrainCorner
    {
        F32 x;
        F32 y;
        F32 z;
    };
    const LLVector3& patch_origin = patch->getOriginRegion();
    const F32 patch_size = surface->getGridsPerPatchEdge() *
                           batch.terrain_grid_scale;
    const auto corner = [&](F32 x, F32 y)
    {
        const S32 gx = ll_round(x / batch.terrain_grid_scale);
        const S32 gy = ll_round(y / batch.terrain_grid_scale);
        return TerrainCorner{x, y, surface->sampleZ(gx, gy)};
    };
    const std::array<TerrainCorner, 4> corners{{
        corner(patch_origin.mV[VX], patch_origin.mV[VY]),
        corner(patch_origin.mV[VX] + patch_size,
               patch_origin.mV[VY]),
        corner(patch_origin.mV[VX] + patch_size,
               patch_origin.mV[VY] + patch_size),
        corner(patch_origin.mV[VX],
               patch_origin.mV[VY] + patch_size),
    }};
    const LLVector3& camera_agent =
        LLViewerCamera::getInstance()->getOrigin();
    const LLVector3 tessellation_origin =
        camera_agent - region->getOriginAgent();

    LLMatrix4a clip;
    LLVector4a clip_origin;
    const bool raster_cap = raster_segment > 0.f &&
        tess_density > 0.f;
    F32 raster_x = 0.f;
    F32 raster_y = 0.f;
    if (raster_cap)
    {
        const LLCamera& pass = LLViewerCamera::getCurrent();
        clip.setMul(pass.getModelview(), pass.getProjection());
        clip.transform4(
            LLVector4a(camera_agent.mV[VX], camera_agent.mV[VY],
                       camera_agent.mV[VZ], 1.f),
            clip_origin);
        raster_x = 0.5f * static_cast<F32>(capture.spot_shadow_width) /
                   raster_segment;
        raster_y = 0.5f * static_cast<F32>(capture.spot_shadow_height) /
                   raster_segment;
    }

    const auto clip_corner = [&](const TerrainCorner& value)
    {
        LLVector4a relative(
            value.x - tessellation_origin.mV[VX],
            value.y - tessellation_origin.mV[VY],
            value.z - tessellation_origin.mV[VZ], 0.f);
        LLVector4a result;
        clip.transform4(relative, result);
        result.add(clip_origin);
        return result;
    };
    const auto edge_level = [&](const TerrainCorner& a,
                                const TerrainCorner& b)
    {
        if (tessellation_pinned)
        {
            return 16.f;
        }
        const F32 dx = b.x - a.x;
        const F32 dy = b.y - a.y;
        const F32 dz = b.z - a.z;
        const F32 length = sqrtf(dx * dx + dy * dy + dz * dz);
        const F32 mx = 0.5f * (a.x + b.x) -
                       tessellation_origin.mV[VX];
        const F32 my = 0.5f * (a.y + b.y) -
                       tessellation_origin.mV[VY];
        const F32 mz = 0.5f * (a.z + b.z) -
                       tessellation_origin.mV[VZ];
        const F32 distance = sqrtf(mx * mx + my * my + mz * mz);
        F32 level = length * tess_density / llmax(distance, 1.f);
        if (raster_cap)
        {
            const LLVector4a ca = clip_corner(a);
            const LLVector4a cb = clip_corner(b);
            if (llmin(ca[VW], cb[VW]) > 0.f)
            {
                const F32 sx = (cb[VX] / cb[VW] - ca[VX] / ca[VW]) *
                               raster_x;
                const F32 sy = (cb[VY] / cb[VW] - ca[VY] / ca[VW]) *
                               raster_y;
                level = llmin(level, sqrtf(sx * sx + sy * sy));
            }
        }
        return llclamp(level, 1.f, 64.f);
    };
    const std::array<F32, 4> outer{{
        edge_level(corners[0], corners[3]),
        edge_level(corners[0], corners[1]),
        edge_level(corners[1], corners[2]),
        edge_level(corners[3], corners[2]),
    }};
    const std::array<F32, 2> inner{{
        llmax(outer[1], outer[3]),
        llmax(outer[0], outer[2]),
    }};
    for (U32 edge = 0; edge < outer.size(); ++edge)
    {
        batch.terrain_tessellation_factors[edge] =
            ALWaterHeightBake::halfOf(outer[edge]);
    }
    for (U32 inside = 0; inside < inner.size(); ++inside)
    {
        batch.terrain_tessellation_factors[4 + inside] =
            ALWaterHeightBake::halfOf(inner[inside]);
    }
}

void LLPipeline::captureMetalSpotShadowAvatarBatch(
    LLViewerJointMesh& mesh, LLVertexBuffer* buffer,
    LLGLTexture* texture, U32 start, U32 end, U32 count,
    U32 offset, bool skinned, F32 draw_alpha)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active ||
        !mMetalWorldSimpleCapture->spot_shadow_avatar_pass_active)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const auto fail = [&capture](U32 source_line)
    {
        if (capture.spot_shadow_first_incomplete_source_line == 0)
        {
            capture.spot_shadow_first_incomplete_source_line = source_line;
        }
        capture.spot_shadow_capture_complete = false;
        capture.spot_shadow_batches.clear();
        capture.spot_shadow_avatar_palettes.clear();
    };
    if (capture.spot_shadow_expected_batches ==
        std::numeric_limits<std::size_t>::max())
    {
        fail(__LINE__);
        return;
    }
    // Count every authoritative avatar batch before validating its native
    // resources so a missing/invalid batch cannot accidentally satisfy final
    // reconciliation.
    ++capture.spot_shadow_expected_batches;

    ALMetalWorldSpotShadowCoverage coverage;
    switch (LLDrawPoolAvatar::sShadowPass)
    {
        case LLDrawPoolAvatar::SHADOW_PASS_AVATAR_OPAQUE:
            coverage = ALMetalWorldSpotShadowCoverage::opaque;
            break;
        case LLDrawPoolAvatar::SHADOW_PASS_AVATAR_OPAQUE_CUT:
        case LLDrawPoolAvatar::SHADOW_PASS_AVATAR_ALPHA_MASK:
            coverage = ALMetalWorldSpotShadowCoverage::avatar_mask;
            break;
        case LLDrawPoolAvatar::SHADOW_PASS_AVATAR_ALPHA_BLEND:
            coverage = ALMetalWorldSpotShadowCoverage::avatar_blend;
            break;
        default:
            fail(__LINE__);
            return;
    }

    const bool covered = coverage !=
        ALMetalWorldSpotShadowCoverage::opaque;
    LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
    ALMetalTexture* native_texture = image
        ? image->getMetalTexture() : nullptr;
    if (covered && image && !native_texture)
    {
        LLViewerFetchedTexture* fallback =
            LLViewerFetchedTexture::sDefaultImagep.get();
        LLImageGL* fallback_image = fallback
            ? fallback->getGLTexture() : nullptr;
        native_texture = fallback_image
            ? fallback_image->getMetalTexture() : nullptr;
    }
    if (!capture.spot_shadow_capture_complete || !buffer || count == 0 ||
        start > end || end >= buffer->getNumVerts() ||
        !std::isfinite(draw_alpha) || draw_alpha < 0.f || draw_alpha > 1.f ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->getMetalVertexBuffer() || !buffer->getMetalIndexBuffer() ||
        (covered && (!image || !native_texture)) ||
        (skinned && !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT)) ||
        (capture.spot_shadow_avatar_cloth &&
         (!skinned || !buffer->hasDataType(LLVertexBuffer::TYPE_NORMAL) ||
          !buffer->hasDataType(LLVertexBuffer::TYPE_CLOTHWEIGHT))))
    {
        fail(__LINE__);
        return;
    }
    const std::size_t index_stride = buffer->getIndexStride();
    if (index_stride != 2 && index_stride != 4)
    {
        fail(__LINE__);
        return;
    }
    const std::size_t index_offset =
        static_cast<std::size_t>(offset) * index_stride;
    if (count > (std::numeric_limits<std::size_t>::max() - index_offset) /
                    index_stride ||
        index_offset + static_cast<std::size_t>(count) * index_stride >
            buffer->getMetalIndexBuffer()->length())
    {
        fail(__LINE__);
        return;
    }

    auto* appended = capture.appendSeparateShadowBatch(__LINE__);
    if (!appended) return;
    auto& batch = *appended;
    batch.avatar = true;
    batch.avatar_cloth = capture.spot_shadow_avatar_cloth;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.texcoord_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_TEXCOORD0);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = index_offset;
    batch.index_type = index_stride == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = count;
    batch.coverage = coverage;
    batch.avatar_draw_alpha = draw_alpha;
    if (covered)
    {
        batch.coverageData().textures[0] = native_texture;
        batch.texture_count = 1;
        batch.coverageData().alpha_cutoffs[0] = LLDrawPoolAvatar::sMinimumAlpha;
    }

    if (skinned)
    {
        auto palette =
            std::make_unique<std::array<F32, 45 * 4>>();
        if (!mesh.buildJointMatrixPalette(
                palette->data(), palette->size()))
        {
            fail(__LINE__);
            return;
        }
        batch.weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT);
        batch.skin_palette = palette->data();
        batch.skin_palette_float_count = palette->size();
        batch.skin_joint_count = 15;
        capture.spot_shadow_avatar_palettes.push_back(
            std::move(palette));
        const LLMatrix4a& projection =
            capture.spot_shadow_explicit_matrices
            ? capture.spot_shadow_projection
            : gGL.getProjectionMatrix();
        std::memcpy(batch.modelview_projection,
                    projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
        if (batch.avatar_cloth)
        {
            batch.normal_offset = buffer->getOffset(
                LLVertexBuffer::TYPE_NORMAL);
            batch.cloth_offset = buffer->getOffset(
                LLVertexBuffer::TYPE_CLOTHWEIGHT);
            std::memcpy(batch.avatar_wind,
                        capture.spot_shadow_avatar_wind,
                        sizeof(batch.avatar_wind));
            std::memcpy(batch.avatar_sin_wave,
                        capture.spot_shadow_avatar_sin_wave,
                        sizeof(batch.avatar_sin_wave));
            std::memcpy(batch.avatar_gravity,
                        capture.spot_shadow_avatar_gravity,
                        sizeof(batch.avatar_gravity));
            std::memcpy(batch.avatar_cloth_depth,
                        capture.spot_shadow_avatar_cloth_depth,
                        sizeof(batch.avatar_cloth_depth));
        }
    }
    else
    {
        LLMatrix4a modelview_projection;
        const LLMatrix4a* model_matrix =
            capture.spot_shadow_explicit_matrices
            ? &mesh.getWorldMatrix() : nullptr;
        getMetalSpotShadowModelviewProjection(
            model_matrix, modelview_projection);
        std::memcpy(batch.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
    }
}

void LLPipeline::endMetalSpotShadowCapture()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->spot_shadow_capture_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    capture.spot_shadow_capture_active = false;
    if (capture.spot_shadow_avatar_pass_active)
    {
        capture.spot_shadow_first_incomplete_source_line = __LINE__;
        capture.spot_shadow_capture_complete = false;
    }
    capture.spot_shadow_avatar_pass_active = false;
    capture.spot_shadow_avatar_cloth = false;
    const U32 map = capture.spot_shadow_map;
    const bool directional = capture.spot_shadow_capture_directional;
    capture.spot_shadow_capture_directional = false;
    static const bool shadow_diagnostics = []
    {
        const char* value = std::getenv("ALCHEMY_METAL_SHADOW_DIAGNOSTICS");
        return value && value[0] != '\0' && value[0] != '0';
    }();
    const std::size_t pack_index =
        static_cast<std::size_t>(renderPack());
    const U32 map_bit = 1u << map;
    const bool complete = capture.spot_shadow_capture_complete &&
        capture.renderer && capture.device &&
        capture.spot_shadow_admission.complete(capture.spot_shadow_expected_batches);
    static std::array<U32,
        static_cast<std::size_t>(ALRenderResourcePlan::Pack::COUNT)>
        diagnosed_incomplete_directional_slices{};
    if (shadow_diagnostics && directional && !complete &&
        pack_index < diagnosed_incomplete_directional_slices.size() &&
        (diagnosed_incomplete_directional_slices[pack_index] & map_bit) == 0)
    {
        diagnosed_incomplete_directional_slices[pack_index] |= map_bit;
        LL_WARNS("Metal")
            << "Directional-shadow capture incomplete: pack="
            << pack_index << ", slice=" << map
            << ", capture_complete="
            << capture.spot_shadow_capture_complete
            << ", first_incomplete_line="
            << capture.spot_shadow_first_incomplete_source_line
            << ", batches=" << capture.spot_shadow_batches.size()
            << ", sources=" << capture.spot_shadow_admission.sourceCount()
            << ", expected=" << capture.spot_shadow_expected_batches
            << ", renderer=" << static_cast<bool>(capture.renderer)
            << ", device=" << static_cast<bool>(capture.device)
            << LL_ENDL;
    }
    capture.spot_shadow_capture_complete = false;
    if (!complete)
    {
        capture.spot_shadow_batches.clear();
        capture.spot_shadow_avatar_palettes.clear();
        return;
    }

    ALMetalWorldSpotShadowScene scene;
    scene.batches = capture.spot_shadow_batches.data();
    scene.batch_count = capture.spot_shadow_batches.size();
    scene.source_batch_count = capture.spot_shadow_admission.sourceCount();
    scene.early_merged_source_count = capture.spot_shadow_admission.mergedSourceCount();
    scene.width = capture.spot_shadow_width;
    scene.height = capture.spot_shadow_height;
    scene.reverse_z = capture.reverse_z;
    scene.depth_clamp = directional;
    std::string error;
    const std::size_t rendered_batches = capture.spot_shadow_batches.size();

    ALMetalTextureDescriptor descriptor;
    descriptor.type = ALMetalTextureType::texture_2d_array;
    descriptor.format = ALMetalPixelFormat::r32_float;
    descriptor.width = scene.width;
    descriptor.height = scene.height;
    descriptor.array_length = directional ? 4 : 2;
    descriptor.storage = ALMetalStorageMode::private_gpu;
    descriptor.usage = ALMetalTextureUsage::render_target |
        ALMetalTextureUsage::shader_read;
    descriptor.label = directional
        ? "Alchemy direct raw directional-shadow maps"
        : "Alchemy direct raw projector-shadow maps";
    std::unique_ptr<ALMetalTexture>& retained_texture = directional
        ? capture.direct_directional_shadow_texture
        : capture.direct_projector_shadow_texture;
    const ALMetalTextureDescriptor* existing =
        retained_texture
            ? &retained_texture->descriptor()
            : nullptr;
    if (!existing || existing->type != descriptor.type ||
        existing->format != descriptor.format ||
        existing->width != descriptor.width ||
        existing->height != descriptor.height ||
        existing->array_length != descriptor.array_length ||
        existing->usage != descriptor.usage)
    {
        retained_texture = ALMetalTexture::create(
            *capture.device, descriptor, &error);
        if (directional)
        {
            capture.direct_directional_shadow_valid = {};
        }
        else
        {
            capture.direct_projector_shadow_valid = {};
        }
        if (!retained_texture)
        {
            capture.spot_shadow_batches.clear();
            capture.spot_shadow_avatar_palettes.clear();
            LL_WARNS("Metal")
                << "Could not allocate direct Metal "
                << (directional ? "directional" : "spot")
                << "-shadow pack: "
                << error << LL_ENDL;
            return;
        }
    }

    const bool rendered = capture.renderer->renderSpotShadow(
        *retained_texture, map, scene, &error);
    if (!rendered)
    {
        capture.spot_shadow_batches.clear();
        capture.spot_shadow_avatar_palettes.clear();
        LL_WARNS("Metal")
            << "Could not render direct Metal "
            << (directional ? "directional" : "spot")
            << "-shadow slice " << map
            << ": " << error << LL_ENDL;
        return;
    }

    // A live shadow defect can otherwise collapse three distinct states into
    // the same "retained" milestone: a populated slice, an intentional
    // all-far slice, or caster geometry transformed outside the map. Keep the
    // synchronous readback strictly opt-in and one-shot per pack/slice; it is
    // diagnostic evidence, never part of ordinary rendering or correctness.
    static std::array<U32,
        static_cast<std::size_t>(ALRenderResourcePlan::Pack::COUNT)>
        diagnosed_directional_slices{};
    if (shadow_diagnostics && directional &&
        !capture.renderer->commandBatchActive() &&
        pack_index < diagnosed_directional_slices.size() &&
        (diagnosed_directional_slices[pack_index] & map_bit) == 0)
    {
        diagnosed_directional_slices[pack_index] |= map_bit;
        std::vector<F32> depths(
            static_cast<std::size_t>(scene.width) * scene.height);
        std::string diagnostic_error;
        const bool read = retained_texture->readback(
            *capture.device, 0, map, {}, depths.data(),
            static_cast<std::size_t>(scene.width) * sizeof(F32),
            &diagnostic_error);
        if (read)
        {
            const F32 far_depth = scene.reverse_z ? 0.f : 1.f;
            F32 minimum = std::numeric_limits<F32>::infinity();
            F32 maximum = -std::numeric_limits<F32>::infinity();
            std::size_t finite = 0;
            std::size_t non_far = 0;
            for (F32 depth : depths)
            {
                if (!std::isfinite(depth))
                {
                    continue;
                }
                ++finite;
                minimum = std::min(minimum, depth);
                maximum = std::max(maximum, depth);
                non_far += std::abs(depth - far_depth) > 0.000001f;
            }
            LL_INFOS("Metal")
                << "Directional-shadow diagnostic: pack=" << pack_index
                << ", slice=" << map
                << ", size=" << scene.width << "x" << scene.height
                << ", batches=" << rendered_batches
                << ", sources=" << capture.spot_shadow_admission.sourceCount()
                << ", expected=" << capture.spot_shadow_expected_batches
                << ", reverse_z=" << scene.reverse_z
                << ", finite=" << finite
                << ", non_far=" << non_far
                << ", min=" << minimum
                << ", max=" << maximum
                << LL_ENDL;
        }
        else
        {
            LL_WARNS("Metal")
                << "Directional-shadow diagnostic readback failed: pack="
                << pack_index << ", slice=" << map << ": "
                << diagnostic_error << LL_ENDL;
        }

        std::array<F32, 3> ndc_min{
            std::numeric_limits<F32>::infinity(),
            std::numeric_limits<F32>::infinity(),
            std::numeric_limits<F32>::infinity()};
        std::array<F32, 3> ndc_max{
            -std::numeric_limits<F32>::infinity(),
            -std::numeric_limits<F32>::infinity(),
            -std::numeric_limits<F32>::infinity()};
        std::size_t sampled_batches = 0;
        std::size_t samples_inside_xy = 0;
        std::size_t samples_inside_z = 0;
        std::size_t samples_inside = 0;
        for (std::size_t batch_index = 0;
             batch_index < capture.spot_shadow_batches.size();
             ++batch_index)
        {
            const ALMetalWorldSpotShadowBatch& batch =
                capture.spot_shadow_batches[batch_index];
            if (batch.terrain || batch.avatar || batch.skin_palette ||
                !batch.vertices || !batch.indices ||
                batch.index_count == 0)
            {
                continue;
            }

            U32 vertex_index = 0;
            std::string vertex_error;
            bool vertex_read = false;
            if (batch.index_type == ALMetalIndexType::uint32)
            {
                vertex_read = batch.indices->readback(
                    *capture.device, batch.index_offset, &vertex_index,
                    sizeof(vertex_index), &vertex_error);
            }
            else
            {
                U16 short_index = 0;
                vertex_read = batch.indices->readback(
                    *capture.device, batch.index_offset, &short_index,
                    sizeof(short_index), &vertex_error);
                vertex_index = short_index;
            }

            LLVector4a object_position;
            if (vertex_read && vertex_index < batch.vertex_count)
            {
                vertex_read = batch.vertices->readback(
                    *capture.device,
                    batch.position_offset +
                        static_cast<std::size_t>(vertex_index) *
                            sizeof(LLVector4a),
                    object_position.getF32ptr(), sizeof(LLVector4a),
                    &vertex_error);
            }
            if (!vertex_read)
            {
                LL_WARNS("Metal")
                    << "Directional-shadow caster diagnostic readback "
                       "failed: batch=" << batch_index << ": "
                    << vertex_error << LL_ENDL;
                continue;
            }

            LLMatrix4a matrix;
            std::memcpy(matrix.getF32ptr(), batch.modelview_projection,
                        sizeof(batch.modelview_projection));
            const LLVector4a shader_position(
                object_position[VX], object_position[VY],
                object_position[VZ], 1.f);
            LLVector4a clip_position;
            matrix.transform4(shader_position, clip_position);
            const F32 inverse_w = clip_position[VW] != 0.f
                ? 1.f / clip_position[VW] : 0.f;
            const LLVector4a ndc(
                clip_position[VX] * inverse_w,
                clip_position[VY] * inverse_w,
                clip_position[VZ] * inverse_w, 1.f);
            ++sampled_batches;
            for (U32 axis = 0; axis < 3; ++axis)
            {
                ndc_min[axis] = std::min(ndc_min[axis], ndc[axis]);
                ndc_max[axis] = std::max(ndc_max[axis], ndc[axis]);
            }
            const bool inside_xy = std::abs(ndc[VX]) <= 1.f &&
                std::abs(ndc[VY]) <= 1.f;
            const bool inside_z = ndc[VZ] >= 0.f && ndc[VZ] <= 1.f;
            samples_inside_xy += inside_xy;
            samples_inside_z += inside_z;
            samples_inside += inside_xy && inside_z;
            if (sampled_batches == 1)
            {
                LL_INFOS("Metal")
                    << "Directional-shadow caster diagnostic: batch="
                    << batch_index << ", vertex=" << vertex_index
                    << ", object=(" << object_position[VX] << ","
                    << object_position[VY] << "," << object_position[VZ]
                    << "," << object_position[VW] << ")"
                    << ", clip=(" << clip_position[VX] << ","
                    << clip_position[VY] << "," << clip_position[VZ]
                    << "," << clip_position[VW] << ")"
                    << ", ndc=(" << ndc[VX] << "," << ndc[VY]
                    << "," << ndc[VZ] << ")"
                    << LL_ENDL;
            }
        }
        if (sampled_batches != 0)
        {
            LL_INFOS("Metal")
                << "Directional-shadow caster sample summary: pack="
                << pack_index << ", slice=" << map
                << ", sampled=" << sampled_batches
                << ", inside_xy=" << samples_inside_xy
                << ", inside_z=" << samples_inside_z
                << ", inside=" << samples_inside
                << ", ndc_min=(" << ndc_min[VX] << ","
                << ndc_min[VY] << "," << ndc_min[VZ] << ")"
                << ", ndc_max=(" << ndc_max[VX] << ","
                << ndc_max[VY] << "," << ndc_max[VZ] << ")"
                << LL_ENDL;
        }
    }

    capture.spot_shadow_batches.clear();
    capture.spot_shadow_avatar_palettes.clear();
    if (directional)
    {
        capture.direct_directional_shadow_valid[map] = true;
        capture.impostor_directional_shadow_frame =
            std::numeric_limits<U32>::max();
        if (!mMetalDirectionalShadowReported)
        {
            mMetalDirectionalShadowReported = true;
            LL_INFOS("Metal")
                << "Direct Metal directional-shadow slices are rendered "
                   "in place from native caster draws; no retention copy "
                   "or GL depth import remains"
                << LL_ENDL;
        }
    }
    else
    {
        capture.direct_projector_shadow_valid[map] = true;
        capture.projector_shadow_frame = std::numeric_limits<U32>::max();
        if (!mMetalProjectorShadowReported)
        {
            mMetalProjectorShadowReported = true;
            LL_INFOS("Metal")
                << "Direct Metal projector-shadow slices are rendered "
                   "in place from native caster draws; no retention copy "
                   "or GL depth import remains"
                << LL_ENDL;
        }
    }
}

bool LLPipeline::fillMetalWorldProjectorShadows()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->device)
    {
        return false;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const U32 unbuilt = (unbuiltShadowMaps() >> 4u) & 0x3u;
    if (unbuilt == 0x3u)
    {
        // Cold startup may reach cube faces before the main view has built
        // either map. The light collector leaves those lights unshadowed and
        // the renderer binds its own lit fallback; no retained texture is
        // needed or exposed as a valid shadow input in that case.
        capture.projector_shadows = {};
        capture.projector_shadows.constants.config[0] = 2;
        capture.projector_shadows.constants.config[1] = unbuilt;
        capture.projector_shadow_frame = gFrameCount;
        return true;
    }
    // Projector maps belong to the main view even while a cube face is
    // active. The owner swap leaves that retained map pair in the probe
    // slot; only the receiver matrices below depend on the current face.
    const MetalWorldSimpleCapture* shadow_owner =
        isMetalProbeFaceCaptureActive()
            ? mMetalProbeWorldSimpleCapture.get()
            : &capture;
    if (!shadow_owner || shadow_owner->device != capture.device)
    {
        return false;
    }
    const ALMetalTextureDescriptor* direct =
        shadow_owner->direct_projector_shadow_texture
            ? &shadow_owner->direct_projector_shadow_texture->descriptor()
            : nullptr;
    if (!direct || direct->type != ALMetalTextureType::texture_2d_array ||
        direct->format != ALMetalPixelFormat::r32_float ||
        direct->width == 0 || direct->height == 0 ||
        direct->array_length != 2)
    {
        return false;
    }
    const U32 width = direct->width;
    const U32 height = direct->height;

    const auto publish = [&](const ALMetalTexture* texture)
    {
        ALMetalWorldDirectionalShadowConstants constants;
        std::memcpy(constants.shadow_matrix[0],
                    mNativeShadowData.shadow_matrix[4],
                    sizeof(constants.shadow_matrix[0]));
        std::memcpy(constants.shadow_matrix[1],
                    mNativeShadowData.shadow_matrix[5],
                    sizeof(constants.shadow_matrix[1]));
        std::memcpy(constants.shadow_clip,
                    mNativeShadowData.shadow_clip,
                    sizeof(constants.shadow_clip));
        constants.resolution[0] = static_cast<F32>(width);
        constants.resolution[1] = static_cast<F32>(height);
        constants.resolution[2] = static_cast<F32>(capture.width);
        constants.resolution[3] = static_cast<F32>(capture.height);
        constants.parameters[0] = mNativeShadowData.spot_shadow_bias;
        constants.parameters[1] = mNativeShadowData.spot_shadow_offset;
        constants.parameters[2] = mNativeShadowData.shadow_pcss_scale;
        constants.parameters[3] = static_cast<F32>(capture.height);
        constants.config[0] = 2;
        constants.config[1] = unbuilt;
        constants.config[2] = capture.reverse_z ? 1u : 0u;
        constants.config[3] = static_cast<U32>(std::clamp(
            shaderInputs().mGlobal.mShadowFilterQuality, 0, 3)) |
            (gCubeSnapshot
                 ? ALMetalWorldDirectionalShadowConstants::probe_single_tap
                 : 0u);

        capture.projector_shadows.depth_texture = texture;
        capture.projector_shadows.constants = constants;
        capture.projector_shadow_frame = gFrameCount;
        return true;
    };

    bool direct_complete = true;
    for (U32 index = 0; direct_complete && index < 2; ++index)
    {
        direct_complete = (unbuilt & (1u << index)) != 0 ||
            shadow_owner->direct_projector_shadow_valid[index];
    }
    // Publish from the current owner every time: multiple cube faces can
    // share a frame number while their receiver matrices differ, and an
    // earlier publication must not retain a replaced owner's texture.
    return direct_complete &&
        publish(shadow_owner->direct_projector_shadow_texture.get());
}

void LLPipeline::captureMetalImpostorLegacyMaterialAlphaBatch(
    const LLDrawInfo& params, bool particle_or_hud_particle,
    bool depth_only)
{
    if (!mMetalWorldSimpleCapture || !params.mMaterial)
    {
        return;
    }

    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool world_pre_water = capture.world_post_deferred_active &&
        capture.world_pre_water_alpha_active;
    const bool world_post_water = capture.world_post_deferred_active &&
        capture.world_post_water_alpha_active;
    const bool world_alpha = world_pre_water || world_post_water;
    if (!capture.impostor_alpha_active && !world_alpha)
    {
        return;
    }
    if (depth_only && !world_post_water)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    const U32 shader_mask = params.mShaderMask;
    if (shader_mask >= LLMaterial::SHADER_COUNT ||
        (shader_mask & 0x3u) != LLMaterial::DIFFUSE_ALPHA_MODE_BLEND ||
        params.mGLTFMaterial.notNull() ||
        (!world_alpha &&
         (particle_or_hud_particle ||
          params.mBlendFuncSrc != LLRender::BF_SOURCE_ALPHA ||
          params.mBlendFuncDst != LLRender::BF_ONE_MINUS_SOURCE_ALPHA)))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    bool uses_shadows = metalWorldAlphaUsesDirectionalShadows(*this);
    if (uses_shadows && !fillMetalImpostorDirectionalShadows())
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    if (world_alpha)
    {
        uses_shadows = uses_shadows &&
            capture.impostor_directional_shadows.depth_texture != nullptr;
        capture.world_alpha_uses_shadows =
            capture.world_alpha_uses_shadows || uses_shadows;
    }
    else
    {
        capture.impostor_legacy_alpha_uses_shadows =
            capture.impostor_legacy_alpha_uses_shadows || uses_shadows;
    }

    bool& lighting_valid = world_alpha
        ? capture.world_alpha_lighting_valid
        : capture.impostor_legacy_alpha_lighting_valid;
    ALMetalWorldLegacyAlphaLighting& captured_lighting = world_alpha
        ? capture.world_alpha_lighting
        : capture.impostor_legacy_alpha_lighting;
    if (!lighting_valid)
    {
        ALMetalWorldLegacyAlphaLighting lighting;
        if (!fillMetalWorldAlphaLighting(lighting))
        {
            capture.markIncomplete(__LINE__);
            capture.batches.clear();
            return;
        }
        captured_lighting = lighting;
        lighting_valid = true;
    }

    const std::size_t first_batch = capture.batches.size();
    capture.rigged = params.mAvatar != nullptr;
    capture.alpha_mask = false;
    capture.material_alpha_mode = LLMaterial::DIFFUSE_ALPHA_MODE_BLEND;
    capture.material_normal_map = (shader_mask & 0x8u) != 0;
    capture.material_specular_map = (shader_mask & 0x4u) != 0;
    capture.pbr = false;
    capture.terrain = false;
    capture.avatar = false;
    capture.impostor = false;
    capture.impostor_fullbright = false;
    capture.impostor_shiny = false;
    capture.impostor_emboss = false;
    capture.pass_active = true;
    captureMetalWorldMaterialBatch(params, false);
    capture.pass_active = false;
    if (capture.complete &&
        capture.batches.size() == first_batch + 1)
    {
        ALMetalWorldSimpleBatch& batch = capture.batches.back();
        if (world_alpha)
        {
            batch.pre_water_alpha = world_pre_water;
            batch.post_water_alpha = world_post_water;
            batch.pre_water_material = true;
            batch.pre_water_shadows = uses_shadows;
            if (!fillMetalWorldPreWaterAlphaDraw(
                    batch, params, particle_or_hud_particle,
                    depth_only, false))
            {
                capture.markIncomplete(__LINE__);
                capture.batches.clear();
                return;
            }
        }
    }
    capture.material_alpha_mode = 0;
    capture.material_normal_map = false;
    capture.material_specular_map = false;
}

void LLPipeline::captureMetalWorldAvatarBatch(
    LLViewerJointMesh& mesh, LLVertexBuffer* buffer,
    LLGLTexture* texture, U32 start, U32 end, U32 count, U32 offset,
    bool diffuse_srgb)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active ||
        !mMetalWorldSimpleCapture->avatar)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool avatar_alpha = capture.world_post_deferred_active &&
        !capture.world_post_deferred_phase;
    const auto fail = [&capture]()
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.avatar_palettes.clear();
    };
    const bool direct_avatar_alpha = avatar_alpha &&
        capture.direct_avatar_alpha;
    if (direct_avatar_alpha &&
        !capture.direct_avatar_alpha_state_active)
    {
        fail();
        return;
    }
    LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
    if (!capture.complete || !buffer || !image || count == 0 ||
        start > end || end >= buffer->getNumVerts() ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_NORMAL) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->getMetalVertexBuffer() || !buffer->getMetalIndexBuffer() ||
        !image->getMetalTexture() ||
        (capture.avatar_skinned &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_WEIGHT)) ||
        (capture.avatar_cloth &&
         !buffer->hasDataType(LLVertexBuffer::TYPE_CLOTHWEIGHT)))
    {
        fail();
        return;
    }
    const std::size_t index_stride = buffer->getIndexStride();
    if (index_stride != 2 && index_stride != 4)
    {
        fail();
        return;
    }
    const std::size_t index_offset =
        static_cast<std::size_t>(offset) * index_stride;
    if (count > (std::numeric_limits<std::size_t>::max() - index_offset) /
                    index_stride ||
        index_offset + static_cast<std::size_t>(count) * index_stride >
            buffer->getMetalIndexBuffer()->length())
    {
        fail();
        return;
    }

    ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.normal_offset = buffer->getOffset(LLVertexBuffer::TYPE_NORMAL);
    batch.texcoord_offset = buffer->getOffset(
        LLVertexBuffer::TYPE_TEXCOORD0);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_offset = index_offset;
    batch.index_type = index_stride == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = count;
    batch.diffuse_textures[0] = image->getMetalTexture();
    batch.texture_count = 1;
    batch.alpha_mask = !avatar_alpha;
    batch.use_vertex_color = false;
    batch.alpha_cutoff_bias = false;
    batch.alpha_cutoff = avatar_alpha
        ? 0.f : LLDrawPoolAvatar::sMinimumAlpha;
    batch.avatar_diffuse_srgb = diffuse_srgb;
    batch.avatar_rigid = !capture.avatar_skinned;
    batch.avatar_skinning = capture.avatar_skinned;
    batch.avatar_cloth = capture.avatar_cloth;
    batch.avatar_alpha = avatar_alpha;
    if (avatar_alpha)
    {
        if (direct_avatar_alpha)
        {
            batch.avatar_cull_mode =
                capture.direct_avatar_alpha_cull_mode;
            batch.avatar_depth_write =
                capture.direct_avatar_alpha_depth_write;
            batch.avatar_color_write =
                capture.direct_avatar_alpha_color_write;
            batch.pre_water_alpha_writes_coverage = false;
        }
        else
        {
            if (!LLGLState::isEnabled(GL_CULL_FACE))
            {
                batch.avatar_cull_mode = ALMetalCullMode::none;
            }
            else if (gGL.getCullFace() == GL_FRONT)
            {
                batch.avatar_cull_mode = ALMetalCullMode::front;
            }
            else if (gGL.getCullFace() == GL_BACK)
            {
                batch.avatar_cull_mode = ALMetalCullMode::back;
            }
            else
            {
                fail();
                return;
            }
            batch.avatar_depth_write =
                LLGLDepthTest::depthWriteEnabled();
            bool color_mask[4]{};
            gGL.getColorMask(color_mask);
            if (color_mask[0] != color_mask[1] ||
                color_mask[0] != color_mask[2])
            {
                fail();
                return;
            }
            batch.avatar_color_write = color_mask[0];
            batch.pre_water_alpha_writes_coverage = color_mask[3];
        }
        batch.pre_water_simple = true;
        batch.pre_water_shadows =
            capture.world_alpha_uses_shadows;
        batch.pre_water_minimum_alpha =
            LLDrawPoolAvatar::sMinimumAlpha;
        batch.pre_water_source_rgb =
            ALMetalBlendFactor::source_alpha;
        batch.pre_water_destination_rgb =
            ALMetalBlendFactor::one_minus_source_alpha;
    }

    if (capture.avatar_skinned)
    {
        auto palette =
            std::make_unique<std::array<F32, 45 * 4>>();
        if (!mesh.buildJointMatrixPalette(
                palette->data(), palette->size()))
        {
            fail();
            return;
        }
        batch.weight_offset = buffer->getOffset(
            LLVertexBuffer::TYPE_WEIGHT);
        batch.skin_palette = palette->data();
        batch.skin_palette_float_count = palette->size();
        batch.skin_joint_count = 15;
        capture.avatar_palettes.push_back(std::move(palette));
        std::memcpy(batch.modelview_projection,
                    LLViewerCamera::getCurrent().getProjection().getF32ptr(),
                    sizeof(batch.modelview_projection));
        if (capture.avatar_cloth)
        {
            batch.cloth_offset = buffer->getOffset(
                LLVertexBuffer::TYPE_CLOTHWEIGHT);
            std::memcpy(batch.avatar_wind, capture.avatar_wind,
                        sizeof(batch.avatar_wind));
            std::memcpy(batch.avatar_sin_wave, capture.avatar_sin_wave,
                        sizeof(batch.avatar_sin_wave));
            std::memcpy(batch.avatar_gravity, capture.avatar_gravity,
                        sizeof(batch.avatar_gravity));
            std::memcpy(batch.avatar_cloth_depth,
                        capture.avatar_cloth_depth,
                        sizeof(batch.avatar_cloth_depth));
        }
    }
    else
    {
        LLMatrix4a modelview;
        LLMatrix4a inverse_modelview;
        LLMatrix4a modelview_projection;
        if (!buildMetalWorldDrawMatrices(
                &mesh.getWorldMatrix(), modelview, inverse_modelview,
                modelview_projection))
        {
            fail();
            return;
        }
        std::memcpy(batch.modelview_projection,
                    modelview_projection.getF32ptr(),
                    sizeof(batch.modelview_projection));
        std::memcpy(batch.modelview, modelview.getF32ptr(),
                    sizeof(batch.modelview));
        const F32* inverse = inverse_modelview.getF32ptr();
        for (U32 column = 0; column < 3; ++column)
        {
            batch.normal_matrix[column][0] = inverse[0 * 4 + column];
            batch.normal_matrix[column][1] = inverse[1 * 4 + column];
            batch.normal_matrix[column][2] = inverse[2 * 4 + column];
        }
    }
    if (capture.direct_probe_scene_active && avatar_alpha)
    {
        capture.direct_avatar_alpha_state_active = false;
    }
}

void LLPipeline::captureMetalWorldImpostorBatch(
    LLVOAvatar& avatar, const LLVector3& center,
    const LLVector3& left, const LLVector3& up,
    const LLMatrix3a& normal_rotation, F32 debug_outline_width)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active ||
        !mMetalWorldSimpleCapture->impostor)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    const bool debug_requested =
        hasRenderDebugMask(RENDER_DEBUG_IMPOSTORS);
    const bool debug_outline = debug_outline_width > 0.f;
    bool debug_state_valid = !debug_requested && !debug_outline &&
        debug_outline_width == 0.f;
    if (debug_requested && debug_outline)
    {
        LLRender::eBlendFactor color_source;
        LLRender::eBlendFactor color_destination;
        LLRender::eBlendFactor alpha_source;
        LLRender::eBlendFactor alpha_destination;
        gGL.getBlendFunc(color_source, color_destination,
                         alpha_source, alpha_destination);
        U32 rgb_equation = 0;
        U32 alpha_equation = 0;
        gGL.getBlendEquation(rgb_equation, alpha_equation);
        bool color_mask[4]{};
        gGL.getColorMask(color_mask);
        debug_state_valid =
            std::isfinite(debug_outline_width) &&
            debug_outline_width >= 1.f && debug_outline_width <= 5.f &&
            gGL.getLineWidth() == debug_outline_width &&
            LLGLState::isEnabled(GL_BLEND) &&
            LLGLState::isEnabled(GL_CULL_FACE) &&
            LLGLDepthTest::depthEnabled() &&
            LLGLDepthTest::depthWriteEnabled() &&
            LLGLDepthTest::depthFunction() == GL_LEQUAL &&
            color_source == LLRender::BF_ONE &&
            color_destination == LLRender::BF_ONE &&
            alpha_source == LLRender::BF_ONE &&
            alpha_destination == LLRender::BF_ONE &&
            rgb_equation == GL_FUNC_ADD &&
            alpha_equation == GL_FUNC_ADD &&
            color_mask[0] && color_mask[1] &&
            color_mask[2] && color_mask[3];
    }
    if (!capture.complete || !debug_state_valid)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.avatar_palettes.clear();
        return;
    }
    ALMetalAvatarResources::Key key{};
    std::copy_n(avatar.getID().mData, key.size(), key.begin());
    auto textures = capture.avatar_resources->find(
        key, *capture.device, capture.hdr, capture.normal_hdr);
    const bool has_textures = static_cast<bool>(textures);
    if (!has_textures)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.avatar_palettes.clear();
        // Ask the normal avatar scheduler for one fresh bake. The draw-pool
        // capture publishes one coherent four-attachment native generation;
        // no legacy render-target pixels are imported as a fallback.
        avatar.mNeedsImpostorUpdate = true;
        return;
    }

    const LLMatrix4a& modelview =
        LLViewerCamera::getCurrent().getModelview();
    LLMatrix4a modelview_projection;
    modelview_projection.setMul(
        modelview, LLViewerCamera::getCurrent().getProjection());

    ALMetalWorldSimpleBatch batch;
    batch.impostor = true;
    batch.impostor_texture_owner = textures;
    batch.impostor_debug_outline = debug_outline;
    batch.impostor_debug_line_width = debug_outline_width;
    for (std::size_t texture = 0;
         texture < batch.impostor_textures.size(); ++texture)
    {
        batch.impostor_textures[texture] =
            textures->textures[texture].get();
    }
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    std::memcpy(batch.modelview, modelview.getF32ptr(),
                sizeof(batch.modelview));
    std::memcpy(batch.impostor_center, center.mV, sizeof(center.mV));
    std::memcpy(batch.impostor_left, left.mV, sizeof(left.mV));
    std::memcpy(batch.impostor_up, up.mV, sizeof(up.mV));
    for (U32 row = 0; row < 3; ++row)
    {
        std::memcpy(batch.impostor_normal_rotation[row],
                    normal_rotation.getRow(row).getF32ptr(),
                    sizeof(batch.impostor_normal_rotation[row]));
    }
    try
    {
        capture.batches.push_back(batch);
    }
    catch (const std::bad_alloc&)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        capture.avatar_palettes.clear();
    }
}

bool LLPipeline::publishMetalImpostorBake(LLVOAvatar& avatar)
{
    if (!mMetalWorldSimpleCapture)
    {
        return false;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device ||
        capture.impostor_bake_avatar_id != avatar.getID())
    {
        return false;
    }

    const U32 width = capture.width;
    const U32 height = capture.height;
    bool native_ready = width != 0 && height != 0 &&
        capture.impostor_bake_attempted &&
        capture.impostor_bake_native_valid &&
        capture.impostor_bake_native_complete &&
        capture.impostor_bake_target;
    if (native_ready)
    {
        const ALMetalRenderTargetDescriptor& descriptor =
            capture.impostor_bake_target->descriptor();
        native_ready = descriptor.width == width &&
            descriptor.height == height && descriptor.sample_count == 1 &&
            descriptor.color_attachment_count == 4 &&
            descriptor.colors[0].format ==
                ALMetalPixelFormat::rgba8_unorm_srgb &&
            descriptor.colors[1].format ==
                ALMetalPixelFormat::rgba8_unorm &&
            descriptor.colors[2].format ==
                (capture.normal_hdr
                     ? ALMetalPixelFormat::rgba16_unorm
                     : ALMetalPixelFormat::rgb10a2_unorm) &&
            descriptor.colors[3].format ==
                (capture.hdr ? ALMetalPixelFormat::rg11b10_float
                             : ALMetalPixelFormat::rgba8_unorm);
        for (U32 attachment = 0; native_ready && attachment < 4;
             ++attachment)
        {
            native_ready =
                capture.impostor_bake_target->colorTexture(attachment) !=
                nullptr;
        }
    }

    if (native_ready)
    {
        std::array<std::unique_ptr<ALMetalTexture>, 4> textures;
        for (U32 attachment = 0; attachment < textures.size(); ++attachment)
        {
            textures[attachment] =
                capture.impostor_bake_target->takeColorTexture(attachment);
        }
        native_ready = std::all_of(
            textures.begin(), textures.end(),
            [](const std::unique_ptr<ALMetalTexture>& texture)
            {
                return texture != nullptr;
            });
        if (native_ready)
        {
            ALMetalAvatarResources::Record published;
            published.textures = std::move(textures);
            published.device = capture.device;
            published.width = width;
            published.height = height;
            published.normal_hdr = capture.normal_hdr;
            published.hdr = capture.hdr;
            ALMetalAvatarResources::Key key{};
            std::copy_n(avatar.getID().mData, key.size(), key.begin());
            std::string publication_error;
            native_ready = capture.avatar_resources->publish(
                key, std::move(published), &publication_error);
            if (!native_ready)
                LL_WARNS("Metal") << "Could not publish avatar impostor: "
                    << publication_error << LL_ENDL;
            if (native_ready) LL_DEBUGS("Metal")
                << "Published native avatar-impostor G-buffer "
                << avatar.getID() << " at " << width << "x" << height
                << " without a legacy render-target readback" << LL_ENDL;
        }
    }

    if (!native_ready)
    {
        // Allocation of the logical LLRenderTarget is not a publication
        // receipt. Keep the avatar dirty until a complete native quartet
        // exists; otherwise the reader and producer can suppress each
        // other's retry indefinitely during attachment loading.
        static U32 failed_publication_reports = 0;
        if (failed_publication_reports++ < 16)
        {
            LL_WARNS("Metal") << "Native avatar-impostor publication deferred: "
                << "attempted=" << capture.impostor_bake_attempted
                << ", valid=" << capture.impostor_bake_native_valid
                << ", complete=" << capture.impostor_bake_native_complete
                << ", target=" << bool(capture.impostor_bake_target)
                << ", first invalidation pipeline.cpp:"
                << capture.impostor_bake_first_incomplete_line << LL_ENDL;
        }
    }
    capture.impostor_bake_target.reset();
    capture.impostor_bake_avatar_id.setNull();
    capture.impostor_bake_attempted = false;
    capture.impostor_bake_native_valid = false;
    capture.impostor_bake_native_complete = false;
    capture.impostor_alpha_active = false;
    capture.impostor_alpha_phase = false;
    return native_ready;
}

void LLPipeline::releaseMetalImpostorTextures(const LLUUID& avatar_id)
{
    ALMetalAvatarResources::Key key{};
    std::copy_n(avatar_id.mData, key.size(), key.begin());
    for (const auto* owner :
         { &mMetalWorldSimpleCapture, &mMetalProbeWorldSimpleCapture })
    {
        if (!*owner) continue;
        (*owner)->avatar_resources->erase(key);
    }
    if (mMetalWorldSimpleCapture)
    {
        if (mMetalWorldSimpleCapture->impostor_bake_avatar_id == avatar_id)
        {
            mMetalWorldSimpleCapture->impostor_bake_target.reset();
            mMetalWorldSimpleCapture->impostor_bake_avatar_id.setNull();
            mMetalWorldSimpleCapture->impostor_bake_attempted = false;
            mMetalWorldSimpleCapture->impostor_bake_native_valid = false;
            mMetalWorldSimpleCapture->impostor_bake_native_complete = false;
            mMetalWorldSimpleCapture->impostor_alpha_active = false;
            mMetalWorldSimpleCapture->impostor_alpha_phase = false;
            mMetalWorldSimpleCapture->impostor_fullbright = false;
            mMetalWorldSimpleCapture->impostor_shiny = false;
            mMetalWorldSimpleCapture->impostor_emboss = false;
        }
    }
}

void LLPipeline::captureMetalWorldTreeBatch(LLFace* face,
                                            LLViewerTexture* texture)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete)
    {
        return;
    }
    LLDrawable* drawable = face ? face->getDrawable() : nullptr;
    LLViewerRegion* region = drawable ? drawable->getRegion() : nullptr;
    LLVertexBuffer* buffer = face ? face->getVertexBuffer() : nullptr;
    LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
    if (!region || !buffer || !image ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_NORMAL) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_TEXCOORD0) ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_COLOR) ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->getMetalIndexBuffer() || !image->getMetalTexture() ||
        buffer->getNumVerts() == 0 || buffer->getNumIndices() == 0)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    LLMatrix4a modelview;
    LLMatrix4a inverse_modelview;
    LLMatrix4a modelview_projection;
    if (!buildMetalWorldDrawMatrices(
            &region->mRenderMatrix, modelview, inverse_modelview,
            modelview_projection))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX);
    batch.normal_offset = buffer->getOffset(LLVertexBuffer::TYPE_NORMAL);
    batch.texcoord_offset = buffer->getOffset(LLVertexBuffer::TYPE_TEXCOORD0);
    batch.color_offset = buffer->getOffset(LLVertexBuffer::TYPE_COLOR);
    batch.vertex_count = buffer->getNumVerts();
    batch.indices = buffer->getMetalIndexBuffer();
    batch.index_type = buffer->getIndexStride() == 4
        ? ALMetalIndexType::uint32 : ALMetalIndexType::uint16;
    batch.index_count = buffer->getNumIndices();
    batch.diffuse_textures[0] = image->getMetalTexture();
    batch.texture_count = 1;
    batch.alpha_mask = true;
    batch.use_vertex_color = false;
    batch.alpha_cutoff_bias = false;
    batch.alpha_cutoff = 0.5f;
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    // treeF applies the hero-mirror plane to vary_position in eye space.
    // The shared Metal cutout vertex path derives the same value from this
    // matrix; leaving it zero retains every tree fragment at clip distance 0.
    std::memcpy(batch.modelview, modelview.getF32ptr(),
                sizeof(batch.modelview));

    const F32* inverse = inverse_modelview.getF32ptr();
    const F32* modelview_values = modelview.getF32ptr();
    for (U32 column = 0; column < 3; ++column)
    {
        batch.normal_matrix[column][0] = inverse[0 * 4 + column];
        batch.normal_matrix[column][1] = inverse[1 * 4 + column];
        batch.normal_matrix[column][2] = inverse[2 * 4 + column];
        batch.rigged_normal_matrix[column][0] =
            modelview_values[column * 4 + 0];
        batch.rigged_normal_matrix[column][1] =
            modelview_values[column * 4 + 1];
        batch.rigged_normal_matrix[column][2] =
            modelview_values[column * 4 + 2];
    }
}

static void describe_missing_native_terrain_input(const char* role, U32 slot = 0)
{
    // Asset arrival can fail many views in one frame. Keep diagnostics bounded
    // and name the earliest missing input, without logging asset identities.
    static U32 last_frame = std::numeric_limits<U32>::max();
    if (last_frame == std::numeric_limits<U32>::max() ||
        gFrameCount - last_frame >= 120)
    {
        last_frame = gFrameCount;
        LL_WARNS("Metal") << "Native terrain input unavailable: role=" << role
                          << ", slot=" << slot << LL_ENDL;
    }
}

void LLPipeline::captureMetalWorldTerrainBatch(
    LLFace* face, LLViewerTexture* const* detail_textures,
    LLViewerTexture* alpha_ramp, LLViewerTexture* parcel_overlay,
    F32 detail_scale, const F32* detail_phase, F32 tess_density,
    bool smoothing, bool triplanar, bool hex, F32 triplanar_blend,
    bool tessellation_pinned,
    std::shared_ptr<const ALMetalTerrainFetchedBindings> fetched)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || !capture.terrain)
    {
        return;
    }

    LLDrawable* drawable = face ? face->getDrawable() : nullptr;
    LLVOSurfacePatch* object = drawable
        ? dynamic_cast<LLVOSurfacePatch*>(drawable->getVObj().get()) : nullptr;
    LLSurfacePatch* patch = object ? object->getPatch() : nullptr;
    LLSurface* surface = patch ? patch->getSurface() : nullptr;
    LLViewerRegion* region = surface ? surface->getRegion() : nullptr;
    LLVertexBuffer* buffer = face ? face->getVertexBuffer() : nullptr;
    if (!face || !detail_textures || !alpha_ramp || !detail_phase ||
        !patch || !surface || !region || !buffer ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        face->getGeomCount() != LLVOSurfacePatch::PATCH_CORNERS ||
        face->getGeomIndex() + LLVOSurfacePatch::PATCH_CORNERS >
            buffer->getNumVerts() ||
        !std::isfinite(detail_scale) || detail_scale <= 0.f ||
        !std::isfinite(detail_phase[0]) ||
        !std::isfinite(detail_phase[1]) ||
        !std::isfinite(tess_density) ||
        (!tessellation_pinned && tess_density <= 0.f) ||
        !std::isfinite(triplanar_blend) || triplanar_blend <= 0.f)
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    ALTerrainSurfaceMaps& maps = surface->getSurfaceMaps();
    ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
    batch.terrain = true;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX) +
        static_cast<std::size_t>(face->getGeomIndex()) * sizeof(LLVector4a);
    batch.vertex_count = LLVOSurfacePatch::PATCH_CORNERS;
    batch.texture_count = 4;
    for (U32 texture = 0; texture < batch.texture_count; ++texture)
    {
        LLImageGL* image = detail_textures[texture]
            ? detail_textures[texture]->getGLTexture() : nullptr;
        batch.diffuse_textures[texture] = fetched
            ? fetched->base[texture].nativeTexture()
            : image ? image->getMetalTexture() : nullptr;
        batch.terrain_diffuse_srgb[texture] =
            !fetched || !fetched->base[texture].fallback;
    }
    LLImageGL* ramp_image = alpha_ramp->getGLTexture();
    LLImageGL* overlay_image = parcel_overlay
        ? parcel_overlay->getGLTexture() : nullptr;
    batch.terrain_height_texture = maps.getMetalHeightTexture();
    batch.terrain_composition_texture = maps.getMetalCompositionTexture();
    batch.terrain_texture_owner = fetched;
    batch.terrain_alpha_ramp_texture = fetched
        ? fetched->blend.nativeTexture()
        : ramp_image ? ramp_image->getMetalTexture() : nullptr;
    batch.terrain_parcel_overlay_texture = fetched
        ? fetched->overlay.nativeTexture()
        : overlay_image ? overlay_image->getMetalTexture() : nullptr;
    batch.terrain_blend_wrap = fetched && fetched->blend.fallback;
    batch.terrain_overlay_wrap = fetched && fetched->overlay.fallback;
    batch.terrain_overlay_srgb = !fetched || !fetched->overlay.fallback;
    if (!batch.terrain_height_texture ||
        !batch.terrain_composition_texture ||
        !batch.terrain_alpha_ramp_texture ||
        (parcel_overlay && !batch.terrain_parcel_overlay_texture) ||
        std::any_of(batch.diffuse_textures.begin(),
                    batch.diffuse_textures.begin() + batch.texture_count,
                    [](const ALMetalTexture* texture)
                    {
                        return texture == nullptr;
                    }))
    {
        if (!batch.terrain_height_texture)
            describe_missing_native_terrain_input("generated_height");
        else if (!batch.terrain_composition_texture)
            describe_missing_native_terrain_input("generated_composition");
        else if (!batch.terrain_alpha_ramp_texture)
            describe_missing_native_terrain_input("alpha_ramp");
        else if (parcel_overlay && !batch.terrain_parcel_overlay_texture)
            describe_missing_native_terrain_input("parcel_overlay");
        else for (U32 slot = 0; slot < batch.texture_count; ++slot)
            if (!batch.diffuse_textures[slot])
            {
                describe_missing_native_terrain_input("classic_detail", slot);
                break;
            }
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }

    LLMatrix4a modelview;
    LLMatrix4a inverse_modelview;
    LLMatrix4a modelview_projection;
    if (!buildMetalWorldDrawMatrices(
            &region->mRenderMatrix, modelview, inverse_modelview,
            modelview_projection))
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
        return;
    }
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    const F32* inverse = inverse_modelview.getF32ptr();
    for (U32 column = 0; column < 3; ++column)
    {
        batch.normal_matrix[column][0] = inverse[0 * 4 + column];
        batch.normal_matrix[column][1] = inverse[1 * 4 + column];
        batch.normal_matrix[column][2] = inverse[2 * 4 + column];
    }

    batch.terrain_grid_scale = surface->getMetersPerGrid();
    batch.terrain_region_scale = region->getWidth();
    batch.terrain_detail_scale = detail_scale;
    batch.terrain_detail_phase[0] = detail_phase[0];
    batch.terrain_detail_phase[1] = detail_phase[1];
    batch.terrain_triplanar_blend = triplanar_blend;
    batch.terrain_smoothing = smoothing;
    batch.terrain_triplanar = triplanar;
    batch.terrain_hex = hex;
    batch.terrain_tessellation_pinned = tessellation_pinned;

    if (hex)
    {
        // Match the float lattice scale compiled into both shader families
        // before doing the large-world placement in double precision.
        constexpr F64 hex_grid = static_cast<F64>(3.4641016f);
        const LLVector3d& origin = region->getOriginGlobal();
        const F64 du = detail_scale * origin.mdV[VX] - detail_phase[0];
        const F64 dv = detail_scale * origin.mdV[VY] - detail_phase[1];
        const F64 delta[3][2] = {{du, dv}, {dv, 0.0}, {du, 0.0}};
        for (U32 projection = 0; projection < 3; ++projection)
        {
            const U32 element = projection >> 1;
            const U32 half = (projection & 1) * 2;
            ALHexLattice::place(
                hex_grid, delta[projection][0], delta[projection][1],
                &batch.terrain_hex_base[element][half],
                &batch.terrain_hex_fraction[element][half]);
        }
    }

    const LLVector3& patch_origin = patch->getOriginRegion();
    const F32 patch_size = surface->getGridsPerPatchEdge() *
                           batch.terrain_grid_scale;
    struct TerrainCorner
    {
        F32 x;
        F32 y;
        F32 z;
    };
    const auto corner = [&](F32 x, F32 y)
    {
        const S32 gx = ll_round(x / batch.terrain_grid_scale);
        const S32 gy = ll_round(y / batch.terrain_grid_scale);
        return TerrainCorner{x, y, surface->sampleZ(gx, gy)};
    };
    const std::array<TerrainCorner, 4> corners{{
        corner(patch_origin.mV[VX], patch_origin.mV[VY]),
        corner(patch_origin.mV[VX] + patch_size, patch_origin.mV[VY]),
        corner(patch_origin.mV[VX] + patch_size,
               patch_origin.mV[VY] + patch_size),
        corner(patch_origin.mV[VX], patch_origin.mV[VY] + patch_size),
    }};
    const LLVector3 tessellation_origin =
        LLViewerCamera::getInstance()->getOrigin() -
        region->getOriginAgent();
    const auto edge_level = [&](const TerrainCorner& a,
                                const TerrainCorner& b)
    {
        if (tessellation_pinned)
        {
            return 16.f;
        }
        const F32 dx = b.x - a.x;
        const F32 dy = b.y - a.y;
        const F32 dz = b.z - a.z;
        const F32 length = sqrtf(dx * dx + dy * dy + dz * dz);
        const F32 mx = 0.5f * (a.x + b.x) - tessellation_origin.mV[VX];
        const F32 my = 0.5f * (a.y + b.y) - tessellation_origin.mV[VY];
        const F32 mz = 0.5f * (a.z + b.z) - tessellation_origin.mV[VZ];
        const F32 distance = sqrtf(mx * mx + my * my + mz * mz);
        return llclamp(length * tess_density / llmax(distance, 1.f),
                       1.f, 64.f);
    };
    const std::array<F32, 4> outer{{
        edge_level(corners[0], corners[3]),
        edge_level(corners[0], corners[1]),
        edge_level(corners[1], corners[2]),
        edge_level(corners[3], corners[2]),
    }};
    const std::array<F32, 2> inner{{
        llmax(outer[1], outer[3]),
        llmax(outer[0], outer[2]),
    }};
    for (U32 edge = 0; edge < outer.size(); ++edge)
    {
        batch.terrain_tessellation_factors[edge] =
            ALWaterHeightBake::halfOf(outer[edge]);
    }
    for (U32 inside = 0; inside < inner.size(); ++inside)
    {
        batch.terrain_tessellation_factors[4 + inside] =
            ALWaterHeightBake::halfOf(inner[inside]);
    }
}

void LLPipeline::captureMetalWorldPBRTerrainBatch(
    LLFace* face, LLViewerTexture* const* base_color_textures,
    LLViewerTexture* const* normal_textures,
    LLViewerTexture* const* orm_textures,
    LLViewerTexture* const* emissive_textures,
    LLViewerTexture* blend_texture, LLViewerTexture* parcel_overlay,
    const F32 (*uv_transform)[4], const F32 (*uv_offset)[2],
    const F32 (*normal_axes)[4], const LLColor4* base_color_factors,
    const F32* metallic_factors, const F32* roughness_factors,
    const LLColor3* emissive_colors, const F32* minimum_alphas,
    U32 paint_type, S32 pbr_detail, F32 tess_density,
    bool smoothing, bool triplanar, bool hex, bool flat_normals,
    F32 triplanar_blend, bool tessellation_pinned,
    std::shared_ptr<const ALMetalTerrainFetchedBindings> fetched)
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active ||
        !mMetalWorldSimpleCapture->pass_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.complete || !capture.terrain)
    {
        return;
    }

    const auto fail = [&capture]()
    {
        capture.markIncomplete(__LINE__);
        capture.batches.clear();
    };
    LLDrawable* drawable = face ? face->getDrawable() : nullptr;
    LLVOSurfacePatch* object = drawable
        ? dynamic_cast<LLVOSurfacePatch*>(drawable->getVObj().get()) : nullptr;
    LLSurfacePatch* patch = object ? object->getPatch() : nullptr;
    LLSurface* surface = patch ? patch->getSurface() : nullptr;
    LLViewerRegion* region = surface ? surface->getRegion() : nullptr;
    LLVertexBuffer* buffer = face ? face->getVertexBuffer() : nullptr;
    if (!face || !base_color_textures || !normal_textures ||
        !orm_textures || !emissive_textures || !blend_texture ||
        !uv_transform || !uv_offset || !normal_axes ||
        !base_color_factors || !metallic_factors ||
        !roughness_factors || !emissive_colors || !minimum_alphas ||
        !patch || !surface || !region || !buffer ||
        !buffer->getMetalVertexBuffer() ||
        !buffer->hasDataType(LLVertexBuffer::TYPE_VERTEX) ||
        face->getGeomCount() != LLVOSurfacePatch::PATCH_CORNERS ||
        face->getGeomIndex() + LLVOSurfacePatch::PATCH_CORNERS >
            buffer->getNumVerts() ||
        paint_type >= TERRAIN_PAINT_TYPE_COUNT ||
        pbr_detail < TERRAIN_PBR_DETAIL_MIN ||
        pbr_detail > TERRAIN_PBR_DETAIL_MAX ||
        !std::isfinite(tess_density) ||
        (!tessellation_pinned && tess_density <= 0.f) ||
        !std::isfinite(triplanar_blend) || triplanar_blend <= 0.f)
    {
        fail();
        return;
    }

    const auto metal_texture = [](LLViewerTexture* texture)
        -> ALMetalTexture*
    {
        LLImageGL* image = texture ? texture->getGLTexture() : nullptr;
        return image ? image->getMetalTexture() : nullptr;
    };
    ALTerrainSurfaceMaps& maps = surface->getSurfaceMaps();
    ALMetalWorldSimpleBatch& batch = capture.batches.emplace_back();
    batch.terrain = true;
    batch.terrain_pbr = true;
    batch.vertices = buffer->getMetalVertexBuffer();
    batch.position_offset = buffer->getOffset(LLVertexBuffer::TYPE_VERTEX) +
        static_cast<std::size_t>(face->getGeomIndex()) * sizeof(LLVector4a);
    batch.vertex_count = LLVOSurfacePatch::PATCH_CORNERS;
    batch.texture_count = LLVLComposition::ASSET_COUNT;
    batch.pbr_slot_count = LLVLComposition::ASSET_COUNT;
    for (U32 material = 0; material < batch.texture_count; ++material)
    {
        batch.diffuse_textures[material] = fetched
            ? fetched->base[material].nativeTexture()
            : metal_texture(base_color_textures[material]);
        batch.terrain_diffuse_srgb[material] =
            !fetched || !fetched->base[material].fallback;
        batch.terrain_emissive_srgb[material] =
            !fetched || !fetched->emissive[material].fallback;
        ALMetalWorldPBRSlot& slot = batch.pbrSlots()[material];
        slot.normal_texture = fetched
            ? fetched->normal[material].nativeTexture()
            : metal_texture(normal_textures[material]);
        slot.orm_texture = fetched
            ? fetched->orm[material].nativeTexture()
            : metal_texture(orm_textures[material]);
        slot.emissive_texture = fetched
            ? fetched->emissive[material].nativeTexture()
            : metal_texture(emissive_textures[material]);
        std::memcpy(slot.base_color_factor,
                    base_color_factors[material].mV,
                    sizeof(slot.base_color_factor));
        std::memcpy(slot.emissive_color, emissive_colors[material].mV,
                    sizeof(emissive_colors[material].mV));
        slot.roughness_factor = roughness_factors[material];
        slot.metallic_factor = metallic_factors[material];
        slot.alpha_cutoff = minimum_alphas[material];
        std::memcpy(batch.terrain_uv_transform[material],
                    uv_transform[material],
                    sizeof(batch.terrain_uv_transform[material]));
        std::memcpy(batch.terrain_uv_offset[material],
                    uv_offset[material],
                    sizeof(batch.terrain_uv_offset[material]));
        std::memcpy(batch.terrain_normal_axes[material],
                    normal_axes[material],
                    sizeof(batch.terrain_normal_axes[material]));
        if (!batch.diffuse_textures[material] ||
            !slot.normal_texture || !slot.orm_texture ||
            !slot.emissive_texture)
        {
            describe_missing_native_terrain_input(
                !batch.diffuse_textures[material] ? "pbr_base_color" :
                !slot.normal_texture ? "pbr_normal" :
                !slot.orm_texture ? "pbr_orm" : "pbr_emissive", material);
            fail();
            return;
        }
        batch.alpha_mask = batch.alpha_mask || slot.alpha_cutoff >= 0.f;
    }

    batch.terrain_height_texture = maps.getMetalHeightTexture();
    batch.terrain_composition_texture = maps.getMetalCompositionTexture();
    batch.terrain_texture_owner = fetched;
    const ALMetalTexture* blend = fetched
        ? fetched->blend.nativeTexture() : metal_texture(blend_texture);
    batch.terrain_blend_wrap = fetched && fetched->blend.fallback;
    batch.terrain_overlay_wrap = fetched && fetched->overlay.fallback;
    batch.terrain_overlay_srgb = !fetched || !fetched->overlay.fallback;
    if (paint_type == TERRAIN_PAINT_TYPE_HEIGHTMAP_WITH_NOISE)
    {
        batch.terrain_alpha_ramp_texture = blend;
    }
    else
    {
        batch.terrain_paint_texture = blend;
    }
    batch.terrain_parcel_overlay_texture = fetched
        ? fetched->overlay.nativeTexture() : metal_texture(parcel_overlay);
    if (!batch.terrain_height_texture ||
        !batch.terrain_composition_texture || !blend ||
        (parcel_overlay && !batch.terrain_parcel_overlay_texture))
    {
        describe_missing_native_terrain_input(
            !batch.terrain_height_texture ? "generated_height" :
            !batch.terrain_composition_texture ? "generated_composition" :
            !blend ? "pbr_blend" : "parcel_overlay");
        fail();
        return;
    }

    LLMatrix4a modelview;
    LLMatrix4a inverse_modelview;
    LLMatrix4a modelview_projection;
    if (!buildMetalWorldDrawMatrices(
            &region->mRenderMatrix, modelview, inverse_modelview,
            modelview_projection))
    {
        fail();
        return;
    }
    std::memcpy(batch.modelview_projection,
                modelview_projection.getF32ptr(),
                sizeof(batch.modelview_projection));
    std::memcpy(batch.terrain_modelview, modelview.getF32ptr(),
                sizeof(batch.terrain_modelview));
    const F32* inverse = inverse_modelview.getF32ptr();
    for (U32 column = 0; column < 3; ++column)
    {
        batch.normal_matrix[column][0] = inverse[0 * 4 + column];
        batch.normal_matrix[column][1] = inverse[1 * 4 + column];
        batch.normal_matrix[column][2] = inverse[2 * 4 + column];
    }

    batch.terrain_grid_scale = surface->getMetersPerGrid();
    batch.terrain_region_scale = region->getWidth();
    batch.terrain_triplanar_blend = triplanar_blend;
    batch.terrain_smoothing = smoothing;
    batch.terrain_triplanar = triplanar;
    batch.terrain_hex = hex;
    batch.terrain_flat_normals = flat_normals;
    batch.terrain_pbr_detail = pbr_detail;
    batch.terrain_paint_type = paint_type;
    batch.terrain_tessellation_pinned = tessellation_pinned;

    if (hex)
    {
        constexpr F64 hex_grid = static_cast<F64>(3.4641016f);
        const LLVector3d& origin = region->getOriginGlobal();
        const F64 x = origin.mdV[VX];
        const F64 y = origin.mdV[VY];
        for (U32 material = 0; material < batch.texture_count; ++material)
        {
            const F64 a = uv_transform[material][0];
            const F64 b = uv_transform[material][1];
            const F64 c = uv_transform[material][2];
            const F64 d = uv_transform[material][3];
            const F64 delta[3][2] = {
                {a * x + c * y, b * x + d * y},
                {a * y, b * y},
                {a * x, b * x},
            };
            for (U32 projection = 0; projection < 3; ++projection)
            {
                const U32 element = 2 * material + (projection >> 1);
                const U32 half = (projection & 1) * 2;
                ALHexLattice::place(
                    hex_grid, delta[projection][0], delta[projection][1],
                    &batch.terrain_hex_base[element][half],
                    &batch.terrain_hex_fraction[element][half]);
            }
        }
    }

    const LLVector3& patch_origin = patch->getOriginRegion();
    const F32 patch_size = surface->getGridsPerPatchEdge() *
                           batch.terrain_grid_scale;
    struct TerrainCorner
    {
        F32 x;
        F32 y;
        F32 z;
    };
    const auto corner = [&](F32 x, F32 y)
    {
        const S32 gx = ll_round(x / batch.terrain_grid_scale);
        const S32 gy = ll_round(y / batch.terrain_grid_scale);
        return TerrainCorner{x, y, surface->sampleZ(gx, gy)};
    };
    const std::array<TerrainCorner, 4> corners{{
        corner(patch_origin.mV[VX], patch_origin.mV[VY]),
        corner(patch_origin.mV[VX] + patch_size, patch_origin.mV[VY]),
        corner(patch_origin.mV[VX] + patch_size,
               patch_origin.mV[VY] + patch_size),
        corner(patch_origin.mV[VX], patch_origin.mV[VY] + patch_size),
    }};
    const LLVector3 tessellation_origin =
        LLViewerCamera::getInstance()->getOrigin() -
        region->getOriginAgent();
    const auto edge_level = [&](const TerrainCorner& a,
                                const TerrainCorner& b)
    {
        if (tessellation_pinned)
        {
            return 16.f;
        }
        const F32 dx = b.x - a.x;
        const F32 dy = b.y - a.y;
        const F32 dz = b.z - a.z;
        const F32 length = sqrtf(dx * dx + dy * dy + dz * dz);
        const F32 mx = 0.5f * (a.x + b.x) -
                       tessellation_origin.mV[VX];
        const F32 my = 0.5f * (a.y + b.y) -
                       tessellation_origin.mV[VY];
        const F32 mz = 0.5f * (a.z + b.z) -
                       tessellation_origin.mV[VZ];
        const F32 distance = sqrtf(mx * mx + my * my + mz * mz);
        return llclamp(length * tess_density / llmax(distance, 1.f),
                       1.f, 64.f);
    };
    const std::array<F32, 4> outer{{
        edge_level(corners[0], corners[3]),
        edge_level(corners[0], corners[1]),
        edge_level(corners[1], corners[2]),
        edge_level(corners[3], corners[2]),
    }};
    const std::array<F32, 2> inner{{
        llmax(outer[1], outer[3]),
        llmax(outer[0], outer[2]),
    }};
    for (U32 edge = 0; edge < outer.size(); ++edge)
    {
        batch.terrain_tessellation_factors[edge] =
            ALWaterHeightBake::halfOf(outer[edge]);
    }
    for (U32 inside = 0; inside < inner.size(); ++inside)
    {
        batch.terrain_tessellation_factors[4 + inside] =
            ALWaterHeightBake::halfOf(inner[inside]);
    }
}

void LLPipeline::endMetalWorldGBufferPass()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active)
    {
        return;
    }
    mMetalWorldSimpleCapture->pass_active = false;
    mMetalWorldSimpleCapture->water_exclusion = false;
    mMetalWorldSimpleCapture->legacy_glow = false;
    mMetalWorldSimpleCapture->pbr_glow = false;
    mMetalWorldSimpleCapture->direct_avatar_alpha = false;
    mMetalWorldSimpleCapture->direct_avatar_alpha_state_active = false;
}

void LLPipeline::endMetalWorldGBufferCapture()
{
    if (!mMetalWorldSimpleCapture ||
        !mMetalWorldSimpleCapture->frame_active)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (capture.visibility_capture_active)
    {
        gGL.queries().endVisibilityCapture();
        capture.visibility_capture_active = false;
    }
    const auto settle_visibility_results =
        [&](std::shared_ptr<ALMetalVisibilityResultBatch> results)
    {
        const bool complete_results = results &&
            results->resultCount() == capture.visibility_tickets.size() &&
            capture.visibility_queries.size() ==
                capture.visibility_tickets.size();
        for (std::size_t index = 0;
             index < capture.visibility_tickets.size(); ++index)
        {
            if (!complete_results ||
                !gGL.queries().attachVisibilityResult(
                    capture.visibility_tickets[index], results, index))
            {
                gGL.queries().discard(
                    capture.visibility_tickets[index]);
            }
        }
        capture.visibility_queries.clear();
        capture.visibility_tickets.clear();
    };
    if (capture.visibility_queries.size() !=
        capture.visibility_tickets.size())
    {
        capture.markIncomplete(__LINE__);
    }
    const bool impostor_bake = capture.impostor_bake;
    capture.impostor_bake = false;
    capture.frame_active = false;
    capture.pass_active = false;
    // Original display clears and continues through sky/lighting even when
    // no geometry is accepted. That is valid for the main view as well as a
    // sky-only probe or transparent impostor. Draw count is not a completeness
    // receipt: unsupported/missing producers explicitly invalidate the view.
    if (!capture.complete)
    {
        const std::size_t incomplete_batch_count =
            capture.batches.size();
        settle_visibility_results(nullptr);
        capture.batches.clear();
        capture.avatar_palettes.clear();
        if (impostor_bake)
        {
            capture.impostor_bake_native_valid = false;
            return;
        }
        const U32 failed_frames = ++capture.failed_frames;
        if (failed_frames >= MetalWorldSimpleCapture::max_failed_frames)
        {
            if (capture.world_ui_chain_active &&
                !capture.world_ui_chain_snapshot &&
                !capture.world_ui_chain_debug_color &&
                !capture.world_ui_continuous_unlocked &&
                !capture.world_ui_chain_counted)
            {
                ++capture.world_ui_chain_attempts;
                capture.world_ui_chain_last_attempt_frame = gFrameCount;
                capture.world_ui_chain_counted = true;
            }
            capture.attempted = true;
            LL_WARNS("Metal")
                << "Native world G-buffer probe retained GL after "
                << failed_frames
                << " deferred frames contained incomplete native "
                   "geometry or texture mirrors; first invalidation was "
                   "pipeline.cpp:"
                << capture.first_incomplete_source_line
                << " with " << incomplete_batch_count
                << " batch(es) retained before discard"
                << LL_ENDL;
        }
        return;
    }

    ALMetalWorldGBufferScene scene;
    scene.batches = capture.batches.data();
    scene.batch_count = capture.batches.size();
    scene.visibility_queries = capture.visibility_queries.data();
    scene.visibility_query_count = capture.visibility_queries.size();
    scene.width = capture.width;
    scene.height = capture.height;
    scene.normal_hdr = capture.normal_hdr;
    scene.hdr = capture.hdr;
    scene.reverse_z = capture.reverse_z;
    scene.stamp_opaque_coverage = impostor_bake && !capture.impostor_profile;
    scene.wireframe = capture.wireframe;
    // CPU mechanism tests are positive, while GPU results depend on the
    // workload. Keep this nonpersistent trial control off by default until
    // a controlled viewer comparison establishes an end-to-end benefit.
    static LLCachedControl<bool> join_static_draws(
        gSavedSettings, "RenderMetalJoinStaticDraws", false);
    scene.join_adjacent_static_draws = join_static_draws();
    if (scene.wireframe)
    {
        constexpr F32 gray = 0.5f;
        scene.clear_color[0] = gray;
        scene.clear_color[1] = gray;
        scene.clear_color[2] = gray;
        scene.clear_color[3] = 1.f;
    }
    if (mMetalHeroWorldCaptureActive &&
        mHeroProbeManager.isMirrorPass())
    {
        // Match globalF.glsl's MIRROR_CLIP plane exactly. The Metal producer
        // clips at the rasterizer with a per-vertex eye-space distance,
        // before any G-buffer fragment can hide geometry that GLSL rejects.
        const LLMatrix4a& modelview =
            LLViewerCamera::getCurrent().getModelview();
        LLMatrix4a normal_matrix;
        normal_matrix.setNormalMatrix(modelview);
        const LLVector3& mirror_normal = mHeroProbeManager.mMirrorNormal;
        const LLVector3& mirror_position =
            mHeroProbeManager.mMirrorPosition;
        LLVector4a normal(
            mirror_normal.mV[VX], mirror_normal.mV[VY],
            mirror_normal.mV[VZ], 0.f);
        LLVector4a position(
            mirror_position.mV[VX], mirror_position.mV[VY],
            mirror_position.mV[VZ], 1.f);
        LLVector4a eye_normal;
        LLVector4a eye_position;
        normal_matrix.rotate(normal, eye_normal);
        eye_normal.normalize3();
        modelview.affineTransform(position, eye_position);
        scene.mirror_clip_plane[0] = eye_normal[0];
        scene.mirror_clip_plane[1] = eye_normal[1];
        scene.mirror_clip_plane[2] = eye_normal[2];
        scene.mirror_clip_plane[3] =
            -eye_position.dot3(eye_normal).getF32();
        scene.mirror_clip = true;
    }
    if (impostor_bake)
    {
        std::fill(scene.clear_color, scene.clear_color + 4, 0.f);
    }
    // The retained resource plan already owns the exact G-buffer layout used
    // by the native renderer. Borrow that storage when it is compatible,
    // rather than carrying a conversion-era second full-resolution set. Do
    // not immediately overwrite the same retained set: the prior native
    // transaction may still be in flight, so the pooled target remains the
    // alternate frame/view destination.
    if (!impostor_bake && mRT && mRT->deferredScreen.isComplete() &&
        mRT->deferredScreen.getNumTextures() == 4 &&
        mRT->deferredScreen.getWidth() == scene.width &&
        mRT->deferredScreen.getHeight() == scene.height)
    {
        const ALMetalRenderTarget* retained =
            mRT->deferredScreen.getMetalRenderTarget();
        const ALMetalRenderTargetDescriptor* descriptor = retained
            ? &retained->descriptor() : nullptr;
        const bool exact_layout = descriptor &&
            descriptor->color_attachment_count == 4 &&
            descriptor->colors[0].format ==
                ALMetalPixelFormat::rgba8_unorm_srgb &&
            descriptor->colors[1].format ==
                ALMetalPixelFormat::rgba8_unorm &&
            descriptor->colors[2].format ==
                (scene.normal_hdr ? ALMetalPixelFormat::rgba16_unorm
                                  : ALMetalPixelFormat::rgb10a2_unorm) &&
            descriptor->colors[3].format ==
                (scene.hdr ? ALMetalPixelFormat::rg11b10_float
                           : ALMetalPixelFormat::rgba8_unorm) &&
            descriptor->depth_stencil_format ==
                ALMetalPixelFormat::depth32_float_stencil8;
        const auto* surface = gGL.getMetalPresentationSurface();
        ALMetalRetainedBackground::Lease retained_ui;
        if (surface)
        {
            const auto& info = surface->info();
            retained_ui = capture.ui_background.find({capture.device, surface,
                info.generation, info.width, info.height, scene.reverse_z});
        }
        const bool retained_depth_in_use = exact_layout && retained_ui &&
            retained->depthStencilTexture() &&
            retained_ui->depthTexture()->nativeHandle() ==
                retained->depthStencilTexture()->nativeHandle();
        const bool previous_uses_retained = exact_layout &&
            capture.target && capture.target->colorTexture(0) ==
                retained->colorTexture(0);
        if (exact_layout && !previous_uses_retained && !retained_depth_in_use)
        {
            scene.destination = retained;
        }
    }
    std::string error;
    const bool batch_main_world = !impostor_bake &&
        isMainWorldPass() && mRT == &mMainRT;
    bool command_batch_active = false;
    if (batch_main_world)
    {
        command_batch_active = capture.renderer->beginCommandBatch(
            "Alchemy native world G-buffer and ordered sky", &error);
        if (!command_batch_active)
        {
            LL_WARNS_ONCE("Metal")
                << "Could not begin the optional native world command batch; "
                   "retaining independent command-buffer submission: "
                << error << LL_ENDL;
            error.clear();
        }
    }
    std::shared_ptr<ALMetalVisibilityResultBatch> visibility_results;
    const bool count_native_draws = ALMetalDevice::commandTimingEnabled();
    const U64 native_draws_before = count_native_draws
        ? ALMetalDevice::encodedDrawCallCount() : 0;
    auto target = capture.renderer->render(
        scene, &error, &visibility_results);
    if (target && !impostor_bake)
    {
        if (count_native_draws)
        {
            const U64 native_draws_after = ALMetalDevice::encodedDrawCallCount();
            if (native_draws_after >= native_draws_before)
            {
                describe_metal_gbuffer_draw_encoding(
                    scene, capture.hero_probe_face_capture ? 2 :
                        capture.reflection_probe_face_capture ? 3 : isMainWorldPass() ? 1 : 0,
                    capture.hero_probe_face_capture ? capture.hero_probe_face :
                        capture.reflection_probe_face_capture ? capture.reflection_probe_face : 0,
                    native_draws_after - native_draws_before);
            }
        }
        describe_metal_draw_join_upper_bound(
            scene.batches, scene.batch_count, false,
            capture.hero_probe_face_capture ? 2 :
                capture.reflection_probe_face_capture ? 3 : isMainWorldPass() ? 1 : 0,
            capture.hero_probe_face_capture ? capture.hero_probe_face :
                capture.reflection_probe_face_capture ? capture.reflection_probe_face : 0,
            scene.visibility_query_count);
    }
    if (!target)
    {
        settle_visibility_results(nullptr);
        if (command_batch_active)
        {
            capture.renderer->cancelCommandBatch();
        }
        if (impostor_bake)
        {
            capture.impostor_bake_native_valid = false;
            LL_WARNS("Metal")
                << "Could not encode native opaque avatar-impostor bake: "
                << error << LL_ENDL;
            capture.batches.clear();
            capture.avatar_palettes.clear();
            return;
        }
        if (++capture.failed_frames >=
            MetalWorldSimpleCapture::max_failed_frames)
        {
            if (capture.world_ui_chain_active &&
                !capture.world_ui_chain_snapshot &&
                !capture.world_ui_chain_debug_color &&
                !capture.world_ui_continuous_unlocked &&
                !capture.world_ui_chain_counted)
            {
                ++capture.world_ui_chain_attempts;
                capture.world_ui_chain_last_attempt_frame = gFrameCount;
                capture.world_ui_chain_counted = true;
            }
            capture.attempted = true;
            LL_WARNS("Metal")
                << "Native world G-buffer probe retained GL after "
                << capture.failed_frames << " render failures: "
                << error << LL_ENDL;
        }
    }
    else if (impostor_bake)
    {
        capture.impostor_bake_target = std::move(target);
        capture.impostor_bake_attempted = true;
        LL_DEBUGS("Metal")
            << "Native opaque avatar-impostor bake encoded "
            << capture.batches.size() << " batches at "
            << capture.width << "x" << capture.height
            << "; native forward phases remain transactionally retained"
            << LL_ENDL;
    }
    else
    {
        if (capture.world_ui_chain_active &&
            !capture.world_ui_chain_snapshot &&
            !capture.world_ui_chain_debug_color &&
            !capture.world_ui_continuous_unlocked &&
            !capture.world_ui_chain_counted)
        {
            ++capture.world_ui_chain_attempts;
            capture.world_ui_chain_last_attempt_frame = gFrameCount;
            capture.world_ui_chain_counted = true;
        }
        capture.hdri_sky_native_available = false;
        capture.split_sky_native_available = false;
        capture.windlight_sky_native_available = false;
        capture.windlight_stars_native_available = false;
        capture.windlight_heavenly_bodies_native_available = false;
        capture.windlight_meteors_native_available = false;
        capture.windlight_aurora_native_available = false;
        capture.windlight_clouds_native_available = false;
        if (capture.hdri_sky_complete &&
            !capture.hdri_sky_active &&
            !capture.hdri_sky_batches.empty() &&
            capture.hdri_sky_environment)
        {
            ALMetalWorldHDRISkyScene sky_scene;
            sky_scene.batches = capture.hdri_sky_batches.data();
            sky_scene.batch_count = capture.hdri_sky_batches.size();
            sky_scene.environment_texture =
                capture.hdri_sky_environment;
            std::memcpy(sky_scene.camera_local,
                        capture.hdri_sky_camera_local,
                        sizeof(sky_scene.camera_local));
            std::memcpy(sky_scene.environment_rotation,
                        capture.hdri_sky_environment_rotation,
                        sizeof(sky_scene.environment_rotation));
            sky_scene.exposure_scale =
                capture.hdri_sky_exposure_scale;
            sky_scene.width = capture.width;
            sky_scene.height = capture.height;
            sky_scene.normal_hdr = capture.normal_hdr;
            sky_scene.hdr = capture.hdr;
            sky_scene.reverse_z = capture.reverse_z;
            sky_scene.wireframe = capture.wireframe;
            error.clear();
            capture.hdri_sky_native_available =
                capture.renderer->compositeHDRISky(
                    *target, sky_scene, &error);
            if (!capture.hdri_sky_native_available)
            {
                LL_WARNS("Metal")
                    << "Native world HDRI sky retained clear-depth GL "
                       "authority after composite failure: "
                    << error << LL_ENDL;
            }
        }
        if (!capture.hdri_sky_native_available &&
            capture.split_sky_complete &&
            !capture.split_sky_active &&
            !capture.split_sky_batches.empty() &&
            capture.split_sky_environment &&
            capture.split_sky_rainbow && capture.split_sky_halo)
        {
            ALMetalWorldWindLightSkyScene windlight_scene;
            windlight_scene.batches = capture.split_sky_batches.data();
            windlight_scene.batch_count = capture.split_sky_batches.size();
            windlight_scene.rainbow_texture = capture.split_sky_rainbow;
            windlight_scene.halo_texture = capture.split_sky_halo;
            windlight_scene.constants =
                capture.split_sky_windlight_constants;
            windlight_scene.sky_hdr_scale =
                capture.split_sky_windlight_hdr_scale;
            windlight_scene.width = capture.width;
            windlight_scene.height = capture.height;
            windlight_scene.normal_hdr = capture.normal_hdr;
            windlight_scene.hdr = capture.hdr;
            windlight_scene.reverse_z = capture.reverse_z;
            windlight_scene.wireframe = capture.wireframe;
            error.clear();
            capture.split_sky_native_available =
                capture.renderer->compositeWindLightSky(
                    *target, windlight_scene, &error);

            if (capture.split_sky_native_available)
            {
                ALMetalWorldHDRISkyScene hdri_scene;
                hdri_scene.batches = capture.split_sky_batches.data();
                hdri_scene.batch_count = capture.split_sky_batches.size();
                hdri_scene.environment_texture =
                    capture.split_sky_environment;
                std::memcpy(hdri_scene.camera_local,
                            capture.split_sky_camera_local,
                            sizeof(hdri_scene.camera_local));
                std::memcpy(hdri_scene.environment_rotation,
                            capture.split_sky_environment_rotation,
                            sizeof(hdri_scene.environment_rotation));
                hdri_scene.exposure_scale =
                    capture.split_sky_exposure_scale;
                hdri_scene.horizontal_fraction =
                    capture.split_sky_horizontal_fraction;
                hdri_scene.width = capture.width;
                hdri_scene.height = capture.height;
                hdri_scene.normal_hdr = capture.normal_hdr;
                hdri_scene.hdr = capture.hdr;
                hdri_scene.reverse_z = capture.reverse_z;
                hdri_scene.wireframe = capture.wireframe;
                error.clear();
                capture.split_sky_native_available =
                    capture.renderer->compositeHDRISky(
                        *target, hdri_scene, &error);
            }
            if (!capture.split_sky_native_available)
            {
                LL_WARNS("Metal")
                    << "Native partial-HDRI sky retained clear-depth GL "
                       "authority after composite failure"
                    << (error.empty() ? "" : ": ") << error
                    << LL_ENDL;
            }
        }
        if (!capture.hdri_sky_native_available &&
            !capture.split_sky_native_available &&
            capture.windlight_sky_complete &&
            !capture.windlight_sky_active &&
            !capture.windlight_sky_batches.empty() &&
            capture.windlight_sky_rainbow &&
            capture.windlight_sky_halo)
        {
            ALMetalWorldWindLightSkyScene sky_scene;
            sky_scene.batches = capture.windlight_sky_batches.data();
            sky_scene.batch_count = capture.windlight_sky_batches.size();
            sky_scene.rainbow_texture = capture.windlight_sky_rainbow;
            sky_scene.halo_texture = capture.windlight_sky_halo;
            sky_scene.constants = capture.windlight_sky_constants;
            sky_scene.sky_hdr_scale = capture.windlight_sky_hdr_scale;
            sky_scene.width = capture.width;
            sky_scene.height = capture.height;
            sky_scene.normal_hdr = capture.normal_hdr;
            sky_scene.hdr = capture.hdr;
            sky_scene.reverse_z = capture.reverse_z;
            sky_scene.wireframe = capture.wireframe;
            error.clear();
            capture.windlight_sky_native_available =
                capture.renderer->compositeWindLightSky(
                    *target, sky_scene, &error);
            if (!capture.windlight_sky_native_available)
            {
                LL_WARNS("Metal")
                    << "Native WindLight atmospheric sky retained "
                       "clear-depth GL authority after composite failure: "
                    << error << LL_ENDL;
            }
            else if (capture.windlight_sky_behind_requested)
            {
                error.clear();
                capture.sky_behind_target =
                    capture.renderer->renderWindLightSkyBehind(
                        sky_scene, &error);
                if (!capture.sky_behind_target)
                {
                    LL_WARNS("Metal")
                        << "Native WindLight sky-behind mirror was not "
                           "available for the later atmospheric pass: "
                        << error << LL_ENDL;
                }
            }
        }
        if (capture.windlight_sky_native_available &&
            capture.windlight_stars_expected)
        {
            if (capture.windlight_stars_complete &&
                !capture.windlight_stars_active &&
                capture.windlight_star_batch.vertices)
            {
                ALMetalWorldStarScene star_scene;
                star_scene.batches = &capture.windlight_star_batch;
                star_scene.batch_count = 1;
                star_scene.moon_texture = capture.windlight_star_moon;
                star_scene.star_alpha = capture.windlight_star_alpha;
                star_scene.time = capture.windlight_star_time;
                std::memcpy(star_scene.moon_direction,
                            capture.windlight_star_moon_direction,
                            sizeof(star_scene.moon_direction));
                std::memcpy(star_scene.moon_quad_center,
                            capture.windlight_star_moon_quad_center,
                            sizeof(star_scene.moon_quad_center));
                std::memcpy(star_scene.moon_quad_u,
                            capture.windlight_star_moon_quad_u,
                            sizeof(star_scene.moon_quad_u));
                std::memcpy(star_scene.moon_quad_v,
                            capture.windlight_star_moon_quad_v,
                            sizeof(star_scene.moon_quad_v));
                star_scene.moon_brightness =
                    capture.windlight_star_moon_brightness;
                star_scene.width = capture.width;
                star_scene.height = capture.height;
                star_scene.moon_mask =
                    capture.windlight_stars_moon_mask;
                star_scene.normal_hdr = capture.normal_hdr;
                star_scene.hdr = capture.hdr;
                star_scene.reverse_z = capture.reverse_z;
                star_scene.wireframe = capture.wireframe;
                error.clear();
                capture.windlight_stars_native_available =
                    capture.renderer->compositeWindLightStars(
                        *target, star_scene, &error);
            }
            if (!capture.windlight_stars_native_available)
            {
                capture.windlight_sky_native_available = false;
                LL_WARNS("Metal")
                    << "Native WindLight sky retained GL authority because "
                       "its expected star layer was incomplete"
                    << (error.empty() ? "" : ": ") << error
                    << LL_ENDL;
            }
        }
        if (capture.windlight_sky_native_available &&
            capture.windlight_heavenly_bodies_expected)
        {
            if (capture.windlight_heavenly_bodies_complete &&
                !capture.windlight_heavenly_bodies_active &&
                !capture.windlight_heavenly_body_batches.empty())
            {
                ALMetalWorldHeavenlyBodyScene body_scene;
                body_scene.batches =
                    capture.windlight_heavenly_body_batches.data();
                body_scene.batch_count =
                    capture.windlight_heavenly_body_batches.size();
                body_scene.width = capture.width;
                body_scene.height = capture.height;
                body_scene.normal_hdr = capture.normal_hdr;
                body_scene.hdr = capture.hdr;
                body_scene.reverse_z = capture.reverse_z;
                body_scene.wireframe = capture.wireframe;
                error.clear();
                capture.windlight_heavenly_bodies_native_available =
                    capture.renderer->compositeWindLightHeavenlyBodies(
                        *target, body_scene, &error);
            }
            if (!capture.windlight_heavenly_bodies_native_available)
            {
                capture.windlight_sky_native_available = false;
                LL_WARNS("Metal")
                    << "Native WindLight sky retained GL authority because "
                       "its expected sun/moon layer was incomplete"
                    << (error.empty() ? "" : ": ") << error
                    << LL_ENDL;
            }
        }
        if (capture.windlight_sky_native_available &&
            capture.windlight_meteors_expected)
        {
            if (capture.windlight_meteors_complete &&
                !capture.windlight_meteors_active &&
                capture.windlight_meteor_batch.vertices)
            {
                ALMetalWorldMeteorScene meteor_scene;
                meteor_scene.batches = &capture.windlight_meteor_batch;
                meteor_scene.batch_count = 1;
                meteor_scene.width_pixels =
                    capture.windlight_meteor_width_pixels;
                meteor_scene.width = capture.width;
                meteor_scene.height = capture.height;
                meteor_scene.normal_hdr = capture.normal_hdr;
                meteor_scene.hdr = capture.hdr;
                meteor_scene.reverse_z = capture.reverse_z;
                meteor_scene.wireframe = capture.wireframe;
                error.clear();
                capture.windlight_meteors_native_available =
                    capture.renderer->compositeWindLightMeteors(
                        *target, meteor_scene, &error);
            }
            if (!capture.windlight_meteors_native_available)
            {
                capture.windlight_sky_native_available = false;
                LL_WARNS("Metal")
                    << "Native WindLight sky retained GL authority because "
                       "its expected meteor layer was incomplete"
                    << (error.empty() ? "" : ": ") << error
                    << LL_ENDL;
            }
        }
        if (capture.windlight_sky_native_available &&
            capture.windlight_aurora_expected)
        {
            if (capture.windlight_aurora_complete &&
                !capture.windlight_aurora_active &&
                !capture.windlight_aurora_batches.empty())
            {
                ALMetalWorldAuroraScene aurora_scene;
                aurora_scene.batches =
                    capture.windlight_aurora_batches.data();
                aurora_scene.batch_count =
                    capture.windlight_aurora_batches.size();
                std::memcpy(aurora_scene.camera_local,
                            capture.windlight_aurora_camera_local,
                            sizeof(aurora_scene.camera_local));
                aurora_scene.intensity =
                    capture.windlight_aurora_intensity;
                aurora_scene.time = capture.windlight_aurora_time;
                aurora_scene.width = capture.width;
                aurora_scene.height = capture.height;
                aurora_scene.normal_hdr = capture.normal_hdr;
                aurora_scene.hdr = capture.hdr;
                aurora_scene.reverse_z = capture.reverse_z;
                aurora_scene.wireframe = capture.wireframe;
                error.clear();
                capture.windlight_aurora_native_available =
                    capture.renderer->compositeWindLightAurora(
                        *target, aurora_scene, &error);
            }
            if (!capture.windlight_aurora_native_available)
            {
                capture.windlight_sky_native_available = false;
                LL_WARNS("Metal")
                    << "Native WindLight sky retained GL authority because "
                       "its expected aurora layer was incomplete"
                    << (error.empty() ? "" : ": ") << error
                    << LL_ENDL;
            }
        }
        if (capture.windlight_sky_native_available &&
            capture.windlight_clouds_expected)
        {
            if (capture.windlight_clouds_complete &&
                !capture.windlight_clouds_active &&
                !capture.windlight_cloud_batches.empty() &&
                capture.windlight_cloud_noise &&
                capture.windlight_cloud_noise_next)
            {
                ALMetalWorldCloudScene cloud_scene;
                cloud_scene.batches =
                    capture.windlight_cloud_batches.data();
                cloud_scene.batch_count =
                    capture.windlight_cloud_batches.size();
                cloud_scene.noise_texture =
                    capture.windlight_cloud_noise;
                cloud_scene.next_noise_texture =
                    capture.windlight_cloud_noise_next;
                cloud_scene.constants =
                    capture.windlight_cloud_constants;
                cloud_scene.width = capture.width;
                cloud_scene.height = capture.height;
                cloud_scene.normal_hdr = capture.normal_hdr;
                cloud_scene.hdr = capture.hdr;
                cloud_scene.reverse_z = capture.reverse_z;
                cloud_scene.wireframe = capture.wireframe;
                error.clear();
                capture.windlight_clouds_native_available =
                    capture.renderer->compositeWindLightClouds(
                        *target, cloud_scene, &error);
            }
            if (!capture.windlight_clouds_native_available)
            {
                capture.windlight_sky_native_available = false;
                LL_WARNS("Metal")
                    << "Native WindLight sky retained GL authority because "
                       "its expected cloud layer was incomplete"
                    << (error.empty() ? "" : ": ") << error
                    << LL_ENDL;
            }
        }
        if (command_batch_active)
        {
            error.clear();
            if (!capture.renderer->commitCommandBatch(&error))
            {
                target.reset();
                const U32 failed_frames = ++capture.failed_frames;
                if (failed_frames == MetalWorldSimpleCapture::max_failed_frames)
                {
                    LL_WARNS("Metal")
                        << "Native world G-buffer/sky batch retained GL after "
                        << failed_frames << " commit failures: "
                        << error << LL_ENDL;
                }
            }
        }
        settle_visibility_results(
            target ? std::move(visibility_results) : nullptr);
        if (target)
        {
            capture.target = std::move(target);
            capture.attempted = true;
            capture.failed_frames = 0;
            if (!capture.continuous_world_capture &&
                !capture.world_ui_continuous_unlocked)
            {
                LL_DEBUGS("Metal")
                    << "Native world G-buffer owner encoded "
                    << capture.batches.size()
                    << " world batches at " << capture.width << "x"
                    << capture.height
                    << (capture.hdri_sky_native_available
                            ? "; full HDRI sky is native"
                            : capture.split_sky_native_available
                                ? "; partial HDRI/WindLight sky split is native"
                            : capture.windlight_sky_native_available
                                ? capture.windlight_clouds_expected
                                    ? "; full WindLight sky and clouds are native"
                                    : capture.windlight_aurora_expected
                                        ? "; WindLight haze through aurora are native"
                                    : capture.windlight_meteors_expected
                                        ? "; WindLight haze, stars, heavenly bodies and meteors are native"
                                    : capture.windlight_heavenly_bodies_expected
                                        ? "; WindLight haze, stars and heavenly bodies are native"
                                    : capture.windlight_stars_expected
                                        ? "; WindLight haze and stars are native"
                                        : "; WindLight atmospheric haze sky is native"
                                : "; sky remains GL-owned")
                    << "; publication still requires the complete native world transaction"
                    << LL_ENDL;
            }
        }
    }
    capture.batches.clear();
    capture.hdri_sky_batches.clear();
    capture.hdri_sky_environment = nullptr;
    capture.hdri_sky_active = false;
    capture.hdri_sky_complete = false;
    capture.split_sky_batches.clear();
    capture.split_sky_environment = nullptr;
    capture.split_sky_rainbow = nullptr;
    capture.split_sky_halo = nullptr;
    capture.split_sky_exposure_scale = 1.f;
    capture.split_sky_horizontal_fraction = 0.f;
    capture.split_sky_windlight_constants = {};
    capture.split_sky_active = false;
    capture.split_sky_complete = false;
    capture.windlight_sky_batches.clear();
    capture.windlight_sky_rainbow = nullptr;
    capture.windlight_sky_halo = nullptr;
    capture.windlight_sky_active = false;
    capture.windlight_sky_complete = false;
    capture.windlight_star_batch = {};
    capture.windlight_star_moon = nullptr;
    capture.windlight_stars_expected = false;
    capture.windlight_stars_active = false;
    capture.windlight_stars_complete = false;
    capture.windlight_stars_moon_mask = false;
    capture.windlight_heavenly_body_batches.clear();
    capture.windlight_heavenly_bodies_expected = false;
    capture.windlight_heavenly_bodies_active = false;
    capture.windlight_heavenly_bodies_complete = false;
    capture.windlight_meteor_batch = {};
    capture.windlight_meteor_width_pixels = 0.f;
    capture.windlight_meteors_expected = false;
    capture.windlight_meteors_active = false;
    capture.windlight_meteors_complete = false;
    capture.windlight_aurora_batches.clear();
    capture.windlight_aurora_intensity = 0.f;
    capture.windlight_aurora_time = 0.f;
    capture.windlight_aurora_expected = false;
    capture.windlight_aurora_active = false;
    capture.windlight_aurora_complete = false;
    capture.windlight_cloud_batches.clear();
    capture.windlight_cloud_noise = nullptr;
    capture.windlight_cloud_noise_next = nullptr;
    capture.windlight_cloud_constants = {};
    capture.windlight_clouds_expected = false;
    capture.windlight_clouds_active = false;
    capture.windlight_clouds_complete = false;
    capture.avatar_palettes.clear();
}

void LLPipeline::renderMetalWorldLocalLights(
    LLViewerCamera& camera, const LLMatrix4a& modelview,
    F32 light_scale, S32 local_light_count)
{
    if (!isMetalWorldCapturePass() ||
        (!mMetalHeroWorldCaptureActive &&
         !mMetalReflectionWorldCaptureActive && mRT != &mMainRT) ||
        !mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device || !capture.renderer || !capture.target ||
        !capture.base_light_target ||
        capture.local_lighting_attempted)
    {
        return;
    }

    std::vector<ALMetalWorldLocalLight> bounded_lights;
    std::vector<ALMetalWorldLocalLight> fullscreen_lights;
    const std::size_t light_capacity = std::min<std::size_t>(
        static_cast<std::size_t>(std::max(local_light_count, 0)),
        mNearbyLights.size());
    bounded_lights.reserve(light_capacity);
    fullscreen_lights.reserve(light_capacity);
    const LLVector3& camera_origin = camera.getOrigin();
    const ALMetalRenderTargetDescriptor& target_descriptor =
        capture.target->descriptor();
    S32 count = 0;
    for (light_set_t::iterator iter = mNearbyLights.begin();
         iter != mNearbyLights.end(); ++iter)
    {
        ++count;
        if (count > local_light_count)
        {
            break;
        }

        LLDrawable* drawable = iter->drawable;
        LLVOVolume* volume = drawable ? drawable->getVOVolume() : nullptr;
        if (!volume || (volume->isAttachment() && !sRenderAttachedLights))
        {
            continue;
        }

        LLVector4a center;
        center.load3(drawable->getPositionAgent().mV);
        const F32 radius = volume->getLightRadius() * 1.5f;
        LLColor3 color = volume->getLightLinearColor() * light_scale;
        color *= light_fade_brightness(iter->fade);
        if (color.magVecSquared() < 0.001f || radius <= 0.001f)
        {
            continue;
        }

        LLVector4a extent;
        extent.splat(radius);
        if (camera.AABBInFrustumNoFarClip(center, extent) == 0 ||
            volume->isLightSpotlight())
        {
            // Projectors own cookie, ambiance and optional spot-shadow
            // semantics and remain a separate downstream migration pass.
            continue;
        }

        LLVector4a eye_center;
        modelview.affineTransform(center, eye_center);
        ALMetalWorldLocalLight light;
        light.position_radius[0] = eye_center[0];
        light.position_radius[1] = eye_center[1];
        light.position_radius[2] = eye_center[2];
        light.position_radius[3] = radius;
        light.color_falloff[0] = color.mV[0];
        light.color_falloff[1] = color.mV[1];
        light.color_falloff[2] = color.mV[2];
        light.color_falloff[3] =
            volume->getLightFalloff(DEFERRED_LIGHT_FALLOFF);
        const F32* world_center = center.getF32ptr();
        const bool camera_outside =
            camera_origin.mV[0] > world_center[0] + radius + 0.2f ||
            camera_origin.mV[0] < world_center[0] - radius - 0.2f ||
            camera_origin.mV[1] > world_center[1] + radius + 0.2f ||
            camera_origin.mV[1] < world_center[1] - radius - 0.2f ||
            camera_origin.mV[2] > world_center[2] + radius + 0.2f ||
            camera_origin.mV[2] < world_center[2] - radius - 0.2f;
        if (camera_outside)
        {
            setMetalLightScreenRect(
                light.position_radius, light.screen_rect,
                camera.getProjection(), target_descriptor.width,
                target_descriptor.height);
            bounded_lights.push_back(light);
        }
        else
        {
            fullscreen_lights.push_back(light);
        }
    }

    std::vector<ALMetalWorldLocalLight> lights = std::move(bounded_lights);
    const std::size_t bounded_light_count = lights.size();
    lights.insert(
        lights.end(), fullscreen_lights.begin(), fullscreen_lights.end());

    ALMetalWorldLocalLightingScene scene;
    scene.gbuffer = capture.target.get();
    scene.lights = lights.empty() ? nullptr : lights.data();
    scene.light_count = lights.size();
    scene.bounded_light_count = bounded_light_count;
    LLMatrix4a inverse_projection;
    inverse_projection.setInverse(camera.getProjection());
    std::memcpy(scene.inverse_projection,
                inverse_projection.getF32ptr(),
                sizeof(scene.inverse_projection));
    scene.specular_exponent = mDeferredUBOData.specular_exponent;
    scene.reverse_z = capture.reverse_z;
    scene.hdr = capture.hdr;
    scene.classic_mode = LLRender::sClassicMode;

    std::string error;
    if (!capture.renderer->accumulateLocalLights(
            *capture.base_light_target, scene, &error))
    {
        if (++capture.local_lighting_failed_frames >=
            MetalWorldSimpleCapture::max_failed_frames)
        {
            capture.local_lighting_attempted = true;
            LL_WARNS("Metal")
                << "Native world local-point-light owner left the native frame incomplete after "
                << capture.local_lighting_failed_frames
                << " failures: " << error << LL_ENDL;
        }
        return;
    }

    capture.local_lighting_attempted = true;
    capture.local_lighting_failed_frames = 0;
    if (!capture.continuous_world_capture &&
        !capture.world_ui_continuous_unlocked)
    {
        LL_DEBUGS("Metal")
            << "Native world local-point-light owner encoded "
            << bounded_light_count << " bounded and "
            << lights.size() - bounded_light_count
            << " camera-inside ordinary lights at "
            << capture.base_light_target->descriptor().width << "x"
            << capture.base_light_target->descriptor().height
            << "; accumulated in place after native base lighting"
            << LL_ENDL;
    }
}

void LLPipeline::renderMetalWorldProjectorLights(
    LLViewerCamera& camera, const LLMatrix4a& modelview,
    F32 light_scale, S32 local_light_count)
{
    if (!isMetalWorldCapturePass() ||
        (!mMetalHeroWorldCaptureActive &&
         !mMetalReflectionWorldCaptureActive && mRT != &mMainRT) ||
        !mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device || !capture.renderer || !capture.target ||
        !capture.base_light_target ||
        capture.projector_lighting_attempted)
    {
        return;
    }

    std::vector<ALMetalWorldProjectorLight> lights;
    lights.reserve(std::min<std::size_t>(
        static_cast<std::size_t>(std::max(local_light_count, 0)),
        mNearbyLights.size()));
    const U32 unbuilt_projector_shadows =
        (unbuiltShadowMaps() >> 4u) & 0x3u;
    bool needs_projector_shadows = false;
    S32 count = 0;
    for (light_set_t::iterator iter = mNearbyLights.begin();
         iter != mNearbyLights.end(); ++iter)
    {
        ++count;
        if (count > local_light_count)
        {
            break;
        }

        LLDrawable* drawable = iter->drawable;
        LLVOVolume* volume = drawable ? drawable->getVOVolume() : nullptr;
        if (!volume || !volume->isLightSpotlight() ||
            (volume->isAttachment() && !sRenderAttachedLights))
        {
            continue;
        }

        LLVector4a center;
        center.load3(drawable->getPositionAgent().mV);
        const F32 radius = volume->getLightRadius() * 1.5f;
        LLColor3 color = volume->getLightLinearColor() * light_scale;
        color *= light_fade_brightness(iter->fade);
        if (color.magVecSquared() < 0.001f || radius <= 0.001f)
        {
            continue;
        }

        LLVector4a extent;
        extent.splat(radius);
        if (camera.AABBInFrustumNoFarClip(center, extent) == 0)
        {
            continue;
        }

        LLViewerTexture* cookie = volume->getLightTexture();
        if (!cookie)
        {
            cookie = LLViewerFetchedTexture::sWhiteImagep.get();
        }
        LLImageGL* cookie_image = cookie ? cookie->getGLTexture() : nullptr;
        if (!cookie_image || !cookie_image->getMetalTexture())
        {
            // The ordinary texture path substitutes the viewer default image
            // when a fetched projector cookie has not published GPU storage
            // yet. Use that same durable image for the native replay so an
            // unavailable cookie does not stall the whole world transaction.
            LLViewerFetchedTexture* fallback =
                LLViewerFetchedTexture::sDefaultImagep.get();
            LLImageGL* fallback_image = fallback
                ? fallback->getGLTexture() : nullptr;
            if (fallback_image && fallback_image->getMetalTexture())
            {
                cookie_image = fallback_image;
            }
        }
        ALMetalTexture* cookie_texture = cookie_image
            ? cookie_image->getMetalTexture() : nullptr;
        if (!cookie_texture)
        {
            // A fetched cookie can arrive after the light itself. Publishing
            // a partial accumulation would make the migration target lie;
            // leave the probe armed and retry when its durable mirror exists.
            return;
        }

        const LLVector3 parameters = volume->getSpotLightParams();
        const F32 fov = parameters.mV[0];
        const F32 focus = parameters.mV[1];
        const LLVector3 position = drawable->getPositionAgent();
        const LLQuaternion rotation = volume->getRenderRotation();
        const LLVector3 scale = volume->getScale();
        if (!std::isfinite(fov) || !std::isfinite(focus) ||
            fov <= 0.f || scale.mV[VX] <= 0.f ||
            scale.mV[VY] <= 0.f)
        {
            return;
        }

        LLVector3 at_axis(0.f, 0.f, -scale.mV[VZ] * 0.5f);
        at_axis *= rotation;
        const LLVector3 near_point = position + at_axis;
        at_axis.normVec();
        const F32 distance =
            (scale.mV[VY] * 0.5f) / tanf(fov * 0.5f);
        const LLVector3 origin = near_point - at_axis * distance;
        LLMatrix4 light_matrix(rotation, LLVector4(origin, 1.f));
        LLMatrix4a light_to_eye;
        light_to_eye.setMul(LLMatrix4a(light_matrix), modelview);
        LLMatrix4a eye_to_light;
        eye_to_light.setInverse(light_to_eye);

        const F32 near_clip = distance;
        const F32 far_clip = radius + distance - scale.mV[VZ];
        const F32 projector_range = far_clip - near_clip;
        if (!std::isfinite(distance) || near_clip <= 0.f ||
            far_clip <= near_clip || !std::isfinite(projector_range))
        {
            return;
        }

        LLVector4a plane_point;
        LLVector4a direction_point;
        LLVector4a eye_origin;
        light_to_eye.affineTransform(
            LLVector4a(0.f, 0.f, -(near_clip + 0.01f), 1.f),
            plane_point);
        light_to_eye.affineTransform(
            LLVector4a(0.f, 0.f, -(near_clip + 1.f), 1.f),
            direction_point);
        light_to_eye.affineTransform(
            LLVector4a(0.f, 0.f, 0.f, 1.f), eye_origin);
        LLVector4a plane_normal;
        plane_normal.setSub(direction_point, plane_point);
        plane_normal.normalize3();

        // The retired GL projector setup used this exact forward cookie matrix;
        // projection even when the scene depth is reverse-Z. Keep this
        // byte-for-byte construction paired with its [-1,1] z remap.
        eye_to_light.setMul(
            eye_to_light,
            LLMatrix4a::perspective(
                fov, scale.mV[VX] / scale.mV[VY],
                near_clip, far_clip));
        LLMatrix4a clip_to_cookie;
        clip_to_cookie.mMatrix[0].set(0.5f, 0.f, 0.f, 0.f);
        clip_to_cookie.mMatrix[1].set(0.f, 0.5f, 0.f, 0.f);
        clip_to_cookie.mMatrix[2].set(0.f, 0.f, 0.5f, 0.f);
        clip_to_cookie.mMatrix[3].set(0.5f, 0.5f, 0.5f, 1.f);
        eye_to_light.setMul(eye_to_light, clip_to_cookie);

        LLVector4a eye_center;
        modelview.affineTransform(center, eye_center);
        ALMetalWorldProjectorLight light;
        light.cookie_texture = cookie_texture;
        light.position_radius[0] = eye_center[0];
        light.position_radius[1] = eye_center[1];
        light.position_radius[2] = eye_center[2];
        light.position_radius[3] = radius;
        light.color_falloff[0] = color.mV[0];
        light.color_falloff[1] = color.mV[1];
        light.color_falloff[2] = color.mV[2];
        light.color_falloff[3] =
            volume->getLightFalloff(DEFERRED_LIGHT_FALLOFF);
        std::memcpy(light.projector_matrix, eye_to_light.getF32ptr(),
                    sizeof(light.projector_matrix));
        std::memcpy(light.projector_plane, plane_point.getF32ptr(),
                    sizeof(F32) * 3);
        light.projector_plane[3] = parameters.mV[2];
        std::memcpy(light.projector_normal, plane_normal.getF32ptr(),
                    sizeof(F32) * 3);
        light.projector_normal[3] = projector_range;
        std::memcpy(light.projector_origin, eye_origin.getF32ptr(),
                    sizeof(F32) * 3);
        light.projector_origin[3] = focus;
        light.sampling[0] = llmax(
            logf(static_cast<F32>(cookie->getWidth())) / logf(2.f),
            1.f);
        for (S32 shadow = 0; shadow < 2; ++shadow)
        {
            if (mShadowSpotLight[shadow] == drawable &&
                (unbuilt_projector_shadows & (1u << shadow)) == 0)
            {
                light.shadow_channel = shadow;
                light.sampling[1] = 1.f - mSpotLightFade[shadow];
                needs_projector_shadows = true;
                break;
            }
        }
        setMetalLightScreenRect(
            light.position_radius, light.screen_rect,
            camera.getProjection(), capture.target->descriptor().width,
            capture.target->descriptor().height);
        lights.push_back(light);
    }

    if (needs_projector_shadows && !fillMetalWorldProjectorShadows())
    {
        return;
    }

    ALMetalWorldProjectorLightingScene scene;
    scene.gbuffer = capture.target.get();
    scene.lights = lights.empty() ? nullptr : lights.data();
    scene.light_count = lights.size();
    scene.projector_shadows = needs_projector_shadows
        ? &capture.projector_shadows : nullptr;
    LLMatrix4a inverse_projection;
    inverse_projection.setInverse(camera.getProjection());
    std::memcpy(scene.inverse_projection,
                inverse_projection.getF32ptr(),
                sizeof(scene.inverse_projection));
    scene.specular_exponent = mDeferredUBOData.specular_exponent;
    scene.reverse_z = capture.reverse_z;
    scene.hdr = capture.hdr;
    scene.normal_hdr = capture.normal_hdr;
    scene.classic_mode = LLRender::sClassicMode;

    std::string error;
    if (!capture.renderer->accumulateProjectorLights(
            *capture.base_light_target, scene, &error))
    {
        // The raw maps and selected shadow-owning lights are one frame's
        // transaction. A retry must capture both again rather than combine
        // a later light list with stale spot-map contents or matrices.
        capture.projector_shadows = {};
        capture.projector_shadow_frame = std::numeric_limits<U32>::max();
        const U32 failed_frames =
            ++capture.projector_lighting_failed_frames;
        if (failed_frames >= MetalWorldSimpleCapture::max_failed_frames)
        {
            capture.projector_lighting_attempted = true;
            if (failed_frames == MetalWorldSimpleCapture::max_failed_frames)
            {
                LL_WARNS("Metal")
                    << "Native world projector-light owner left the native frame incomplete after "
                    << failed_frames << " failures: " << error << LL_ENDL;
            }
        }
        return;
    }

    capture.projector_lighting_attempted = true;
    capture.projector_lighting_failed_frames = 0;
    if (!capture.continuous_world_capture &&
        !capture.world_ui_continuous_unlocked)
    {
        LL_DEBUGS("Metal")
            << "Native world projector-light owner encoded "
            << lights.size() << " cookies at "
            << capture.base_light_target->descriptor().width << "x"
            << capture.base_light_target->descriptor().height
            << (needs_projector_shadows
                    ? "; exact native spot-shadow filtering consumes "
                      "direct Metal depth slices"
                    : "; no live spot-shadow channel was consumed")
            << LL_ENDL;
    }
}

void LLPipeline::renderMetalWorldLightingComposition()
{
    if (!isMetalWorldCapturePass() ||
        (!mMetalHeroWorldCaptureActive &&
         !mMetalReflectionWorldCaptureActive && mRT != &mMainRT) ||
        !mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device || !capture.renderer ||
        !capture.base_light_target ||
        !capture.local_lighting_attempted ||
        capture.local_lighting_failed_frames != 0 ||
        !capture.projector_lighting_attempted ||
        capture.projector_lighting_failed_frames != 0 ||
        capture.lighting_composition_attempted)
    {
        return;
    }

    // Base, ordinary and projector lighting now share one carried-depth
    // owner. Transfer it into the historical composed slot so every
    // downstream post-deferred transaction keeps the same fail-closed
    // readiness contract without allocating or drawing a composition pass.
    capture.composed_light_target = std::move(capture.base_light_target);
    capture.lighting_composition_attempted = true;
    capture.lighting_composition_failed_frames = 0;
    if (!capture.continuous_world_capture &&
        !capture.world_ui_continuous_unlocked)
    {
        LL_DEBUGS("Metal")
            << "Native world base, ordinary-light and projector-light "
               "owner accumulated in place at "
            << capture.composed_light_target->descriptor().width << "x"
            << capture.composed_light_target->descriptor().height
            << "; no intermediate light targets or composition draw were "
               "created, and native presentation remains fail-closed"
            << LL_ENDL;
    }
}

bool LLPipeline::renderMetalWorldLightMap(
    LLViewerCamera& camera, bool has_sun_shadow, bool has_ssao)
{
    if (!isMetalWorldCapturePass() ||
        (!mMetalHeroWorldCaptureActive &&
         !mMetalReflectionWorldCaptureActive && mRT != &mMainRT) ||
        !mMetalWorldSimpleCapture)
    {
        return false;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device || !capture.renderer || !capture.target ||
        capture.base_lighting_attempted)
    {
        return false;
    }
    if (capture.base_light_map_target)
    {
        return true;
    }

    ALMetalWorldReflectionProbes ready_probes;
    const ALMetalTexture* legacy_environment = nullptr;
    if (sReflectionProbesEnabled)
    {
        if (!mReflectionMapManager.fillMetalReflectionProbes(
                ready_probes) ||
            !ready_probes.irradiance_texture)
        {
            // A newly-enabled probe pack has no published irradiance yet,
            // while its first offscreen face needs base lighting before it
            // can become that publication. Break only that circular
            // bootstrap with the already-native legacy sky cube. The main
            // world remains fail-closed until a coherent probe pack exists.
            if (!isMetalProbeFaceCaptureActive())
            {
                LL_WARNS_ONCE("Metal")
                    << "Native main-world light-map capture is waiting for "
                       "a coherent reflection-probe radiance/SH pair"
                    << LL_ENDL;
                return false;
            }
            LLCubeMap* cube_map =
                gSky.mVOSkyp ? gSky.mVOSkyp->getCubeMap() : nullptr;
            std::string environment_error;
            legacy_environment = cube_map
                ? cube_map->getMetalTexture(&environment_error) : nullptr;
            if (!legacy_environment)
            {
                return false;
            }
        }
    }
    else
    {
        LLCubeMap* cube_map =
            gSky.mVOSkyp ? gSky.mVOSkyp->getCubeMap() : nullptr;
        std::string environment_error;
        legacy_environment = cube_map
            ? cube_map->getMetalTexture(&environment_error) : nullptr;
        if (!legacy_environment)
        {
            return false;
        }
    }
    if (has_sun_shadow && !fillMetalImpostorDirectionalShadows())
    {
        return false;
    }

    if (has_ssao && !capture.base_noise_texture)
    {
        constexpr U32 noise_size = ALRenderResourcePlan::NOISE_SIZE;
        const std::size_t texel_count =
            static_cast<std::size_t>(noise_size) * noise_size;
        if (mMetalNoiseMapRG16.size() != texel_count * 2)
        {
            LL_WARNS("Metal")
                << "Static SSAO noise has no matching CPU publication for "
                   "native world lighting"
                << LL_ENDL;
            return false;
        }

        ALMetalTextureDescriptor descriptor;
        descriptor.format = ALMetalPixelFormat::rg16_float;
        descriptor.width = noise_size;
        descriptor.height = noise_size;
        descriptor.storage = ALMetalStorageMode::private_gpu;
        descriptor.usage = ALMetalTextureUsage::shader_read;
        descriptor.label = "Alchemy static SSAO noise publication";
        std::string error;
        capture.base_noise_texture = ALMetalTexture::create(
            *capture.device, descriptor, &error);
        auto upload = capture.base_noise_texture
            ? capture.device->makeCommandBuffer(
                  "Alchemy static SSAO noise upload", &error)
            : nullptr;
        const bool uploaded = upload &&
            capture.base_noise_texture->upload(
                *upload, 0, 0, {}, mMetalNoiseMapRG16.data(),
                static_cast<std::size_t>(noise_size) * 2 * sizeof(U16),
                &error) &&
            upload->commit(&error);
        if (!uploaded)
        {
            capture.base_noise_texture.reset();
            LL_WARNS("Metal")
                << "Could not upload the static SSAO noise for native "
                   "world lighting: "
                << error << LL_ENDL;
            return false;
        }
    }

    ALMetalWorldLightMapScene scene;
    scene.gbuffer = capture.target.get();
    scene.directional_shadows = has_sun_shadow &&
            capture.impostor_directional_shadows.depth_texture
        ? &capture.impostor_directional_shadows : nullptr;
    scene.noise_texture = has_ssao
        ? capture.base_noise_texture.get() : nullptr;
    ALMetalWorldLightMapConstants& constants = scene.constants;
    LLMatrix4a inverse_projection;
    inverse_projection.setInverse(camera.getProjection());
    std::memcpy(constants.inverse_projection,
                inverse_projection.getF32ptr(),
                sizeof(constants.inverse_projection));
    const bool sun_up = LLEnvironment::instance().getIsSunUp();
    const LLVector4& light_direction = sun_up
        ? mTransformedSunDir : mTransformedMoonDir;
    std::memcpy(constants.light_direction, light_direction.mV,
                sizeof(light_direction.mV));
    constants.ssao[0] = mDeferredUBOData.ssao_radius;
    constants.ssao[1] = mDeferredUBOData.ssao_max_radius;
    constants.ssao[2] = mDeferredUBOData.ssao_factor;
    constants.ssao[3] = mDeferredUBOData.ssao_factor_inv;
    const ALLightMapBlur::Kernel blur = ALLightMapBlur::kernel(
        RenderShadowGaussian, RenderShadowBlurSize,
        RenderShadowBlurDistFactor);
    for (U32 index = 0; index < 4; ++index)
    {
        std::memcpy(constants.blur_taps[index], blur.mTaps[index].mV,
                    sizeof(blur.mTaps[index].mV));
    }
    constants.blur[0] = blur.mScale;
    constants.blur[1] = blur.mDistFactor;
    constants.screen[0] = static_cast<F32>(capture.width);
    constants.screen[1] = static_cast<F32>(capture.height);
    constants.config[0] = capture.reverse_z ? 1u : 0u;
    constants.config[1] = has_sun_shadow ? 1u : 0u;
    constants.config[2] = has_ssao ? 1u : 0u;
    constants.config[3] = capture.normal_hdr ? 1u : 0u;

    std::string error;
    auto target = capture.renderer->renderLightMap(scene, &error);
    if (!target)
    {
        LL_WARNS("Metal")
            << "Native world light-map owner retained the exact GL "
               "fallback after encode failure: "
            << error << LL_ENDL;
        return false;
    }
    capture.base_light_map_target = std::move(target);
    if (!capture.continuous_world_capture &&
        !capture.world_ui_continuous_unlocked)
    {
        LL_DEBUGS("Metal")
            << "Native world directional-shadow/SSAO light-map owner "
               "encoded at "
            << capture.base_light_map_target->descriptor().width << "x"
            << capture.base_light_map_target->descriptor().height
            << "; static noise is CPU-published and live cascades are "
               "direct Metal depth slices"
            << LL_ENDL;
    }
    return true;
}

void LLPipeline::renderMetalWorldBaseLighting(
    LLViewerCamera& camera, bool has_sun_shadow, bool has_ssao,
    F32 ssao_scale, F32 ssao_max)
{
    if (!isMetalWorldCapturePass() ||
        (!mMetalHeroWorldCaptureActive &&
         !mMetalReflectionWorldCaptureActive && mRT != &mMainRT) ||
        !mMetalWorldSimpleCapture)
    {
        return;
    }
    MetalWorldSimpleCapture& capture = *mMetalWorldSimpleCapture;
    if (!capture.device || !capture.renderer || !capture.target ||
        !capture.base_light_map_target ||
        capture.base_lighting_attempted)
    {
        return;
    }

    ALMetalWorldReflectionProbes probes;
    const ALMetalTexture* legacy_environment = nullptr;
    bool use_reflection_probes = sReflectionProbesEnabled;
    if (sReflectionProbesEnabled)
    {
        if (!mReflectionMapManager.fillMetalReflectionProbes(probes) ||
            !probes.irradiance_texture)
        {
            // The first native probe face cannot depend on the irradiance
            // texture that this capture is responsible for publishing.
            // Bootstrap that offscreen face from the native sky cube, while
            // keeping the visible main-world transaction fail-closed.
            if (!isMetalProbeFaceCaptureActive())
            {
                LL_WARNS_ONCE("Metal")
                    << "Native main-world base lighting is waiting for a "
                       "coherent reflection-probe radiance/SH pair"
                    << LL_ENDL;
                return;
            }
            LLCubeMap* cube_map =
                gSky.mVOSkyp ? gSky.mVOSkyp->getCubeMap() : nullptr;
            std::string environment_error;
            legacy_environment = cube_map
                ? cube_map->getMetalTexture(&environment_error) : nullptr;
            if (!legacy_environment)
            {
                return;
            }
            use_reflection_probes = false;
        }
    }
    else
    {
        LLCubeMap* cube_map =
            gSky.mVOSkyp ? gSky.mVOSkyp->getCubeMap() : nullptr;
        std::string environment_error;
        legacy_environment = cube_map
            ? cube_map->getMetalTexture(&environment_error) : nullptr;
        if (!legacy_environment)
        {
            return;
        }
    }

    const bool hero_active = use_reflection_probes && !gCubeSnapshot &&
        isMetalHeroProbeActive();
    if (hero_active && !fillMetalImpostorHeroProbe())
    {
        return;
    }
    const bool ssr_active = use_reflection_probes &&
        mResourcePlan.wants(ALRenderResourcePlan::Id::SSRScene) &&
        !gCubeSnapshot;
    const bool ssr_history_ready = !ssr_active ||
        fillMetalImpostorScreenSpaceReflections();
    // Startup and resize have no predecessor. Encode the first complete
    // native frame without SSR, publish its coherent color/depth pair, and
    // bar that warm-up frame from UI composition and presentation. Metal
    // never bootstraps its history by reading the GL framebuffer.
    capture.world_ssr_history_warmup =
        ssr_active && !ssr_history_ready;

    ALMetalWorldBaseLightingScene scene;
    scene.diagnostic_view.frame_index = gFrameCount;
    scene.diagnostic_view.view_kind = capture.hero_probe_face_capture ? 2
        : capture.reflection_probe_face_capture ? 3 : isMainWorldPass() ? 1 : 0;
    scene.diagnostic_view.face_index = capture.hero_probe_face_capture
        ? capture.hero_probe_face : capture.reflection_probe_face_capture
        ? capture.reflection_probe_face : 0;
    std::memcpy(scene.diagnostic_view.projection,
                camera.getProjection().getF32ptr(),
                sizeof(scene.diagnostic_view.projection));
    scene.gbuffer = capture.target.get();
    scene.light_map = capture.base_light_map_target->colorTexture(0);
    scene.reflection_probes = use_reflection_probes
        ? &probes : nullptr;
    scene.legacy_environment = legacy_environment;
    scene.hero_probe = hero_active
        ? &capture.impostor_hero_probe : nullptr;
    scene.screen_space_reflections = ssr_active && ssr_history_ready
        ? &capture.impostor_screen_space_reflections : nullptr;
    // The following local/projector owners continue this exact target in
    // place, then opaque-forward consumes it without a color copy. Keep the
    // depth shader-readable for water pyramids and coherent SSR history.
    scene.carry_depth = true;
    scene.borrow_depth = true;
    scene.depth_stencil_shader_read = true;
    scene.hdr = capture.hdr;
    ALMetalWorldBaseLightingConstants& constants = scene.constants;
    constants.environment_config[1] = mResourceInputs.mEmissive ? 0u : 1u;
    LLMatrix4a inverse_projection;
    inverse_projection.setInverse(camera.getProjection());
    std::memcpy(constants.inverse_projection,
                inverse_projection.getF32ptr(),
                sizeof(constants.inverse_projection));
    const bool sun_up = LLEnvironment::instance().getIsSunUp();
    const LLVector4& light_direction = sun_up
        ? mTransformedSunDir : mTransformedMoonDir;
    std::memcpy(constants.light_direction, light_direction.mV,
                sizeof(light_direction.mV));
    const LLEnvironment::EnvironmentUBOData& environment =
        LLEnvironment::instance().getEnvironmentUBOData();
    std::memcpy(constants.atmos_sunlit, environment.atmos_sunlit,
                sizeof(environment.atmos_sunlit));
    std::memcpy(constants.atmos_sunlit_linear,
                environment.atmos_sunlit_linear,
                sizeof(environment.atmos_sunlit_linear));
    std::memcpy(constants.atmos_amblit, environment.atmos_amblit,
                sizeof(environment.atmos_amblit));
    std::memcpy(constants.ssao_effect, mDeferredUBOData.ssao_effect_mat,
                sizeof(constants.ssao_effect));
    constants.lighting[0] = environment.sky_sunlight_scale;
    constants.lighting[1] = environment.sky_ambient_scale;
    constants.lighting[2] = ssao_scale;
    constants.lighting[3] = ssao_max;
    constants.surface[0] = mDeferredUBOData.specular_exponent;
    constants.surface[1] = capture.normal_hdr ? 1.f : 0.f;
    // Match bindDeferredShader's transpose=true env_mat upload. These are
    // the same padded columns used by the validated ordinary-probe bridge.
    const F32* modelview =
        LLViewerCamera::getCurrent().getModelview().getF32ptr();
    constants.environment_matrix[0][0] = modelview[0];
    constants.environment_matrix[0][1] = modelview[4];
    constants.environment_matrix[0][2] = modelview[8];
    constants.environment_matrix[1][0] = modelview[1];
    constants.environment_matrix[1][1] = modelview[5];
    constants.environment_matrix[1][2] = modelview[9];
    constants.environment_matrix[2][0] = modelview[2];
    constants.environment_matrix[2][1] = modelview[6];
    constants.environment_matrix[2][2] = modelview[10];
    constants.environment[0] =
        environment.reflection_probe_ambiance;
    const bool native_sky = capture.hdri_sky_native_available ||
        capture.split_sky_native_available ||
        capture.windlight_sky_native_available;
    constants.sky_transfer[0] = capture.split_sky_native_available
        ? capture.split_sky_windlight_hdr_scale
        : capture.windlight_sky_native_available
            ? capture.windlight_sky_hdr_scale : 1.f;
    constants.sky[0] = native_sky ? 1u : 0u;
    constants.sky[1] = capture.hdr ? 1u : 0u;
    constants.sky[2] = capture.split_sky_native_available
        ? 2u : capture.windlight_sky_native_available ? 1u : 0u;
    constants.config[0] = capture.reverse_z ? 1u : 0u;
    constants.config[1] = LLRender::sClassicMode ? 1u : 0u;
    constants.config[2] = has_sun_shadow ? 1u : 0u;
    constants.config[3] = has_ssao ? 1u : 0u;
    constants.environment_config[0] =
        use_reflection_probes ? 0u : 1u;

    // Begin only after scene preparation, immediately before the owned base
    // command is created. Reject an enclosing batch rather than capturing an
    // empty interval whose command was created before capture began.
    struct BaseCaptureEnd
    {
        bool started;
        ~BaseCaptureEnd() noexcept { if (started) end_metal_base_capture(false); }
    } capture_end{
        scene.diagnostic_view.view_kind == 1 && !gSnapshot && !gCubeSnapshot &&
        !capture.renderer->commandBatchActive() && begin_metal_base_capture()};
    std::string error;
    auto target = capture.renderer->renderBaseLighting(scene, &error);
    // End before publishing the result or emitting any other rendering work.
    if (capture_end.started)
    {
        end_metal_base_capture(static_cast<bool>(target));
        capture_end.started = false;
    }
    if (!target)
    {
        ++capture.base_lighting_failed_frames;
        capture.base_lighting_attempted = true;
        LL_WARNS("Metal")
            << "Native world base-light owner retained GL after its "
               "migration attempt failed: "
            << error << LL_ENDL;
        return;
    }

    capture.base_light_target = std::move(target);
    capture.base_lighting_attempted = true;
    capture.base_lighting_failed_frames = 0;
    if (!capture.continuous_world_capture &&
        !capture.world_ui_continuous_unlocked)
    {
        LL_DEBUGS("Metal")
            << "Native world "
            << (use_reflection_probes
                    ? "probe-finished" : "legacy-sky-cube")
            << " base-light owner encoded at "
            << capture.base_light_target->descriptor().width << "x"
            << capture.base_light_target->descriptor().height
            << (capture.hdri_sky_native_available
                    ? "; full HDRI clear-depth transfer is native"
                    : capture.windlight_sky_native_available
                        ? capture.windlight_stars_native_available
                            ? "; WindLight haze/star clear-depth transfer is native"
                            : "; WindLight atmospheric clear-depth transfer is native"
                        : "; sky transfer remains GL-owned")
            << "; GL remains authoritative until the retained lighting "
               "outputs are composed and later world owners are native"
            << LL_ENDL;
    }
}
#endif

LLPipeline::~LLPipeline()
{
}

void LLPipeline::cleanup()
{
    assertInitialized();

    mGroupQ1.clear() ;

    for(pool_set_t::iterator iter = mPools.begin();
        iter != mPools.end(); )
    {
        pool_set_t::iterator curiter = iter++;
        LLDrawPool* poolp = *curiter;
        if (poolp->isFacePool())
        {
            LLFacePool* face_pool = (LLFacePool*) poolp;
            if (face_pool->mReferences.empty())
            {
                mPools.erase(curiter);
                removeFromQuickLookup( poolp );
                delete poolp;
            }
        }
        else
        {
            mPools.erase(curiter);
            removeFromQuickLookup( poolp );
            delete poolp;
        }
    }

    if (!mTerrainPools.empty())
    {
        LL_WARNS() << "Terrain Pools not cleaned up" << LL_ENDL;
    }
    if (!mTreePools.empty())
    {
        LL_WARNS() << "Tree Pools not cleaned up" << LL_ENDL;
    }

    delete mAlphaPoolPreWater;
    mAlphaPoolPreWater = nullptr;
    delete mAlphaPoolPostWater;
    mAlphaPoolPostWater = nullptr;
    delete mSkyPool;
    mSkyPool = NULL;
    delete mTerrainPool;
    mTerrainPool = NULL;
    delete mWaterPool;
    mWaterPool = NULL;
    delete mSimplePool;
    mSimplePool = NULL;
    delete mFullbrightPool;
    mFullbrightPool = NULL;
    delete mGlowPool;
    mGlowPool = NULL;
    delete mBumpPool;
    mBumpPool = NULL;
    // don't delete wl sky pool it was handled above in the for loop
    //delete mWLSkyPool;
    mWLSkyPool = NULL;
    delete mWaterExclusionPool;
    mWaterExclusionPool = nullptr;

    releaseAllRenderResources();

    mFaceSelectImagep = NULL;

    mMovedList.clear();
    mMovedBridge.clear();
    mShiftList.clear();

    mInitialized = false;

    mDeferredVB = NULL;
    mScreenTriangleVB = nullptr;
    mExposureHistogramVB = nullptr;

    mCubeVB = NULL;

    mReflectionMapManager.cleanup();
    mHeroProbeManager.cleanup();
}

//============================================================================

void LLPipeline::markRenderInputsDirty(ALRenderInputRequests::Change change)
{
    mRenderInputRequests.mark(change);
}

bool LLPipeline::reloadMetalShaders(std::string* error)
{
    // Programs are rebuilt before this frame starts recording any world/UI
    // commands. Targets, exposure histories and published avatar resources
    // remain owned by their existing capture/resource owners.
    for (auto* owner : {mMetalWorldSimpleCapture.get(), mMetalProbeWorldSimpleCapture.get()})
    {
        if (owner && owner->renderer && owner->renderer->commandBatchActive())
        {
            if (error) *error = "A native world transaction is active during shader reload";
            return false;
        }
    }
    if (!gGL.reloadMetalShaders(error)) return false;
    for (auto* owner : {mMetalWorldSimpleCapture.get(), mMetalProbeWorldSimpleCapture.get()})
    {
        if (owner && owner->renderer && !owner->renderer->reloadShaders(error)) return false;
    }
    return true;
}

void LLPipeline::applyRenderInputs()
{
    // A frame starts here, with every transient target the last one acquired back in the pool. Debug GL poisons each
    // as it is released, and names each for whoever acquires it. Nothing is trimmed until the user is logged in: the
    // login's frames draw no world, and the world's first frame takes what the reconcile readied for it rather than
    // building it mid-pass.
    mTransientTargets.setValidation(gDebugGL);
    mTransientTargets.holdTrimming(LLStartUp::getStartupState() < STATE_STARTED);
    mTransientTargets.beginFrame();
    if (mTransientTargets.namesRecorded())
    {
        LL_INFOS("RenderResources") << "Transient targets over the frame after the reconcile, "
                                    << (mTransientTargets.lastFrame().mBytes >> 20) << " MiB:\n"
                                    << mTransientTargets.describe() << LL_ENDL;
    }

    // Nothing is applied to resources that are not there. Before the pipeline's first load, and while a context is
    // lost, the load that comes next (loadRenderInputs) applies whatever was marked until then.
    if (!mInitialized || !mGLResourcesLive)
    {
        return;
    }
    if (const std::optional<ALRenderInputRequests::Application> taken = mRenderInputRequests.take())
    {
        applyRenderInputs(*taken);
    }
}

void LLPipeline::loadRenderInputs()
{
    ALRenderInputRequests::Application taken = mRenderInputRequests.take().value_or(ALRenderInputRequests::Application{});
    taken.mRebuildPrograms = true;
    applyRenderInputs(taken);
}

void LLPipeline::applyRenderInputs(const ALRenderInputRequests::Application& taken)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    using Programs = ALRenderApplication::Programs;

    latchRenderInputs();

    LLViewerShaderMgr* shaders = LLViewerShaderMgr::instance();
    const ALRenderApplication steps = ALRenderApplication::make(
        taken.mRebuildPrograms, mShadersLoaded ? std::optional<ALShaderInputs>(shaders->inputs()) : std::nullopt,
        mLatchedShaderInputs, mGLResourcesLive ? std::optional<ALRenderResourceInputs>(mRequestedInputs) : std::nullopt,
        mLatchedInputs);
    if (steps.idle())
    {
        return;
    }

    mApplyingChanges = taken.mChanges;
    const bool reload = steps.mPrograms != Programs::Kept;
    const bool rebuild_native = steps.mPrograms == Programs::Rebuilt &&
        (mShadersLoaded || mMetalShaderReloadPending);
    if (reload)
    {
        if (ALMetalDevice* device = getViewerMetalDevice())
            LLViewerShaderMgr::configureNativePipelineCache(*device);
    }
    if (rebuild_native)
    {
        std::string shader_error;
        if (!reloadMetalShaders(&shader_error))
        {
            // Retain each owner's usable old pipelines and the last published
            // complete frame; retry at the next safe application boundary.
            mMetalShaderReloadPending = true;
            mShadersLoaded = false;
            mRenderInputRequests.mark(ALRenderInputRequests::Change::Programs);
            mApplyingChanges = 0;
            LL_WARNS("ShaderLoading") << "Native shader reload withheld: " << shader_error << LL_ENDL;
            return;
        }
        mMetalShaderReloadPending = false;
    }
    // Programs first: the resources' plan takes the normal layout and the depth convention they compile for.
    if (reload && !shaders->setShaders(mLatchedShaderInputs, steps))
    {
        mMetalShaderReloadPending = true;
        mShadersLoaded = false;
        mRenderInputRequests.mark(ALRenderInputRequests::Change::Programs);
        mApplyingChanges = 0;
        return;
    }
    if (rebuild_native)
    {
        // Independent utility/preview owners consume this revision lazily at
        // their next valid operation. Do not discard generated images or
        // publish a new revision for failed or ordinary settings reloads.
        ALMetalShaderLibrary::requestBuiltinReload();
    }
    if (steps.mReconcile)
    {
        rebuildGLBuffers(mLatchedInputs, reload             ? RebuildCause::ShaderReload
                                         : taken.mSkipFrame ? RebuildCause::Resize
                                                            : RebuildCause::Setting);
    }
    else if (reload)
    {
        programsReloaded();
    }
    mApplyingChanges = 0;
}

bool LLPipeline::beginSizeOverride(U32 width, U32 height)
{
    llassert(!mRenderInputRequests.overriding());
    mRenderInputRequests.overrideBegins();

#if LL_DARWIN
    mMetalSizeOverrideActive = false;
    mMetalSizeOverrideWidth = 0;
    mMetalSizeOverrideHeight = 0;

    const LLWindow* window = gViewerWindow
        ? gViewerWindow->getWindow() : nullptr;
    const ALMetalDevice* device = window
        ? window->getMetalDevice() : nullptr;
    U32 native_width = width;
    U32 native_height = height;
    ALRenderResourceInputs::scaleToRenderResolution(
        native_width, native_height, mLatchedInputs.mResolutionDivisor,
        mLatchedInputs.mResolutionMultiplier);
    const U32 max_dimension = device
        ? device->info().max_texture_2d_dimension : 0;
    if (!device || width == 0 || height == 0 || native_width == 0 ||
        native_height == 0 || width > max_dimension ||
        height > max_dimension || native_width > max_dimension ||
        native_height > max_dimension)
    {
        LL_WARNS("Snapshot")
            << "Cannot apply native snapshot size " << width << 'x'
            << height << " (scaled " << native_width << 'x'
            << native_height << ", Metal limit " << max_dimension << ')'
            << LL_ENDL;
        return false;
    }

    mMetalSizeOverrideWidth = native_width;
    mMetalSizeOverrideHeight = native_height;
    mMetalSizeOverrideActive = true;
    LL_INFOS_ONCE("Metal")
        << "Native snapshots override the Metal capture size without "
           "reconciling GL render targets"
        << LL_ENDL;
    return true;
#else
    (void)width;
    (void)height;
    return false;
#endif
}

void LLPipeline::endSizeOverride()
{
#if LL_DARWIN
    mMetalSizeOverrideActive = false;
    mMetalSizeOverrideWidth = 0;
    mMetalSizeOverrideHeight = 0;
#endif
    mRenderInputRequests.overrideEnds();
}

void LLPipeline::latchRenderInputs()
{
    mLatchedShaderInputs = shaderInputsFromSettings();
    mLatchedInputs       = resourceInputsFromSettings(mLatchedShaderInputs);

    sReflectionProbesEnabled = mLatchedInputs.mProbes;
    sRenderTransparentWater  = mLatchedShaderInputs.mLocal.mTransparentWater;

    mMaxFramesAhead  = gSavedSettings.getU32("AlchemyRenderMaxFramesAhead");
    mPacingSlackWork = gSavedSettings.getBOOL("AlchemyRenderPacingSlackWork");
}

const ALShaderInputs& LLPipeline::shaderInputs() const
{
    return LLViewerShaderMgr::instance()->inputs();
}

// static
void LLPipeline::scaleToRenderResolution(U32& resX, U32& resY)
{
    ALRenderResourceInputs::scaleToRenderResolution(resX, resY, gPipeline.mLatchedInputs.mResolutionDivisor,
                                                    gPipeline.mLatchedInputs.mResolutionMultiplier);
}

LLRenderTarget* LLPipeline::resourceTarget(ALRenderResourcePlan::Id id)
{
    using Plan = ALRenderResourcePlan;
    using Id   = Plan::Id;
    using Slot = Plan::Slot;

    // The pool's, acquired by the passes that use them.
    if (Plan::isTransient(id))
    {
        return nullptr;
    }

    if (const std::optional<Plan::Pack> pack = Plan::packOf(id))
    {
        RenderTargetPack& rt = *pack == Plan::Pack::Main ? mMainRT : (*pack == Plan::Pack::Probe ? mAuxillaryRT : mHeroProbeRT);
        const Slot slot = Plan::slotOf(id);
        switch (slot)
        {
            case Slot::GBuffer:  return &rt.deferredScreen;
            case Slot::Screen:   return &rt.screen;
            default:
                return nullptr;
        }
    }

    switch (id)
    {
        case Id::SSRScene:          return &mSceneMap;
        case Id::DownRes:           return &mDownResMap;
        case Id::ExposureMeter:     return &mLuminanceMap;
        case Id::ExposureHistogram: return &mExposureHistogram;
        case Id::Exposure:          return &mExposureMap;
        case Id::ExposureLast:      return &mLastExposure;
        case Id::LensFlareA:        return &mLensFlareState[0];
        case Id::LensFlareB:        return &mLensFlareState[1];
        default:
            return nullptr;
    }
}

bool LLPipeline::resourceTextureReady(ALRenderResourcePlan::Id id)
{
    using Id = ALRenderResourcePlan::Id;
#if LL_DARWIN
    constexpr std::size_t noise_texels =
        static_cast<std::size_t>(ALRenderResourcePlan::NOISE_SIZE) *
        ALRenderResourcePlan::NOISE_SIZE;
    switch (id)
    {
        case Id::Noise:
            return mMetalNoiseMapRG16.size() == noise_texels * 2;
        case Id::TrueNoise:
            return mMetalTrueNoiseMapRGBA16.size() == noise_texels * 4;
        default:
            // Darwin does not plan the legacy SMAA GL textures. Keep the
            // fallback explicit for plan invariants and future additions.
            break;
    }
#endif
    return false;
}

void LLPipeline::releaseResourceTexture(ALRenderResourcePlan::Id id)
{
    using Id = ALRenderResourcePlan::Id;
#if LL_DARWIN
    switch (id)
    {
        case Id::Noise:
            mMetalNoiseMapRG16.clear();
            for (const auto* capture_owner :
                 { &mMetalWorldSimpleCapture,
                   &mMetalProbeWorldSimpleCapture })
            {
                if (*capture_owner)
                {
                    (*capture_owner)->base_noise_texture.reset();
                }
            }
            mNoiseMap = 0;
            return;
        case Id::TrueNoise:
            mMetalTrueNoiseMapRGBA16.clear();
            for (const auto* capture_owner :
                 { &mMetalWorldSimpleCapture,
                   &mMetalProbeWorldSimpleCapture })
            {
                if (*capture_owner)
                {
                    (*capture_owner)->legacy_glow_noise_texture.reset();
                }
            }
            mTrueNoiseMap = 0;
            return;
        case Id::SMAAArea:
            mSMAAAreaMap = 0;
            return;
        case Id::SMAASearch:
            mSMAASearchMap = 0;
            return;
        case Id::SMAASample:
            mSMAASampleMap = 0;
            return;
        default:
            return;
    }
#endif
}

void LLPipeline::ensureResources(const ALRenderResourcePlan& plan, const ALRenderResourcePlan::IdSet& ids,
                                 ResourceChanges& changes)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;
    using Plan = ALRenderResourcePlan;
    using Id   = Plan::Id;

    // Owners first: a target sharing depth attaches the depth its owner holds once the owner is what the plan says.
    for (const bool sharers : { false, true })
    {
        for (size_t i = 0; i < Plan::ID_COUNT; ++i)
        {
            const Id              id       = (Id)i;
            const Plan::Resource& resource = plan[id];
            if (!ids.test(i) || resource.mDepthFrom.has_value() != sharers || Plan::isTransient(id))
            {
                continue;
            }

            // Shadow descriptions are the Metal allocator's size/format contract. No retained GL target exists for
            // them, and a native allocation failure is recorded by slice validity when the transaction is attempted.
            if (Plan::isShadowMap(id))
            {
                continue;
            }

            if (Plan::isTexture(id))
            {
                const bool ready = resourceTextureReady(id);
                if (resource.mDesc && !ready)
                {
                    // A texture whose contents have no source (the SMAA sample image, without a SamplePath) is left
                    // unmade without failing anything.
                    createResourceTexture(id);
                    if (resourceTextureReady(id))
                    {
                        changes.mBuilt.set(i);
                    }
                }
                else if (!resource.mDesc && ready)
                {
                    releaseResourceTexture(id);
                    changes.mFreed.set(i);
                }
                else if (ready)
                {
                    changes.mKept.set(i);
                }
                continue;
            }

            LLRenderTarget& target = *resourceTarget(id);
            if (!resource.mDesc)
            {
                if (target.desc() != ALRenderTargetDesc{})
                {
                    target.release();
                    changes.mFreed.set(i);
                }
                continue;
            }

            const LLRenderTarget::EnsureResult result = resource.mDepthFrom
                ? target.ensure(*resource.mDesc, *resourceTarget(*resource.mDepthFrom))
                : target.ensure(*resource.mDesc);
            switch (result)
            {
                case LLRenderTarget::EnsureResult::Kept:
                    changes.mKept.set(i);
                    break;
                case LLRenderTarget::EnsureResult::Built:
                    changes.mBuilt.set(i);
                    break;
                case LLRenderTarget::EnsureResult::Failed:
                    changes.mFailed.set(i);
                    break;
            }
        }
    }

}

void LLPipeline::prewarmTransients(const ALRenderResourcePlan& plan, const ALRenderResourcePlan::IdSet& ids,
                                   ResourceChanges& changes)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;
    using Plan = ALRenderResourcePlan;
    using Id   = Plan::Id;

    // Nearly every target the pool holds is the main view's size, and a pooled target over a depth the reconcile built
    // again could be matched by nothing.
    const std::optional<ALRenderTargetDesc>& gbuffer = plan.desc(Id::MainGBuffer);
    mTransientTargets.setMainSize(gbuffer ? gbuffer->width : 0, gbuffer ? gbuffer->height : 0);
    mTransientTargets.dropStaleDepth();

    // Each is given back before the next is asked for, so a description several resources share is built once. One
    // whose depth another transient resource shares is held until that one has it.
    Plan::IdSet owners;
    for (size_t i = 0; i < Plan::ID_COUNT; ++i)
    {
        const Plan::Resource& resource = plan[(Id)i];
        if (Plan::isPrewarmed((Id)i) && resource.mDesc && resource.mDepthFrom && Plan::isTransient(*resource.mDepthFrom))
        {
            owners.set((size_t)*resource.mDepthFrom);
        }
    }

    ALTransientTargets                          scope(mTransientTargets);
    std::array<LLRenderTarget*, Plan::ID_COUNT> held{};
    for (const bool sharers : { false, true })
    {
        for (size_t i = 0; i < Plan::ID_COUNT; ++i)
        {
            const Id              id       = (Id)i;
            const Plan::Resource& resource = plan[id];
            if (!ids.test(i) || !Plan::isPrewarmed(id) || !resource.mDesc || resource.mDepthFrom.has_value() != sharers)
            {
                continue;
            }

            LLRenderTarget* target = nullptr;
            if (!resource.mDepthFrom)
            {
                target = scope.acquire(*resource.mDesc, Plan::name(id));
            }
            else if (LLRenderTarget* owner = Plan::isTransient(*resource.mDepthFrom) ? held[(size_t)*resource.mDepthFrom]
                                                                                    : resourceTarget(*resource.mDepthFrom))
            {
                target = scope.acquire(*resource.mDesc, *owner, Plan::name(id));
            }

            if (!target)
            {
                changes.mFailed.set(i);
                continue;
            }
            changes.mPooled.set(i);
            if (owners.test(i))
            {
                held[i] = target;
            }
            else
            {
                scope.release(target);
            }
        }
    }
}

LLRenderTarget* LLPipeline::acquireResource(ALTransientTargets& scope, ALRenderResourcePlan::Id id, std::string_view name,
                                            LLRenderTarget* depth_from)
{
    const ALRenderResourcePlan::Resource& resource = mResourcePlan[id];
    if (!resource.mDesc)
    {
        return nullptr;
    }
    if (name.empty())
    {
        name = ALRenderResourcePlan::name(id);
    }
    if (!resource.mDepthFrom)
    {
        return scope.acquire(*resource.mDesc, name);
    }
    // Nothing over an owner left unbuilt, as a render size that fits nothing leaves the G-buffer.
    LLRenderTarget* owner = ALRenderResourcePlan::isTransient(*resource.mDepthFrom) ? depth_from
                                                                                     : resourceTarget(*resource.mDepthFrom);
    return owner && owner->hasDepthAttachment()
        ? scope.acquire(*resource.mDesc, *owner, name) : nullptr;
}

// static
ALShaderInputs LLPipeline::shaderInputsFromSettings()
{
    static_assert(ALShaderInputs::MAX_INDEXED_GLTF_CHANNELS == LLGLSLShader::MAX_INDEXED_GLTF_CHANNELS);

    ALShaderSettings s;
    // Native world/HUD layouts carry 32 diffuse slots and eight PBR material
    // slots. Reverse-Z and compute are baseline Apple Silicon capabilities;
    // shader selection must not inherit the retired GL manager's limits.
    s.mTextureImageUnits = LLGLSLShader::MAX_BATCH_TEXTURE_COUNT;
    s.mHasClipControl = true;
    s.mHasCompute = true;
    s.mIsD3D12 = false;

    s.mReverseZ                 = gSavedSettings.getBOOL("AlchemyRenderReverseZ");
    s.mHDR                      = gSavedSettings.getBOOL("RenderHDREnabled");
    s.mEmissive                 = gSavedSettings.getBOOL("RenderEnableEmissiveBuffer");
    s.mLightingMaxLevel         = gSavedSettings.getS32("RenderShaderLightingMaxLevel");
    s.mReservedTextureIndices   = gSavedSettings.getS32("RenderReservedTextureIndices");
    s.mSSR                      = gSavedSettings.getBOOL("RenderScreenSpaceReflections");
    s.mMirrors                  = gSavedSettings.getBOOL("RenderMirrors");
    s.mProbes                   = LLFeatureManager::getInstance()->isFeatureAvailable("RenderReflectionsEnabled") &&
                                  gSavedSettings.getBOOL("RenderReflectionsEnabled");
    s.mProbeLevel               = gSavedSettings.getS32("RenderReflectionProbeLevel");
    s.mShadowDetail             = gSavedSettings.getS32("RenderShadowDetail");
    s.mShadowFilterQuality      = gSavedSettings.getU32("AlchemyRenderShadowFilterQuality");
    s.mTerrainPlanarSampleCount = gSavedSettings.getS32("RenderTerrainPBRPlanarSampleCount");
    s.mTerrainPBRDetail         = gSavedSettings.getS32("RenderTerrainPBRDetail");
    s.mTerrainHexTiling         = gSavedSettings.getBOOL("AlchemyRenderTerrainHexTiling");
    s.mTerrainPBRNormals        = gSavedSettings.getBOOL("RenderTerrainPBRNormalsEnabled");
    s.mDynamicLOD               = gSavedSettings.getBOOL("RenderDynamicLOD");
    s.mWaterHextile             = gSavedSettings.getU32("AlchemyRenderWaterHextile");
    s.mWaterWaves               = gSavedSettings.getBOOL("AlchemyRenderWaterWaves");
    s.mDisableCompute           = gSavedSettings.getBOOL("AlchemyRenderDisableCompute");
    s.mTransparentWater         = gSavedSettings.getBOOL("RenderTransparentWater");
    s.mSSAO                     = gSavedSettings.getBOOL("RenderDeferredSSAO");
    s.mAvatarCloth              = gSavedSettings.getBOOL("RenderAvatarCloth");
    s.mGlowNoise                = gSavedSettings.getBOOL("RenderGlowNoise");
    s.mBloomHalation            = gSavedSettings.getBOOL("RenderBloomHalation");
    s.mSMAAPredication          = gSavedSettings.getBOOL("RenderSMAAPredication");
    s.mLocalTerrainPaint        = gSavedSettings.getBOOL("LocalTerrainPaintEnabled");
    s.mTerrainPaintBitDepth     = gSavedSettings.getU32("TerrainPaintBitDepth");

    const ALShaderInputs in = ALShaderInputs::make(s);
    const S32 requested_detail =
        std::clamp(s.mTerrainPBRDetail, (S32)TERRAIN_PBR_DETAIL_MIN, (S32)TERRAIN_PBR_DETAIL_MAX);
    if (in.mGlobal.mTerrainPBRDetail < requested_detail)
    {
        LL_INFOS_ONCE("ShaderLoading") << "RenderTerrainPBRDetail " << s.mTerrainPBRDetail << " clamped to "
                                       << in.mGlobal.mTerrainPBRDetail
                                       << ": full detail needs more fragment texture slots than the "
                                       << s.mTextureImageUnits << " this renderer provides." << LL_ENDL;
    }
    return in;
}

// static
ALRenderResourceInputs LLPipeline::resourceInputsFromSettings(const ALShaderInputs& shaders)
{
    ALRenderResourceInputs in;

    if (gViewerWindow)
    {
        in.mWidth  = (U32)gViewerWindow->getWorldViewWidthRaw();
        in.mHeight = (U32)gViewerWindow->getWorldViewHeightRaw();
    }
    in.mResolutionDivisor    = gSavedSettings.getU32("RenderResolutionDivisor");
    in.mResolutionMultiplier = gSavedSettings.getF32("RenderResolutionMultiplier");

    in.mHDR      = gSavedSettings.getBOOL("RenderHDREnabled");
    in.mEmissive = gSavedSettings.getBOOL("RenderEnableEmissiveBuffer");
    in.mGBufferNormHDR = shaders.mGlobal.mGBufferNormHDR;
    in.mReverseZ       = shaders.mGlobal.mReverseZ;
    in.mCompute        = shaders.mLocal.mCompute;

    in.mShadowDetail     = gSavedSettings.getS32("RenderShadowDetail");
    in.mShadowScale      = gSavedSettings.getF32("RenderShadowResolutionScale");
    in.mSpotShadowMaxResolution = gSavedSettings.getU32("AlchemyRenderSpotShadowMaxResolution");
    in.mShadowDepth32F   = gSavedSettings.getBOOL("AlchemyRenderShadowDepth32F");
    in.mSSAO             = gSavedSettings.getBOOL("RenderDeferredSSAO");
    in.mSSR              = gSavedSettings.getBOOL("RenderScreenSpaceReflections");

    in.mProbes = LLFeatureManager::getInstance()->isFeatureAvailable("RenderReflectionsEnabled") &&
                 gSavedSettings.getBOOL("RenderReflectionsEnabled");
    in.mProbeResolution  = ALRenderResourceInputs::probeResolution(gSavedSettings.getU32("RenderReflectionProbeResolution"));
    in.mProbeSuperSample = ALRenderResourceInputs::probeSuperSample(gSavedSettings.getS32("ALProbeSuperSample"));
    in.mProbeAllCascades = gSavedSettings.getBOOL("AlchemyRenderProbeAllShadowCascades");
    in.mMirrors          = gSavedSettings.getBOOL("RenderMirrors");
    // This Apple Silicon fork has no retained material-preview renderer.
    in.mMaterialPreview  = false;
    in.mHeroResolution   = (U32)llmax(gSavedSettings.getS32("RenderHeroProbeResolution"), 1);

    in.mFSAAType          = gSavedSettings.getU32("RenderFSAAType");
    in.mSMAAStencil       = gSavedSettings.getBOOL("RenderSMAAUseStencil");
    in.mSMAAUseSample     = gSavedSettings.getBOOL("RenderSMAAUseSample");
    in.mBloomMips         = gSavedSettings.getS32("RenderBloomMipCount");
    in.mBloomScale        = gSavedSettings.getS32("RenderBloomResolutionScale");
    in.mBloomHalation     = gSavedSettings.getBOOL("RenderBloomHalation");
    in.mGlowResolutionPow = gSavedSettings.getS32("RenderGlowResolutionPow");
    in.mGlowHDR           = gSavedSettings.getBOOL("RenderGlowHDR");
    in.mDeferredNoise     = gSavedSettings.getF32("RenderDeferredNoise");

    in.mBakeWidth  = (U32)LLAvatarAppearanceDefines::SCRATCH_TEX_WIDTH;
    in.mBakeHeight = (U32)LLAvatarAppearanceDefines::SCRATCH_TEX_HEIGHT;

    return in;
}

LLPipeline::ResourceChanges LLPipeline::reconcileResources(const ALRenderResourceInputs& requested)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;
    using Plan  = ALRenderResourcePlan;
    using Id    = Plan::Id;
    using IdSet = Plan::IdSet;

    ALRenderResourceInputs inputs = requested;
    Plan                   plan   = Plan::make(inputs);

    ResourceChanges changes;
    ensureResources(plan, IdSet().set(), changes);
    prewarmTransients(plan, IdSet().set(), changes);

    // Storage kept whose contents an input makes is filled again where that input changed; storage built just now was
    // filled as it was built.
    const IdSet refill = Plan::refilled(mResourceInputs, inputs) & changes.mKept;
    for (size_t i = 0; i < Plan::ID_COUNT; ++i)
    {
        const Id id = (Id)i;
        if (refill.test(i) && Plan::isTexture(id))
        {
            releaseResourceTexture(id);
            createResourceTexture(id);
            changes.mKept.reset(i);
            changes.mBuilt.set(i, resourceTextureReady(id));
        }
    }
    // A target the render size sizes that cannot be built at it halves the size, the height first and then the width,
    // until they can be or there is no size left: any but a bloom level or a shadow map, which are left unbuilt. Only
    // the targets the size sizes are freed and built again at each size: the rest neither drive the size nor follow it.
    const IdSet required = Plan::idsWhere(Plan::drivesRenderSize);
    const IdSet retried  = Plan::idsWhere(Plan::followsRenderSize);

    static LLCachedControl<bool> simulate_failure(gSavedSettings, "SimulateFBOFailure", false);
    const auto short_of_size = [&]() { return simulate_failure() || (changes.mFailed & required).any(); };
    const auto release_render_sized = [&]()
    {
        for (size_t i = 0; i < Plan::ID_COUNT; ++i)
        {
            if (LLRenderTarget* target = retried.test(i) ? resourceTarget((Id)i) : nullptr)
            {
                target->release();
            }
        }
        mTransientTargets.clear();
    };
    const auto retry_at = [&](U32 width, U32 height)
    {
        release_render_sized();
        if (width == 0 || height == 0)
        {
            return false;
        }
        inputs.mWidth  = width;
        inputs.mHeight = height;
        plan           = Plan::make(inputs);
        changes.mBuilt &= ~retried;
        changes.mKept &= ~retried;
        changes.mFailed &= ~retried;
        changes.mPooled &= ~retried;
        ensureResources(plan, retried, changes);
        prewarmTransients(plan, retried, changes);
        return !short_of_size();
    };

    if (short_of_size())
    {
        changes.mFullSize = false;

        U32  width  = inputs.mWidth;
        U32  height = inputs.mHeight;
        bool fitted = false;
        while (!fitted && width > 0 && height > 0)
        {
            height /= 2;
            fitted = retry_at(width, height);
            if (!fitted)
            {
                width /= 2;
                fitted = retry_at(width, height);
            }
        }

        if (!fitted)
        {
            // Nothing the size sizes is kept, whatever the last attempt managed.
            release_render_sized();
            changes.mFailed |= (changes.mBuilt | changes.mKept | changes.mPooled) & retried;
            changes.mBuilt &= ~retried;
            changes.mKept &= ~retried;
            changes.mPooled &= ~retried;
            LL_WARNS() << "Unable to allocate screen buffer at any resolution!" << LL_ENDL;
        }

        // Each attempt emptied the pool, a change of the main size freeing every target in it, the capture packs'
        // with the rest: they are readied again, so that one that cannot be built is known now and not mid-capture.
        changes.mPooled &= retried;
        prewarmTransients(plan, ~retried, changes);
    }

    // What each pack's passes keep about its targets.
    const auto pack_of = [this](Plan::Pack pack) -> RenderTargetPack&
    {
        return pack == Plan::Pack::Main ? mMainRT : (pack == Plan::Pack::Probe ? mAuxillaryRT : mHeroProbeRT);
    };
    for (Plan::Pack pack : { Plan::Pack::Main, Plan::Pack::Probe, Plan::Pack::Hero })
    {
        RenderTargetPack& rt = pack_of(pack);

        // The size the pack renders for: the main view's before the resolution scale, which the snapshots read back,
        // and a capture pack's its own.
        const std::optional<ALRenderTargetDesc>& gbuffer = plan.desc(Plan::inPack(pack, Plan::Slot::GBuffer));
        if (pack == Plan::Pack::Main)
        {
            rt.width  = inputs.mWidth;
            rt.height = inputs.mHeight;
        }
        else
        {
            rt.width  = gbuffer ? gbuffer->width : 0;
            rt.height = gbuffer ? gbuffer->height : 0;
        }

        // The pyramid is as deep as the levels the pool could build, from the first.
        rt.bloomMipCount = 0;
        while (rt.bloomMipCount < BLOOM_MAX_MIPS && changes.mPooled.test((size_t)Plan::bloomMip(pack, rt.bloomMipCount)))
        {
            ++rt.bloomMipCount;
        }
    }

    // The reflections march through last frame's scene, which a new target does not hold.
    if (changes.mBuilt.test((size_t)Id::SSRScene))
    {
        clearSceneMap();
    }
    // New storage holds no history.
    if (changes.mBuilt.test((size_t)Id::Exposure) || changes.mBuilt.test((size_t)Id::LensFlareA) ||
        changes.mBuilt.test((size_t)Id::LensFlareB))
    {
        resetExposureHistory();
    }
    // The probe managers' own resources, planned beside their packs. They are freed here once nothing renders through
    // them, and built by initReflectionMaps: the reflection probes' below, once this plan is the pipeline's, and the
    // mirrors' by the hero manager's update, which runs in the frame before the world is drawn.
    if (!plan.reflectionProbes())
    {
        changes.mReflectionProbesFreed = mReflectionMapManager.freeResources();
    }
    if (!plan.heroProbes())
    {
        changes.mHeroProbesFreed = mHeroProbeManager.holdsResources();
        mHeroProbeManager.cleanup();
#if LL_DARWIN
        retireMetalHeroProbeResources();
#endif
    }

    // What the state derived from the resources depends on, against what they were reconciled to before.
    const std::optional<ALRenderTargetDesc>& gbuffer_before = mResourcePlan.desc(Id::MainGBuffer);
    const std::optional<ALRenderTargetDesc>& gbuffer_after  = plan.desc(Id::MainGBuffer);
    const ALRenderTargetDesc before = gbuffer_before.value_or(ALRenderTargetDesc{});
    const ALRenderTargetDesc after  = gbuffer_after.value_or(ALRenderTargetDesc{});
    const IdSet changed             = Plan::changed(mResourcePlan, plan);
    changes.mMainSize       = before.width != after.width || before.height != after.height;
    changes.mGBufferFormats = before.color != after.color;
    changes.mDepthFormat    = before.depth != after.depth;
    changes.mHDR            = mResourceInputs.mHDR != inputs.mHDR;
    changes.mProbePack      = (changed & Plan::idsOf(Plan::Pack::Probe) & ~Plan::idsWhere(Plan::forMaterialPreview)).any();
    changes.mHeroPack       = (changed & Plan::idsOf(Plan::Pack::Hero)).any();

    mRequestedInputs = requested;
    mResourceInputs  = inputs;
    mResourcePlan    = plan;
#if LL_DARWIN
    refreshMetalSMAASampleTexture();
#endif

    // The reflection manager's update runs after the frame is drawn, so the frame after probes come on would draw
    // through programs that read probes, with no cube array or coefficients to bind. Its update keeps them from then on.
    if (plan.reflectionProbes())
    {
        mReflectionMapManager.initReflectionMaps();
    }

    stop_glerror();
    return changes;
}

// static
void LLPipeline::refreshCachedSettings()
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_DISPLAY;
    LLPipeline::sAutoMaskAlphaDeferred = gSavedSettings.getBOOL("RenderAutoMaskAlphaDeferred");
    LLPipeline::sAutoMaskAlphaNonDeferred = gSavedSettings.getBOOL("RenderAutoMaskAlphaNonDeferred");
    LLPipeline::sUseFarClip = gSavedSettings.getBOOL("RenderUseFarClip");
    LLVOAvatar::sMaxNonImpostors = gSavedSettings.getU32("RenderAvatarMaxNonImpostors");
    LLVOAvatar::updateImpostorRendering(LLVOAvatar::sMaxNonImpostors);

    LLPipeline::sUseOcclusion =
            (!gUseWireframe
            && LLFeatureManager::getInstance()->isFeatureAvailable("UseOcclusion")
            && gSavedSettings.getBOOL("UseOcclusion")) ? 2 : 0;

    WindLightUseAtmosShaders = true; // DEPRECATED -- gSavedSettings.getBOOL("WindLightUseAtmosShaders");
    RenderDeferred = true; // DEPRECATED -- gSavedSettings.getBOOL("RenderDeferred");
    RenderDeferredSunWash = gSavedSettings.getF32("RenderDeferredSunWash");
    RenderShadowSplits = gSavedSettings.getS32("RenderShadowSplits");
    RenderDelayCreation = gSavedSettings.getBOOL("RenderDelayCreation");
    RenderAnimateRes = gSavedSettings.getBOOL("RenderAnimateRes");
    FreezeTime = gSavedSettings.getBOOL("FreezeTime");
    DebugBeaconLineWidth = gSavedSettings.getS32("DebugBeaconLineWidth");
    RenderHighlightBrightness = gSavedSettings.getF32("RenderHighlightBrightness");
    RenderHighlightColor = gSavedSettings.getColor4("RenderHighlightColor");
    RenderHighlightThickness = gSavedSettings.getF32("RenderHighlightThickness");
    RenderSpotLightsInNondeferred = gSavedSettings.getBOOL("RenderSpotLightsInNondeferred");
    PreviewAmbientColor = gSavedSettings.getColor4("PreviewAmbientColor");
    PreviewDiffuse0 = gSavedSettings.getColor4("PreviewDiffuse0");
    PreviewSpecular0 = gSavedSettings.getColor4("PreviewSpecular0");
    PreviewDiffuse1 = gSavedSettings.getColor4("PreviewDiffuse1");
    PreviewSpecular1 = gSavedSettings.getColor4("PreviewSpecular1");
    PreviewDiffuse2 = gSavedSettings.getColor4("PreviewDiffuse2");
    PreviewSpecular2 = gSavedSettings.getColor4("PreviewSpecular2");
    PreviewDirection0 = gSavedSettings.getVector3("PreviewDirection0");
    PreviewDirection1 = gSavedSettings.getVector3("PreviewDirection1");
    PreviewDirection2 = gSavedSettings.getVector3("PreviewDirection2");
    RenderGlowMaxExtractAlpha = gSavedSettings.getF32("RenderGlowMaxExtractAlpha");
    RenderGlowWarmthAmount = gSavedSettings.getF32("RenderGlowWarmthAmount");
    RenderGlowLumWeights = gSavedSettings.getVector3("RenderGlowLumWeights");
    RenderGlowWarmthWeights = gSavedSettings.getVector3("RenderGlowWarmthWeights");
    RenderGlowIterations = gSavedSettings.getS32("RenderGlowIterations");
    RenderGlowWidth = gSavedSettings.getF32("RenderGlowWidth");
    RenderGlowStrength = gSavedSettings.getF32("RenderGlowStrength");
    RenderDepthOfField = gSavedSettings.getBOOL("RenderDepthOfField");
    CameraFocusTransitionTime = gSavedSettings.getF32("CameraFocusTransitionTime");
    CameraFNumber = gSavedSettings.getF32("CameraFNumber");
    CameraFocalLength = gSavedSettings.getF32("CameraFocalLength");
    CameraFieldOfView = gSavedSettings.getF32("CameraFieldOfView");
    RenderShadowNoise = gSavedSettings.getF32("RenderShadowNoise");
    RenderShadowBlurSize = gSavedSettings.getF32("RenderShadowBlurSize");
    RenderSSAOScale = gSavedSettings.getF32("RenderSSAOScale");
    RenderSSAOMaxScale = gSavedSettings.getU32("RenderSSAOMaxScale");
    RenderSSAOFactor = gSavedSettings.getF32("RenderSSAOFactor");
    RenderSSAOEffect = gSavedSettings.getVector3("RenderSSAOEffect");
    RenderShadowOffset = gSavedSettings.getF32("RenderShadowOffset");
    RenderShadowBias = gSavedSettings.getF32("RenderShadowBias");
    RenderSpotShadowOffset = gSavedSettings.getF32("RenderSpotShadowOffset");
    RenderSpotShadowBias = gSavedSettings.getF32("RenderSpotShadowBias");
    RenderEdgeDepthCutoff = gSavedSettings.getF32("RenderEdgeDepthCutoff");
    RenderEdgeNormCutoff = gSavedSettings.getF32("RenderEdgeNormCutoff");
    RenderShadowGaussian = gSavedSettings.getVector3("RenderShadowGaussian");
    RenderShadowBlurDistFactor = gSavedSettings.getF32("RenderShadowBlurDistFactor");
    RenderDeferredAtmospheric = gSavedSettings.getBOOL("RenderDeferredAtmospheric");
    RenderHighlightFadeTime = gSavedSettings.getF32("RenderHighlightFadeTime");
    RenderFarClip = gSavedSettings.getF32("RenderFarClip");
    RenderShadowSplitExponent = gSavedSettings.getVector3("RenderShadowSplitExponent");
    RenderShadowErrorCutoff = gSavedSettings.getF32("RenderShadowErrorCutoff");
    RenderShadowFOVCutoff = gSavedSettings.getF32("RenderShadowFOVCutoff");
    CameraOffset = gSavedSettings.getBOOL("CameraOffset");
    // The Lightbox's range: the depth of field gather takes about 11 * CoF^2 taps a pixel, so a typed value past it
    // could stall the GPU until the driver resets it.
    CameraMaxCoF = llclamp(gSavedSettings.getF32("CameraMaxCoF"), 1.f, 32.f);
    CameraDoFResScale = gSavedSettings.getF32("CameraDoFResScale");
    RenderAutoHideSurfaceAreaLimit = gSavedSettings.getF32("RenderAutoHideSurfaceAreaLimit");
    RenderScreenSpaceReflectionIterations = gSavedSettings.getS32("RenderScreenSpaceReflectionIterations");
    RenderScreenSpaceReflectionRayStep = gSavedSettings.getF32("RenderScreenSpaceReflectionRayStep");
    RenderScreenSpaceReflectionDistanceBias = gSavedSettings.getF32("RenderScreenSpaceReflectionDistanceBias");
    RenderScreenSpaceReflectionDepthRejectBias = gSavedSettings.getF32("RenderScreenSpaceReflectionDepthRejectBias");
    RenderScreenSpaceReflectionAdaptiveStepMultiplier = gSavedSettings.getF32("RenderScreenSpaceReflectionAdaptiveStepMultiplier");
    RenderScreenSpaceReflectionGlossySamples = gSavedSettings.getS32("RenderScreenSpaceReflectionGlossySamples");
    RenderBufferVisualization = gSavedSettings.getS32("RenderBufferVisualization");
    RenderHeroProbeUpdateRate = gSavedSettings.getS32("RenderHeroProbeUpdateRate");
    RenderHeroProbeConservativeUpdateMultiplier = gSavedSettings.getS32("RenderHeroProbeConservativeUpdateMultiplier");

    RenderSpotLight = nullptr;

    if (gNonInteractive)
    {
        LLVOAvatar::sMaxNonImpostors = 1;
        LLVOAvatar::updateImpostorRendering(LLVOAvatar::sMaxNonImpostors);
    }

    bool enable_buffers = gSavedSettings.getBOOL("CollectFontVertexBuffers");
    LLFontTextCache::enableBufferCollection(enable_buffers);
    enable_buffers = gSavedSettings.getBOOL("CollectUIImageVertexBuffers");
    LLUIImage::enableDisplayListsCollection(enable_buffers);
}

void LLPipeline::releaseAllRenderResources()
{
    assertInitialized();

#if LL_DARWIN
    // Pipeline shutdown drops the native world and its histories with the
    // retained resources. There is no context-loss recovery path in this
    // Apple-only product: a later process starts with a fresh Metal device.
    if (mMetalHeroWorldCaptureActive ||
        mMetalReflectionWorldCaptureActive)
    {
        std::swap(
            mMetalWorldSimpleCapture, mMetalProbeWorldSimpleCapture);
        mMetalHeroWorldCaptureActive = false;
        mMetalReflectionWorldCaptureActive = false;
    }
    mMetalWorldSimpleCapture.reset();
    mMetalProbeWorldSimpleCapture.reset();
    mMetalWorldSnapshotRequested = false;
    mMetalExposureHistoryReady = false;
#endif

    releaseRenderTargets();
    releaseDepthDependents();

    LLVOAvatar::resetImpostors();
    gBumpImageList.clear();
    // The probes themselves stay, to render again into what the reconcile on the next context builds.
    mReflectionMapManager.freeResources();
    mHeroProbeManager.cleanup();

    mColorGradeLutLoaded = false;
    mCGLutSize = LLVector4();
#if LL_DARWIN
    mMetalCGLut.reset();
    mMetalToneCurveLut.reset();
    mMetalSMAASampleTexture.reset();
    mMetalSMAASampleDevice = nullptr;
    mMetalSMAASamplePath.clear();
    mMetalSMAASampleSize = -1;
    mMetalSMAASampleModifiedSeconds = -1;
    mMetalSMAASampleModifiedNanoseconds = -1;
    mMetalSMAASampleLastAttempt = std::numeric_limits<U32>::max();
    mMetalSMAASampleFailureReported = false;
#endif

    releaseScopeBuffers();
    clearReferenceStill();

    mDeferredUBO.release(); // retained GL SSAO/specular block (UB_DEFERRED); re-created lazily on next use
    mDeferredUBODirty = true;

    if (LLEnvironment::instanceExists())
    {   // shared environment block (UB_ENVIRONMENT); re-created lazily on next bind
        LLEnvironment::instance().releaseGLBuffers();
    }

    // Release outstanding native diagnostics with the rendering resources.
    mTerrainPrimitives.release();
    mWaterPrimitives.release();
    mWaterPatchPrimitives.release();
    mMetalAvatarProfileRequests.clear();
    mMetalAttachmentProfiles.clear();

    mGLResourcesLive = false;
}

void LLPipeline::releaseRenderTargets()
{
    using Plan = ALRenderResourcePlan;
    mTransientTargets.clear();
    for (size_t i = 0; i < Plan::ID_COUNT; ++i)
    {
        const Plan::Id id = (Plan::Id)i;
        if (LLRenderTarget* target = resourceTarget(id))
        {
            target->release();
        }
        else if (Plan::isTexture(id))
        {
            releaseResourceTexture(id);
        }
    }

    for (RenderTargetPack* rt : { &mMainRT, &mAuxillaryRT, &mHeroProbeRT })
    {
        rt->bloomMipCount = 0;
    }

    mLensFlareStateValid = false;
    mLensFlareStateClearPending = false;
    mToneCurveLutDirty   = true;
    mToneCurveLutLoaded  = false;
#if LL_DARWIN
    mMetalToneCurveLut.reset();
    ++mMetalLensFlareHistoryEpoch;
    if (mMetalLensFlareHistoryEpoch == 0)
    {
        ++mMetalLensFlareHistoryEpoch;
    }
    mMetalLensFlareHistoryReady = false;
    if (mMetalWorldSimpleCapture)
    {
        mMetalWorldSimpleCapture->lens_flare_state_target.reset();
        mMetalWorldSimpleCapture->lens_flare_state_frame =
            std::numeric_limits<U32>::max();
        mMetalWorldSimpleCapture->lens_flare_state_epoch = 0;
        mMetalWorldSimpleCapture->lens_dirt_target.reset();
        mMetalWorldSimpleCapture->lens_dirt_params =
            LensDirtPlateParams();
    }
#endif

    mResourcePlan = {};
}

void LLPipeline::releaseDepthDependents()
{
    mWaterSurface.release();

    if (ALSelectionOutline::instanceExists())
    {
        ALSelectionOutline::instance().release();
    }
}

namespace
{
    // How many changes the frame's application gathered into one reload or reconcile, for its log line.
    std::string applyingChanges(U32 changes)
    {
        return changes > 0 ? fmt::format(", applying {} {}", changes, changes == 1 ? "change" : "changes") : std::string();
    }

    // The names of a set of resources, comma-separated, for the log line.
    std::string resource_names(const ALRenderResourcePlan::IdSet& ids)
    {
        std::string list;
        for (size_t i = 0; i < ALRenderResourcePlan::ID_COUNT; ++i)
        {
            if (ids.test(i))
            {
                if (!list.empty())
                {
                    list += ", ";
                }
                list += ALRenderResourcePlan::name((ALRenderResourcePlan::Id)i);
            }
        }
        return list.empty() ? std::string("nothing") : list;
    }
}

// Whether a rebuild for a resize built every target at the size it was asked for, the rebuild a window dragged by its
// edge makes every frame.
static bool resized_as_asked(LLPipeline::RebuildCause cause, const LLPipeline::ResourceChanges& changes)
{
    return cause == LLPipeline::RebuildCause::Resize && changes.mFullSize && changes.mFailed.none();
}

bool LLPipeline::rebuildGLBuffers(const ALRenderResourceInputs& requested, RebuildCause cause)
{
    LL_PROFILE_ZONE_SCOPED_CATEGORY_PIPELINE;
    assertInitialized();

    // Comma-separated, for the log line.
    const auto add = [](std::string& list, std::string_view what)
    {
        if (!list.empty())
        {
            list += ", ";
        }
        list += what;
    };
    std::string invalidated;

    const bool first_resources = !mGLResourcesLive;
    const ResourceChanges changes = reconcileResources(requested);
    mGLResourcesLive   = true;
    mResourcesFullSize = changes.mFullSize;

    // Which resource each pooled target serves over the next whole frame, for the log; not for a resize that built what
    // it asked, which is logged at debug level alone and comes every frame of a window's drag.
    if (!resized_as_asked(cause, changes))
    {
        mTransientTargets.recordNames();
    }

    std::string changed;
    if (first_resources)
    {
        // The pipeline's first resource load builds retained resources and
        // everything derived from them. Native owners build lazily where they
        // are first wanted.
        add(changed, "initial resources");
        gBumpImageList.restoreResources();
        // Read again otherwise only when RenderColorGrade or RenderColorGradeLUT changes (LLPipeline::init).
        setupGradingLUT();
    }
    else
    {
        if (changes.mMainSize)
        {
            add(changed, "main size");
        }
        if (changes.mGBufferFormats)
        {
            add(changed, "G-buffer formats");
        }
        if (changes.mDepthFormat)
        {
            add(changed, "depth format");
        }
        if (changes.mHDR)
        {
            add(changed, "HDR");
        }
        if (changes.mProbePack)
        {
            add(changed, "probe pack");
        }
        if (changes.mHeroPack)
        {
            add(changed, "hero pack");
        }

        // The exposure adapts in the HDR scene's units, and the flare's history is measured in them.
        if (changes.mHDR)
        {
            resetExposureHistory();
            add(invalidated, "exposure and flare history");
        }

        // The native lens-dirt owner rebuilds when its plate description
        // changes; captureReferenceStill drops a still of another size and
        // the scopes resize their sample without losing it.
#if LL_DARWIN
        if (changes.mMainSize && mMetalWorldSimpleCapture &&
            mMetalWorldSimpleCapture->lens_dirt_target)
        {
            add(invalidated, "lens dirt (next frame)");
        }
#endif
        if (changes.mMainSize && mReferenceStill.isComplete())
        {
            add(invalidated, "reference still (next frame)");
        }

        if (changes.mDepthFormat)
        {
            releaseDepthDependents();
            add(invalidated, "depth pyramid, water surface maps, selection outline, far-plane overlay");
        }

        // An impostor is G-buffer channels and depth in the main G-buffer's formats (generateImpostor), so those
        // are what make one stale; its size is its own.
        if (changes.mGBufferFormats || changes.mDepthFormat)
        {
            U32 baked = 0;
            for (LLCharacter* character : LLCharacter::sInstances)
            {
                baked += ((LLVOAvatar*)character)->mImpostor.isComplete() ? 1 : 0;
            }
            LLVOAvatar::resetImpostors();
            add(invalidated, fmt::format("avatar impostors ({} baked)", baked));
        }
    }

    std::string_view why;
    switch (cause)
    {
        case RebuildCause::Setting:
            why = " for a setting";
            break;
        case RebuildCause::ShaderReload:
            why = " after a shader reload";
            break;
        case RebuildCause::Resize:
            why = " for a resize";
            break;
        case RebuildCause::Snapshot:
            why = " for a snapshot";
            break;
    }

    // A new context builds everything, which its count says better than sixty names.
    const std::string built = first_resources ? fmt::format("{} resources", changes.mBuilt.count())
                                          : resource_names(changes.mBuilt);
    std::string freed = changes.mFreed.any() ? resource_names(changes.mFreed) : std::string();
    if (changes.mReflectionProbesFreed)
    {
        add(freed, "reflection probes");
    }
    if (changes.mHeroProbesFreed)
    {
        add(freed, "hero probes");
    }
    const std::string applying = applyingChanges(mApplyingChanges);
    std::ostringstream line;
    line << "Render resources reconciled at " << mMainRT.deferredScreen.getWidth() << "x"
         << mMainRT.deferredScreen.getHeight() << why << applying
         << (changes.mFullSize                         ? std::string_view()
             : mMainRT.deferredScreen.isComplete() ? std::string_view(", halved for want of memory")
                                                   : std::string_view(", built at no size"))
         << "; changed: " << (changed.empty() ? std::string_view("nothing") : changed)
         << "; built: " << built << "; freed: " << (freed.empty() ? std::string_view("nothing") : freed) << "; kept "
         << changes.mKept.count() << "; pooled " << changes.mPooled.count() << ", "
         << (mTransientTargets.stats().mBytes >> 20) << " MiB"
         << (changes.mFailed.any() ? "; failed: " + resource_names(changes.mFailed) : std::string())
         << "; invalidated: " << (invalidated.empty() ? std::string_view("nothing") : invalidated);
    // A window dragged by its edge, or a panel sliding beside the world view, resizes it every frame: a resize that
    // built everything at the size asked is logged at debug level, so the log is not written every frame of it.
    if (resized_as_asked(cause, changes))
    {
        LL_DEBUGS("RenderResources") << line.str() << LL_ENDL;
    }
    else
    {
        LL_INFOS("RenderResources") << line.str() << LL_ENDL;
    }

    return changes.mFullSize;
}

void LLPipeline::programsReloaded()
{
    LL_INFOS("RenderResources") << "Programs reloaded" << applyingChanges(mApplyingChanges)
                                << "; render resources kept; invalidated: nothing" << LL_ENDL;
}

void LLPipeline::createResourceTexture(ALRenderResourcePlan::Id id)
{
    using Id = ALRenderResourcePlan::Id;
    constexpr U32 noise_res = ALRenderResourcePlan::NOISE_SIZE;

    switch (id)
    {
        case Id::Noise:
        {
            std::vector<LLVector3> noise(noise_res * noise_res);
            F32 scaler = gSavedSettings.getF32("RenderDeferredNoise") / 100.f;
            for (LLVector3& texel : noise)
            {
                texel = LLVector3(ll_frand() - 0.5f, ll_frand() - 0.5f, 0.f);
                texel.normVec();
                texel.mV[2] = ll_frand() * scaler + 1.f - scaler / 2.f;
            }
#if LL_DARWIN
            mMetalNoiseMapRG16.resize(noise.size() * 2);
            for (std::size_t index = 0; index < noise.size(); ++index)
            {
                mMetalNoiseMapRG16[index * 2] =
                    ALWaterHeightBake::halfOf(noise[index].mV[0]);
                mMetalNoiseMapRG16[index * 2 + 1] =
                    ALWaterHeightBake::halfOf(noise[index].mV[1]);
            }
            for (const auto* capture_owner :
                 { &mMetalWorldSimpleCapture,
                   &mMetalProbeWorldSimpleCapture })
            {
                if (*capture_owner)
                {
                    (*capture_owner)->base_noise_texture.reset();
                }
            }
#endif
            break;
        }

        case Id::TrueNoise:
        {
            std::vector<F32> noise(noise_res * noise_res * 3);
            for (F32& value : noise)
            {
                value = ll_frand() * 2.0f - 1.0f;
            }
#if LL_DARWIN
            mMetalTrueNoiseMapRGBA16.resize(
                static_cast<std::size_t>(noise_res) * noise_res * 4);
            for (std::size_t texel = 0;
                 texel < static_cast<std::size_t>(noise_res) * noise_res;
                 ++texel)
            {
                for (std::size_t channel = 0; channel < 3; ++channel)
                {
                    mMetalTrueNoiseMapRGBA16[texel * 4 + channel] =
                        ALWaterHeightBake::halfOf(
                            noise[texel * 3 + channel]);
                }
                mMetalTrueNoiseMapRGBA16[texel * 4 + 3] = 0;
            }
            for (const auto* capture_owner :
                 { &mMetalWorldSimpleCapture,
                   &mMetalProbeWorldSimpleCapture })
            {
                if (*capture_owner)
                {
                    (*capture_owner)->legacy_glow_noise_texture.reset();
                }
            }
#endif
            break;
        }

        case Id::SMAAArea:
        case Id::SMAASearch:
        case Id::SMAASample:
            break;

        default:
            break;
    }
}

F32 lerpf(F32 a, F32 b, F32 w)
{
    return a + w * (b - a);
}

void LLPipeline::resetExposureHistory()
{
    // Scale 1 at EV 0: the first frame adapts from no exposure at all. Zero is the lens flare's history: no drive, no
    // instability, no reference luminance.
    if (mExposureMap.isComplete())
    {
        mExposureMap.bindTarget();
        gGL.setClearColor(LLColor4::red);
        mExposureMap.clear();
        gGL.setClearColor(LLColor4::transparent);
        mExposureMap.flush();
    }
    if (mLensFlareState[0].isComplete())
    {
        clearLensFlareState();
    }
#if LL_DARWIN
    ++mMetalExposureHistoryEpoch;
    if (mMetalExposureHistoryEpoch == 0)
    {
        ++mMetalExposureHistoryEpoch;
    }
    mMetalExposureHistoryReady = false;
    for (const auto* capture_owner :
         { &mMetalWorldSimpleCapture,
           &mMetalProbeWorldSimpleCapture })
    {
        if (*capture_owner)
        {
            (*capture_owner)->exposure_target.reset();
            (*capture_owner)->exposure_frame =
                std::numeric_limits<U32>::max();
            (*capture_owner)->exposure_epoch = 0;
        }
    }
#endif
}

LLPipeline::LensDirtConfig LLPipeline::lensDirtConfig(
    bool world_frame) const
{
    static LLCachedControl<F32> strength_setting(
        gSavedSettings, "RenderLensDirtStrength", 0.f);
    static LLCachedControl<F32> bloom_setting(
        gSavedSettings, "RenderLensDirtBloomResponse", 1.f);
    static LLCachedControl<F32> flare_setting(
        gSavedSettings, "RenderLensDirtFlareResponse", 1.f);
    static LLCachedControl<S32> seed_setting(
        gSavedSettings, "RenderLensDirtSeed", 7);
    static LLCachedControl<F32> grime_setting(
        gSavedSettings, "RenderLensDirtGrime", 1.f);
    static LLCachedControl<F32> mote_scale_setting(
        gSavedSettings, "RenderLensDirtMoteScale", 1.f);
    static LLCachedControl<F32> smudge_setting(
        gSavedSettings, "RenderLensDirtSmudge", 1.f);
    static LLCachedControl<S32> scratches_setting(
        gSavedSettings, "RenderLensDirtScratches", 0);
    static LLCachedControl<F32> toe_setting(
        gSavedSettings, "RenderLensDirtToe", 1.6f);
    static LLCachedControl<F32> gain_setting(
        gSavedSettings, "RenderLensDirtGain", 1.f);

    LensDirtConfig config;
    config.strength = llclamp(strength_setting(), 0.f, 2.f);
    config.bloom_response = llclamp(bloom_setting(), 0.f, 2.f);
    config.flare_response = llclamp(flare_setting(), 0.f, 2.f);
    config.requested = config.strength > 0.f;
    config.enabled = config.requested && world_frame &&
        !suppressesLensAndPrintEffects();
    config.plate.width = mRT
        ? llmax(1u, mRT->screen.getWidth()) : 0;
    config.plate.height = mRT
        ? llmax(1u, mRT->screen.getHeight()) : 0;
    config.plate.seed = static_cast<F32>(
        llclamp(seed_setting(), 0, 999));
    config.plate.grime = llclamp(grime_setting(), 0.f, 2.f);
    config.plate.mote_scale = llclamp(
        mote_scale_setting(), 0.5f, 2.f);
    config.plate.smudge = llclamp(smudge_setting(), 0.f, 2.f);
    config.plate.scratches = llclamp(
        scratches_setting(), 0, LENS_DIRT_MAX_LINES);
    config.plate.toe = llclamp(toe_setting(), 0.6f, 4.f);
    config.plate.gain = llclamp(gain_setting(), 0.5f, 2.5f);
    return config;
}

#if LL_DARWIN
namespace
{
    std::unique_ptr<ALMetalTexture> makeMetalToneCurveLut(
        const std::vector<U16>& texels)
    {
        ALMetalDevice* device = getViewerMetalDevice();
        if (!device || texels.size() != ALToneCurveSet::LUT_SIZE * 4u)
        {
            return nullptr;
        }

        std::string error;
        auto texture = alMetalCreateUnormTexture2D(
            *device, ALToneCurveSet::LUT_SIZE, 1, 4, sizeof(U16),
            texels.data(), "Alchemy baked tone curve", &error);
        if (!texture)
        {
            LL_WARNS("Metal")
                << "Could not publish the baked tone curve: "
                << error << LL_ENDL;
        }
        return texture;
    }
}
#endif

void LLPipeline::setupGradingLUT()
{
    mColorGradeLutLoaded = false;
    mCGLutSize = LLVector4();
#if LL_DARWIN
    mMetalCGLut.reset();
    ALMetalDevice* metal_device = getViewerMetalDevice();
#endif

    std::string lut_name = gSavedSettings.getString("RenderColorGradeLUT");
    if (gSavedSettings.getBOOL("RenderColorGrade") && !lut_name.empty())
    {
        std::string lut_path = gDirUtilp->getExpandedFilename(LL_PATH_USER_SETTINGS, "colorlut", lut_name);

        if (!LLFile::isfile(lut_path))
        {
            lut_path = gDirUtilp->getExpandedFilename(LL_PATH_APP_SETTINGS, "colorlut", lut_name);
        }

        if (LLFile::isfile(lut_path))
        {
            std::string temp_exten = gDirUtilp->getExtension(lut_path);
            bool decode_success = false;
            LLPointer<LLImageRaw> raw_image;
            bool flip_green = true;
            bool swap_bluegreen = true;
            if (temp_exten == "cube")
            {
                LutCube lutCube(lut_path);
                if (lutCube.colorCube.empty())
                {
                    LL_WARNS() << "Failed to decode color grading LUT: " << lut_path << LL_ENDL;
                    return;
                }

#if LL_DARWIN
                const U32 max_lut_dimension = metal_device
                    ? metal_device->info().max_texture_2d_dimension : 0;
#else
                LL_WARNS("Metal")
                    << "Color grading LUTs require the native Metal renderer."
                    << LL_ENDL;
                return;
#endif
                if (static_cast<U32>(lutCube.size) > max_lut_dimension)
                {
                    LL_WARNS() << "Color LUT of side " << lutCube.size << " exceeds the maximum texture size at path "
                               << lut_path << LL_ENDL;
                    return;
                }

                // The .cube path does not go through LLImageRaw: that class is
                // 8 bits per channel, and flattening a cube of floats to 256
                // levels before the hardware interpolates between them is where
                // LUT banding comes from. LutCube already lays its entries out
                // with x varying fastest, which is the order both volume
                // backends consume, and a cube needs neither of the axis fixups
                // an image strip does -- hence the two zeroes below.
#if LL_DARWIN
                std::string metal_error;
                mMetalCGLut = alMetalCreateUnormVolumeArray(
                    *metal_device, lutCube.size, 4, sizeof(U16),
                    lutCube.colorCube.data(), "Alchemy color-grade LUT",
                    &metal_error);
                if (!mMetalCGLut)
                {
                    LL_WARNS("Metal")
                        << "Failed to allocate native color grading LUT: "
                        << metal_error << LL_ENDL;
                    return;
                }
#endif
                mCGLutSize = LLVector4((F32)lutCube.size, 0.f, 0.f);
                mColorGradeLutLoaded = true;
                return;
            }
            else
            {
                enum class ELutExt
                {
                    EXT_IMG_TGA = 0,
                    EXT_IMG_PNG,
                    EXT_IMG_JPEG,
                    EXT_IMG_BMP,
                    EXT_IMG_WEBP,
                    EXT_NONE
                };

                ELutExt extension = ELutExt::EXT_NONE;
                if (temp_exten == "tga")
                {
                    extension = ELutExt::EXT_IMG_TGA;
                }
                else if (temp_exten == "png")
                {
                    extension = ELutExt::EXT_IMG_PNG;
                }
                else if (temp_exten == "jpg" || temp_exten == "jpeg")
                {
                    extension = ELutExt::EXT_IMG_JPEG;
                }
                else if (temp_exten == "bmp")
                {
                    extension = ELutExt::EXT_IMG_BMP;
                }
                else if (temp_exten == "webp")
                {
                    extension = ELutExt::EXT_IMG_WEBP;
                }

                raw_image = new LLImageRaw;

                switch (extension)
                {
                    default:
                        break;
                    case ELutExt::EXT_IMG_TGA:
                    {
                        LLPointer<LLImageTGA> tga_image = new LLImageTGA;
                        if (tga_image->load(lut_path) && tga_image->decode(raw_image, 0.0f))
                        {
                            decode_success = true;
                        }
                        break;
                    }
                    case ELutExt::EXT_IMG_PNG:
                    {
                        LLPointer<LLImagePNG> png_image = new LLImagePNG;
                        if (png_image->load(lut_path) && png_image->decode(raw_image, 0.0f))
                        {
                            decode_success = true;
                        }
                        break;
                    }
                    case ELutExt::EXT_IMG_JPEG:
                    {
                        LLPointer<LLImageJPEG> jpg_image = new LLImageJPEG;
                        if (jpg_image->load(lut_path) && jpg_image->decode(raw_image, 0.0f))
                        {
                            decode_success = true;
                        }
                        break;
                    }
                    case ELutExt::EXT_IMG_BMP:
                    {
                        LLPointer<LLImageBMP> bmp_image = new LLImageBMP;
                        if (bmp_image->load(lut_path) && bmp_image->decode(raw_image, 0.0f))
                        {
                            decode_success = true;
                        }
                        break;
                    }
                    case ELutExt::EXT_IMG_WEBP:
                    {
                        LLPointer<LLImageWebP> webp_image = new LLImageWebP;
                        if (webp_image->load(lut_path) && webp_image->decode(raw_image, 0.0f))
                        {
                            decode_success = true;
                        }
                        break;
                    }
                }
            }

            if (decode_success && raw_image)
            {
                switch (raw_image->getComponents())
                {
                    case 3:
                        break;
                    case 4:
                        break;
                    default:
                    {
                        LL_WARNS() << "Color LUT has invalid number of color components: " << raw_image->getComponents() << LL_ENDL;
                        return;
                    }
                };

                S32 image_height = raw_image->getHeight();
                S32 image_width  = raw_image->getWidth();
#if LL_DARWIN
                const U32 max_lut_dimension = metal_device
                    ? metal_device->info().max_texture_2d_dimension : 0;
#else
                LL_WARNS("Metal")
                    << "Color grading LUTs require the native Metal renderer."
                    << LL_ENDL;
                return;
#endif
                if ((image_height > 0 && static_cast<U32>(image_height) <= max_lut_dimension) // within dimension limit
                    && ((image_height * image_height) == image_width))                 // width is height * height
                {
                    // The LUT is a cube of side image_height, stored in the raw image
                    // as image_height slices laid out horizontally.
#if LL_DARWIN
                    std::string metal_error;
                    mMetalCGLut = alMetalCreateUnormVolumeArray(
                        *metal_device, image_height, raw_image->getComponents(),
                        sizeof(U8), raw_image->getData(),
                        "Alchemy color-grade LUT", &metal_error);
                    if (!mMetalCGLut)
                    {
                        LL_WARNS("Metal")
                            << "Failed to allocate native color grading LUT: "
                            << metal_error << LL_ENDL;
                        return;
                    }
#endif
                    mCGLutSize = LLVector4(
                        (F32)image_height, (F32)flip_green,
                        (F32)swap_bluegreen);
                    mColorGradeLutLoaded = true;
                }
                else
                {
                    LL_WARNS() << "Color LUT is invalid width or height: " << image_height << " x " << image_width << " at path "
                                << lut_path << LL_ENDL;
                }
            }
            else
            {
                LL_WARNS() << "Failed to decode color grading LUT: " << lut_path << LL_ENDL;
            }
        }
    }
}


// Runs lazily on the way to native world capture, with colorCorrect ensuring
// publication on frames with no capture, rather than from the settings signal.
// Resource release drops the published texture and only a bake on a draw path
// can refill it. A Look
// apply or an undo writes four curve settings in a row and a graph drag commits
// per mouse move, so one bake per rendered frame is the natural rate and the
// dirty flag coalesces the rest. Publication performs no GL work.
void LLPipeline::bakeToneCurveLut()
{
    LL_PROFILE_ZONE_SCOPED;

    // Once per change, so a name lookup is fine and no cached control is
    // needed. controlExists keeps a build whose settings lag behind from
    // asserting inside LLControlGroup.
    ALToneCurveSet curves;
    for (S32 c = 0; c < ALToneCurveSet::CH_COUNT; ++c)
    {
        const ALToneCurveSet::EChannel channel = static_cast<ALToneCurveSet::EChannel>(c);
        const char* name = ALToneCurveSet::settingName(channel);
        if (gSavedSettings.controlExists(name))
        {
            curves.setCurveFromLLSD(channel, gSavedSettings.getLLSD(name));
        }
    }

    mToneCurveIdentity = curves.isIdentity();
    if (mToneCurveIdentity)
    {
        mToneCurveLutLoaded = false;
        mToneCurveLutDirty = false;
#if LL_DARWIN
        mMetalToneCurveLut.reset();
#endif
        // Identity never reaches either shader, so stale non-Darwin texels are
        // harmless and Darwin can release its native texture immediately.
        return;
    }

    std::vector<U16> texels;
    curves.bake(texels, ALToneCurveSet::LUT_SIZE);
#if LL_DARWIN
    mMetalToneCurveLut = makeMetalToneCurveLut(texels);
    mToneCurveLutLoaded = mMetalToneCurveLut != nullptr;
    // A failed publication is unavailable and remains dirty so a later frame
    // can retry after a transient device or allocation failure.
    mToneCurveLutDirty = !mToneCurveLutLoaded;
#else
    // This fork ships only the native Apple renderer. Keep an unsupported
    // source configuration fail-closed rather than retaining a second backend.
    mToneCurveLutLoaded = false;
    mToneCurveLutDirty = false;
#endif
}

